### 5.3 Authentication Controller

**src/controllers/auth.controller.js:**
```javascript
const authService = require('../services/auth.service');
const asyncHandler = require('../utils/asyncHandler');
const ApiResponse = require('../utils/ApiResponse');

/**
 * Register new user
 */
exports.register = asyncHandler(async (req, res) => {
  const result = await authService.register(req.body);

  res.status(201).json(
    new ApiResponse(
      201,
      result,
      'User registered successfully. Please verify your email.'
    )
  );
});

/**
 * Login user
 */
exports.login = asyncHandler(async (req, res) => {
  const { email, password } = req.body;
  const ipAddress = req.ip;
  const userAgent = req.get('user-agent');

  const result = await authService.login(email, password, ipAddress, userAgent);

  // Set refresh token in HTTP-only cookie
  res.cookie('refreshToken', result.tokens.refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
  });

  res.status(200).json(
    new ApiResponse(
      200,
      {
        user: result.user,
        accessToken: result.tokens.accessToken,
      },
      'Login successful'
    )
  );
});

/**
 * Logout user
 */
exports.logout = asyncHandler(async (req, res) => {
  const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

  if (refreshToken) {
    await authService.logout(refreshToken);
  }

  res.clearCookie('refreshToken');

  res.status(200).json(
    new ApiResponse(200, null, 'Logout successful')
  );
});

/**
 * Refresh access token
 */
exports.refreshToken = asyncHandler(async (req, res) => {
  const refreshToken = req.cookies.refreshToken || req.body.refreshToken;
  const ipAddress = req.ip;
  const userAgent = req.get('user-agent');

  const tokens = await authService.refreshAccessToken(
    refreshToken,
    ipAddress,
    userAgent
  );

  // Set new refresh token in cookie
  res.cookie('refreshToken', tokens.refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 30 * 24 * 60 * 60 * 1000,
  });

  res.status(200).json(
    new ApiResponse(
      200,
      { accessToken: tokens.accessToken },
      'Token refreshed successfully'
    )
  );
});

/**
 * Verify email
 */
exports.verifyEmail = asyncHandler(async (req, res) => {
  const { token } = req.params;

  const user = await authService.verifyEmail(token);

  res.status(200).json(
    new ApiResponse(200, { user }, 'Email verified successfully')
  );
});

/**
 * Forgot password
 */
exports.forgotPassword = asyncHandler(async (req, res) => {
  const { email } = req.body;

  const result = await authService.forgotPassword(email);

  res.status(200).json(
    new ApiResponse(200, null, result.message)
  );
});

/**
 * Reset password
 */
exports.resetPassword = asyncHandler(async (req, res) => {
  const { token } = req.params;
  const { password } = req.body;

  const user = await authService.resetPassword(token, password);

  res.status(200).json(
    new ApiResponse(200, { user }, 'Password reset successfully')
  );
});

/**
 * Change password
 */
exports.changePassword = asyncHandler(async (req, res) => {
  const { currentPassword, newPassword } = req.body;

  const user = await authService.changePassword(
    req.user.id,
    currentPassword,
    newPassword
  );

  res.status(200).json(
    new ApiResponse(200, { user }, 'Password changed successfully')
  );
});
```

### 5.4 OAuth Integration (Optional)

**src/services/oauth.service.js:**
```javascript
const axios = require('axios');
const config = require('../config/environment');
const User = require('../models/user.model');
const authService = require('./auth.service');
const ApiError = require('../utils/ApiError');

class OAuthService {
  /**
   * Google OAuth login
   */
  static async googleLogin(code, ipAddress, userAgent) {
    try {
      // Exchange code for tokens
      const tokenResponse = await axios.post(
        'https://oauth2.googleapis.com/token',
        {
          code,
          client_id: config.oauth.google.clientId,
          client_secret: config.oauth.google.clientSecret,
          redirect_uri: config.oauth.google.redirectUri,
          grant_type: 'authorization_code',
        }
      );

      const { access_token } = tokenResponse.data;

      // Get user info
      const userResponse = await axios.get(
        'https://www.googleapis.com/oauth2/v2/userinfo',
        {
          headers: { Authorization: `Bearer ${access_token}` },
        }
      );

      const { email, name, picture, verified_email } = userResponse.data;

      // Find or create user
      let user = await User.findByEmail(email);

      if (!user) {
        user = await User.create({
          email,
          username: email.split('@')[0],
          firstName: name.split(' ')[0],
          lastName: name.split(' ').slice(1).join(' '),
          isEmailVerified: verified_email,
          password: crypto.randomBytes(32).toString('hex'), // Random password
        });
      }

      // Generate tokens
      const tokens = await authService.generateTokenPair(
        user.id,
        ipAddress,
        userAgent
      );

      return {
        user: User.sanitize(user),
        tokens,
      };
    } catch (error) {
      throw new ApiError(400, 'Google authentication failed');
    }
  }
}

module.exports = OAuthService;
```

