## 6. Validation

### 6.1 Request Validation Schemas

**src/validators/auth.validator.js:**
```javascript
const Joi = require('joi');

const authValidator = {
  register: Joi.object({
    body: Joi.object({
      email: Joi.string()
        .email()
        .required()
        .messages({
          'string.email': 'Please provide a valid email',
          'any.required': 'Email is required',
        }),
      username: Joi.string()
        .alphanum()
        .min(3)
        .max(30)
        .required()
        .messages({
          'string.alphanum': 'Username must contain only alphanumeric characters',
          'string.min': 'Username must be at least 3 characters',
          'string.max': 'Username cannot exceed 30 characters',
          'any.required': 'Username is required',
        }),
      password: Joi.string()
        .min(8)
        .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
        .required()
        .messages({
          'string.min': 'Password must be at least 8 characters',
          'string.pattern.base': 'Password must contain uppercase, lowercase, number, and special character',
          'any.required': 'Password is required',
        }),
      firstName: Joi.string().max(100),
      lastName: Joi.string().max(100),
    }),
  }),

  login: Joi.object({
    body: Joi.object({
      email: Joi.string().email().required(),
      password: Joi.string().required(),
    }),
  }),

  refresh: Joi.object({
    body: Joi.object({
      refreshToken: Joi.string().required(),
    }),
  }),

  forgotPassword: Joi.object({
    body: Joi.object({
      email: Joi.string().email().required(),
    }),
  }),

  resetPassword: Joi.object({
    body: Joi.object({
      token: Joi.string().required(),
      password: Joi.string()
        .min(8)
        .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
        .required(),
    }),
  }),

  changePassword: Joi.object({
    body: Joi.object({
      currentPassword: Joi.string().required(),
      newPassword: Joi.string()
        .min(8)
        .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
        .required()
        .invalid(Joi.ref('currentPassword'))
        .messages({
          'any.invalid': 'New password must be different from current password',
        }),
    }),
  }),
};

module.exports = authValidator;
```

**src/validators/user.validator.js:**
```javascript
const Joi = require('joi');

const userValidator = {
  getUserById: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
  }),

  createUser: Joi.object({
    body: Joi.object({
      email: Joi.string().email().required(),
      username: Joi.string().alphanum().min(3).max(30).required(),
      password: Joi.string()
        .min(8)
        .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
        .required(),
      firstName: Joi.string().max(100),
      lastName: Joi.string().max(100),
      role: Joi.string().valid('user', 'admin', 'manager').default('user'),
    }),
  }),

  updateUser: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
    body: Joi.object({
      email: Joi.string().email(),
      username: Joi.string().alphanum().min(3).max(30),
      firstName: Joi.string().max(100),
      lastName: Joi.string().max(100),
      role: Joi.string().valid('user', 'admin', 'manager'),
      isActive: Joi.boolean(),
    }).min(1),
  }),

  patchUser: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
    body: Joi.object({
      email: Joi.string().email(),
      username: Joi.string().alphanum().min(3).max(30),
      firstName: Joi.string().max(100),
      lastName: Joi.string().max(100),
    }).min(1),
  }),

  deleteUser: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
  }),
};

module.exports = userValidator;
```

**src/validators/product.validator.js:**
```javascript
const Joi = require('joi');

const productValidator = {
  getProducts: Joi.object({
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      sort: Joi.string().valid(
        'name',
        '-name',
        'price',
        '-price',
        'createdAt',
        '-createdAt'
      ).default('-createdAt'),
      search: Joi.string().max(255),
      status: Joi.string().valid('active', 'inactive', 'discontinued'),
      minPrice: Joi.number().min(0),
      maxPrice: Joi.number().min(0),
    }),
  }),

  getProductById: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
  }),

  createProduct: Joi.object({
    body: Joi.object({
      name: Joi.string().max(255).required(),
      slug: Joi.string()
        .pattern(/^[a-z0-9-]+$/)
        .max(255)
        .required()
        .messages({
          'string.pattern.base': 'Slug must contain only lowercase letters, numbers, and hyphens',
        }),
      description: Joi.string().allow(''),
      price: Joi.number().positive().precision(2).required(),
      stock: Joi.number().integer().min(0).default(0),
      sku: Joi.string().max(100),
      status: Joi.string().valid('active', 'inactive', 'discontinued').default('active'),
      categoryId: Joi.number().integer().positive(),
    }),
  }),

  updateProduct: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
    body: Joi.object({
      name: Joi.string().max(255),
      slug: Joi.string().pattern(/^[a-z0-9-]+$/).max(255),
      description: Joi.string().allow(''),
      price: Joi.number().positive().precision(2),
      stock: Joi.number().integer().min(0),
      sku: Joi.string().max(100),
      status: Joi.string().valid('active', 'inactive', 'discontinued'),
      categoryId: Joi.number().integer().positive(),
    }).min(1),
  }),

  deleteProduct: Joi.object({
    params: Joi.object({
      id: Joi.number().integer().positive().required(),
    }),
  }),
};

module.exports = productValidator;
```

