const Joi = require('joi');

/**
 * Custom phone number validation
 */
const phoneNumber = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Please provide a valid phone number',
  });

/**
 * Custom date validation (must be in future)
 */
const futureDate = Joi.date()
  .greater('now')
  .messages({
    'date.greater': 'Date must be in the future',
  });

/**
 * Custom URL validation
 */
const url = Joi.string()
  .uri({ scheme: ['http', 'https'] })
  .messages({
    'string.uri': 'Please provide a valid URL',
  });

/**
 * Custom file upload validation
 */
const fileUpload = Joi.object({
  filename: Joi.string().required(),
  mimetype: Joi.string()
    .valid('image/jpeg', 'image/png', 'image/gif', 'application/pdf')
    .required(),
  size: Joi.number().max(5 * 1024 * 1024).required(), // 5MB max
});

/**
 * Custom credit card validation
 */
const creditCard = Joi.string()
  .creditCard()
  .messages({
    'string.creditCard': 'Please provide a valid credit card number',
  });

/**
 * Custom password strength validation
 */
const strongPassword = Joi.string()
  .min(8)
  .max(128)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .messages({
    'string.min': 'Password must be at least 8 characters',
    'string.max': 'Password cannot exceed 128 characters',
    'string.pattern.base': 'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character',
  });

/**
 * Custom array of unique values
 */
const uniqueArray = (itemSchema) => {
  return Joi.array()
    .items(itemSchema)
    .unique()
    .messages({
      'array.unique': 'Array must contain unique values',
    });
};

module.exports = {
  phoneNumber,
  futureDate,
  url,
  fileUpload,
  creditCard,
  strongPassword,
  uniqueArray,
};
```

