{"runType":"STIGMERGY","runId":"c8e5cfb5-574b-4ffc-b0ad-7d0a3823cf00-STIGMERGY-1","contentTransferTokens":40526,"mechanismOverheadTokens":25395,"coordinationInstructionsTokens":8100,"taskReasoningTokens":76008,"systemIdentityTokens":0,"interAgentTokens":74021,"agentAutonomousTokens":76008,"totalTokens":150029,"cachedTokens":0,"effectiveTokens":150029,"cacheHitRate":0,"wallClockMs":625709,"agentCount":10,"apiCallCount":36,"success":true,"output":"## Section 10: Monitoring

Monitoring is the final critical piece of a production-ready REST API. After deploying your application (Section 9), comprehensive monitoring ensures reliability, performance, and rapid incident response. This section covers the three pillars of observability: metrics, logs, and traces.

### 10.1 Observability Strategy

**The Three Pillars:**

```typescript
// src/monitoring/observability.ts
export interface ObservabilityPillars {
  metrics: {
    // What is happening? (Quantitative data)
    requestRate: number;
    errorRate: number;
    latency: number;
    resourceUsage: ResourceMetrics;
  };
  logs: {
    // Why is it happening? (Event records)
    level: 'error' | 'warn' | 'info' | 'debug';
    message: string;
    context: Record<string, any>;
    timestamp: Date;
  };
  traces: {
    // Where is it happening? (Request flow)
    traceId: string;
    spanId: string;
    parentSpanId?: string;
    duration: number;
  };
}
```

### 10.2 Application Performance Monitoring (APM)

**APM Tool Comparison:**

| Tool | Best For | Pricing | Key Features |
|------|----------|---------|--------------|
| New Relic | Enterprise | $$$ | Full-stack, AI insights |
| Datadog | DevOps teams | $$$ | Infrastructure + APM |
| Elastic APM | Open source | $ | Self-hosted, ELK integration |
| Sentry | Error tracking | $$ | Developer-friendly |

**Implementing New Relic:**

```typescript
// src/monitoring/apm.ts
import newrelic from 'newrelic';

export const trackTransaction = (name: string, handler: Function) => {
  return newrelic.startBackgroundTransaction(name, async () => {
    try {
      return await handler();
    } catch (error) {
      newrelic.noticeError(error);
      throw error;
    }
  });
};

// Custom instrumentation
export const recordMetric = (name: string, value: number) => {
  newrelic.recordMetric(`Custom/${name}`, value);
};

// Track business metrics
export const trackOrderCreated = (orderValue: number) => {
  recordMetric('Orders/Created', 1);
  recordMetric('Orders/Revenue', orderValue);
};
```

### 10.3 Metrics Collection with Prometheus

**Setting up Prometheus metrics:**

```typescript
// src/monitoring/metrics.ts
import promClient from 'prom-client';
import { Request, Response, NextFunction } from 'express';

// Create a Registry
export const register = new promClient.Registry();

// Add default metrics (CPU, memory, etc.)
promClient.collectDefaultMetrics({ register });

// Custom metrics
export const httpRequestDuration = new promClient.Histogram({
  name: 'http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.1, 0.5, 1, 2, 5]
});

export const httpRequestTotal = new promClient.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

export const activeConnections = new promClient.Gauge({
  name: 'active_connections',
  help: 'Number of active connections'
});

export const databaseQueryDuration = new promClient.Histogram({
  name: 'database_query_duration_seconds',
  help: 'Duration of database queries',
  labelNames: ['operation', 'table'],
  buckets: [0.01, 0.05, 0.1, 0.5, 1]
});

// Register metrics
register.registerMetric(httpRequestDuration);
register.registerMetric(httpRequestTotal);
register.registerMetric(activeConnections);
register.registerMetric(databaseQueryDuration);

// Metrics middleware
export const metricsMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  const start = Date.now();

  activeConnections.inc();

  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route?.path || req.path;

    httpRequestDuration
      .labels(req.method, route, res.statusCode.toString())
      .observe(duration);

    httpRequestTotal
      .labels(req.method, route, res.statusCode.toString())
      .inc();

    activeConnections.dec();
  });

  next();
};

// Metrics endpoint
export const metricsEndpoint = async (req: Request, res: Response) => {
  res.set('Content-Type', register.contentType);
  res.end(await register.metrics());
};
```

**Integrate metrics in app.ts:**

```typescript
// src/app.ts
import { metricsMiddleware, metricsEndpoint } from './monitoring/metrics';

app.use(metricsMiddleware);

// Metrics endpoint for Prometheus scraping
app.get('/metrics', metricsEndpoint);
```

### 10.4 Enhanced Health Checks

**Comprehensive health check implementation:**

```typescript
// src/monitoring/health.ts
import { Request, Response } from 'express';
import { prisma } from '../config/database'; // From Section 4

interface HealthCheck {
  status: 'healthy' | 'degraded' | 'unhealthy';
  timestamp: string;
  uptime: number;
  checks: {
    database: CheckResult;
    memory: CheckResult;
    disk: CheckResult;
    dependencies: CheckResult;
  };
}

interface CheckResult {
  status: 'pass' | 'fail';
  responseTime?: number;
  details?: any;
}

// Liveness probe - is the app running?
export const livenessProbe = (req: Request, res: Response) => {
  res.status(200).json({
    status: 'alive',
    timestamp: new Date().toISOString()
  });
};

// Readiness probe - is the app ready to serve traffic?
export const readinessProbe = async (req: Request, res: Response) => {
  const checks: HealthCheck['checks'] = {
    database: await checkDatabase(),
    memory: checkMemory(),
    disk: checkDisk(),
    dependencies: await checkDependencies()
  };

  const allHealthy = Object.values(checks).every(c => c.status === 'pass');
  const status = allHealthy ? 'healthy' : 'unhealthy';

  const health: HealthCheck = {
    status,
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    checks
  };

  res.status(allHealthy ? 200 : 503).json(health);
};

async function checkDatabase(): Promise<CheckResult> {
  const start = Date.now();
  try {
    await prisma.$queryRaw`SELECT 1`;
    return {
      status: 'pass',
      responseTime: Date.now() - start
    };
  } catch (error) {
    return {
      status: 'fail',
      details: error.message
    };
  }
}

function checkMemory(): CheckResult {
  const usage = process.memoryUsage();
  const heapUsedPercent = (usage.heapUsed / usage.heapTotal) * 100;

  return {
    status: heapUsedPercent < 90 ? 'pass' : 'fail',
    details: {
      heapUsed: `${Math.round(usage.heapUsed / 1024 / 1024)}MB`,
      heapTotal: `${Math.round(usage.heapTotal / 1024 / 1024)}MB`,
      percentage: `${heapUsedPercent.toFixed(2)}%`
    }
  };
}

function checkDisk(): CheckResult {
  // Simplified - in production use a library like 'diskusage'
  return { status: 'pass' };
}

async function checkDependencies(): Promise<CheckResult> {
  // Check external services (Redis, message queues, etc.)
  try {
    // Example: await redis.ping();
    return { status: 'pass' };
  } catch (error) {
    return { status: 'fail', details: error.message };
  }
}
```

### 10.5 Structured Logging with Winston

**Enhanced logging building on Section 3:**

```typescript
// src/monitoring/logger.ts
import winston from 'winston';
import { ElasticsearchTransport } from 'winston-elasticsearch';

const esTransportOpts = {
  level: 'info',
  clientOpts: {
    node: process.env.ELASTICSEARCH_URL,
    auth: {
      username: process.env.ELASTICSEARCH_USER,
      password: process.env.ELASTICSEARCH_PASSWORD
    }
  },
  index: 'api-logs'
};

export const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: {
    service: 'rest-api',
    environment: process.env.NODE_ENV,
    version: process.env.APP_VERSION
  },
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      maxsize: 10485760, // 10MB
      maxFiles: 5
    }),
    new winston.transports.File({
      filename: 'logs/combined.log',
      maxsize: 10485760,
      maxFiles: 10
    })
  ]
});

// Add Elasticsearch in production
if (process.env.NODE_ENV === 'production') {
  logger.add(new ElasticsearchTransport(esTransportOpts));
}

// Correlation ID middleware
export const correlationIdMiddleware = (req, res, next) => {
  req.correlationId = req.headers['x-correlation-id'] || 
                      req.headers['x-request-id'] || 
                      generateId();
  res.setHeader('X-Correlation-ID', req.correlationId);
  next();
};

// Context-aware logging
export const logWithContext = (level: string, message: string, meta: any) => {
  logger.log(level, message, {
    ...meta,
    correlationId: meta.correlationId,
    userId: meta.userId,
    endpoint: meta.endpoint,
    method: meta.method
  });
};
```

### 10.6 Distributed Tracing with OpenTelemetry

**Implementing distributed tracing:**

```typescript
// src/monitoring/tracing.ts
import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';

const jaegerExporter = new JaegerExporter({
  endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces'
});

export const sdk = new NodeSDK({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'rest-api',
    [SemanticResourceAttributes.SERVICE_VERSION]: process.env.APP_VERSION
  }),
  traceExporter: jaegerExporter,
  instrumentations: [
    getNodeAutoInstrumentations({
      '@opentelemetry/instrumentation-fs': { enabled: false }
    })
  ]
});

// Custom span creation
import { trace, SpanStatusCode } from '@opentelemetry/api';

export const createSpan = (name: string, fn: Function) => {
  const tracer = trace.getTracer('rest-api');

  return tracer.startActiveSpan(name, async (span) => {
    try {
      const result = await fn();
      span.setStatus({ code: SpanStatusCode.OK });
      return result;
    } catch (error) {
      span.setStatus({
        code: SpanStatusCode.ERROR,
        message: error.message
      });
      span.recordException(error);
      throw error;
    } finally {
      span.end();
    }
  });
};

// Usage in services
export const getUserOrders = async (userId: string) => {
  return createSpan('getUserOrders', async () => {
    const span = trace.getActiveSpan();
    span?.setAttribute('user.id', userId);

    // Database query from Section 4
    const orders = await prisma.order.findMany({
      where: { userId }
    });

    span?.setAttribute('orders.count', orders.length);
    return orders;
  });
};
```

### 10.7 Real-Time Alerting

**Alert configuration:**

```typescript
// src/monitoring/alerts.ts
import axios from 'axios';

interface Alert {
  severity: 'critical' | 'warning' | 'info';
  title: string;
  description: string;
  service: string;
  metadata?: Record<string, any>;
}

export class AlertManager {
  private pagerDutyKey: string;
  private slackWebhook: string;

  constructor() {
    this.pagerDutyKey = process.env.PAGERDUTY_KEY;
    this.slackWebhook = process.env.SLACK_WEBHOOK_URL;
  }

  async sendAlert(alert: Alert) {
    if (alert.severity === 'critical') {
      await this.sendToPagerDuty(alert);
    }
    await this.sendToSlack(alert);
    await this.logAlert(alert);
  }

  private async sendToPagerDuty(alert: Alert) {
    try {
      await axios.post('https://events.pagerduty.com/v2/enqueue', {
        routing_key: this.pagerDutyKey,
        event_action: 'trigger',
        payload: {
          summary: alert.title,
          severity: alert.severity,
          source: alert.service,
          custom_details: alert.metadata
        }
      });
    } catch (error) {
      logger.error('Failed to send PagerDuty alert', { error });
    }
  }

  private async sendToSlack(alert: Alert) {
    const color = {
      critical: '#FF0000',
      warning: '#FFA500',
      info: '#0000FF'
    }[alert.severity];

    try {
      await axios.post(this.slackWebhook, {
        attachments: [{
          color,
          title: alert.title,
          text: alert.description,
          fields: Object.entries(alert.metadata || {}).map(([key, value]) => ({
            title: key,
            value: String(value),
            short: true
          })),
          footer: alert.service,
          ts: Math.floor(Date.now() / 1000)
        }]
      });
    } catch (error) {
      logger.error('Failed to send Slack alert', { error });
    }
  }

  private async logAlert(alert: Alert) {
    logger.warn('Alert triggered', alert);
  }
}

