### 6.2 Authentication Validation Schemas

**src/validators/auth.validator.js:**
```javascript
const Joi = require('joi');

/**
 * Register validation
 */
exports.register = Joi.object({
  body: Joi.object({
    email: Joi.string().email().required(),
    username: Joi.string().alphanum().min(3).max(30).required(),
    password: Joi.string()
      .min(8)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required(),
    confirmPassword: Joi.string().valid(Joi.ref('password')).required().messages({
      'any.only': 'Passwords do not match',
    }),
    firstName: Joi.string().min(2).max(100),
    lastName: Joi.string().min(2).max(100),
  }),
});

/**
 * Login validation
 */
exports.login = Joi.object({
  body: Joi.object({
    email: Joi.string().email().required(),
    password: Joi.string().required(),
  }),
});

/**
 * Refresh token validation
 */
exports.refresh = Joi.object({
  body: Joi.object({
    refreshToken: Joi.string().required(),
  }),
});

/**
 * Forgot password validation
 */
exports.forgotPassword = Joi.object({
  body: Joi.object({
    email: Joi.string().email().required(),
  }),
});

/**
 * Reset password validation
 */
exports.resetPassword = Joi.object({
  params: Joi.object({
    token: Joi.string().required(),
  }),
  body: Joi.object({
    password: Joi.string()
      .min(8)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required(),
    confirmPassword: Joi.string().valid(Joi.ref('password')).required(),
  }),
});

/**
 * Change password validation
 */
exports.changePassword = Joi.object({
  body: Joi.object({
    currentPassword: Joi.string().required(),
    newPassword: Joi.string()
      .min(8)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required()
      .invalid(Joi.ref('currentPassword'))
      .messages({
        'any.invalid': 'New password must be different from current password',
      }),
    confirmPassword: Joi.string().valid(Joi.ref('newPassword')).required(),
  }),
});
```

### 6.3 Product Validation Schemas

**src/validators/product.validator.js:**
```javascript
const Joi = require('joi');

/**
 * Get products validation
 */
exports.getProducts = Joi.object({
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    sortBy: Joi.string().valid('name', 'price', 'created_at', 'stock').default('created_at'),
    sortOrder: Joi.string().valid('asc', 'desc').default('desc'),
    category: Joi.string(),
    minPrice: Joi.number().min(0),
    maxPrice: Joi.number().min(0),
    isActive: Joi.boolean(),
    isFeatured: Joi.boolean(),
    search: Joi.string().max(100),
  }),
});

/**
 * Get product by ID validation
 */
exports.getProductById = Joi.object({
  params: Joi.object({
    id: Joi.string().uuid().required(),
  }),
});

/**
 * Create product validation
 */
exports.createProduct = Joi.object({
  body: Joi.object({
    name: Joi.string().min(3).max(255).required(),
    description: Joi.string().max(5000),
    price: Joi.number().positive().precision(2).required(),
    comparePrice: Joi.number().positive().precision(2).greater(Joi.ref('price')).messages({
      'number.greater': 'Compare price must be greater than regular price',
    }),
    stock: Joi.number().integer().min(0).default(0),
    sku: Joi.string().max(100),
    category: Joi.string().max(100).required(),
    images: Joi.array().items(Joi.string().uri()).max(10),
    attributes: Joi.object().pattern(
      Joi.string(),
      Joi.alternatives().try(Joi.string(), Joi.number(), Joi.boolean())
    ),
    isActive: Joi.boolean().default(true),
    isFeatured: Joi.boolean().default(false),
  }),
});

/**
 * Update product validation
 */
exports.updateProduct = Joi.object({
  params: Joi.object({
    id: Joi.string().uuid().required(),
  }),
  body: Joi.object({
    name: Joi.string().min(3).max(255),
    description: Joi.string().max(5000),
    price: Joi.number().positive().precision(2),
    comparePrice: Joi.number().positive().precision(2),
    stock: Joi.number().integer().min(0),
    sku: Joi.string().max(100),
    category: Joi.string().max(100),
    images: Joi.array().items(Joi.string().uri()).max(10),
    attributes: Joi.object(),
    isActive: Joi.boolean(),
    isFeatured: Joi.boolean(),
  }).min(1),
});

/**
 * Delete product validation
 */
exports.deleteProduct = Joi.object({
  params: Joi.object({
    id: Joi.string().uuid().required(),
  }),
});

/**
 * Search products validation
 */
exports.searchProducts = Joi.object({
  query: Joi.object({
    q: Joi.string().min(2).max(100).required(),
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
  }),
});

/**
 * Get by category validation
 */
exports.getByCategory = Joi.object({
  params: Joi.object({
    category: Joi.string().required(),
  }),
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
  }),
});
```

### 6.4 Custom Validation Rules

**src/validators/custom.validator.js:**
```javascript
const Joi = require('joi');

/**
 * Custom validation for UUID v4
 */
exports.uuidv4 = Joi.string().guid({ version: 'uuidv4' });

/**
 * Custom validation for strong password
 */
exports.strongPassword = Joi.string()
  .min(8)
  .max(128)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .messages({
    'string.pattern.base': 'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character',
  });

/**
 * Custom validation for phone number
 */
exports.phoneNumber = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Please provide a valid phone number in E.164 format',
  });

/**
 * Custom validation for URL
 */
exports.url = Joi.string().uri().messages({
  'string.uri': 'Please provide a valid URL',
});

/**
 * Custom validation for date range
 */
exports.dateRange = Joi.object({
  startDate: Joi.date().iso().required(),
  endDate: Joi.date().iso().min(Joi.ref('startDate')).required().messages({
    'date.min': 'End date must be after start date',
  }),
});

/**
 * Custom validation for pagination
 */
exports.pagination = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
});

/**
 * Custom validation for sorting
 */
exports.sorting = (allowedFields) => {
  return Joi.object({
    sortBy: Joi.string().valid(...allowedFields).default(allowedFields[0]),
    sortOrder: Joi.string().valid('asc', 'desc').default('desc'),
  });
};

/**
 * Custom validation for file upload
 */
exports.fileUpload = Joi.object({
  mimetype: Joi.string().valid('image/jpeg', 'image/png', 'image/gif', 'image/webp').required(),
  size: Joi.number().max(5 * 1024 * 1024).required().messages({
    'number.max': 'File size cannot exceed 5MB',
  }),
});
```

