## 7. Error Handling

### 7.1 Custom Error Classes

**src/utils/ApiError.js:**
```javascript
class ApiError extends Error {
  constructor(statusCode, message, isOperational = true, stack = '') {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    if (stack) {
      this.stack = stack;
    } else {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

module.exports = ApiError;
```

**src/utils/ApiResponse.js:**
```javascript
class ApiResponse {
  constructor(statusCode, message, data = null) {
    this.statusCode = statusCode;
    this.status = 'success';
    this.message = message;
    if (data) {
      this.data = data;
    }
  }
}

module.exports = ApiResponse;
```

### 7.2 Async Handler Utility

**src/utils/asyncHandler.js:**
```javascript
/**
 * Wrapper for async route handlers to catch errors
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

module.exports = asyncHandler;
```

### 7.3 Comprehensive Error Middleware

**src/middleware/error.middleware.js:**
```javascript
const config = require('../config/environment');
const logger = require('../config/logger');
const ApiError = require('../utils/ApiError');

/**
 * Handle specific database errors
 */
const handleDatabaseError = (error) => {
  // PostgreSQL unique constraint violation
  if (error.code === '23505') {
    const field = error.detail.match(/Key \((.*?)\)/)?.[1] || 'field';
    return new ApiError(400, `${field} already exists`);
  }

  // PostgreSQL foreign key violation
  if (error.code === '23503') {
    return new ApiError(400, 'Referenced record does not exist');
  }

  // PostgreSQL not null violation
  if (error.code === '23502') {
    const field = error.column || 'field';
    return new ApiError(400, `${field} is required`);
  }

  return error;
};

/**
 * Handle JWT errors
 */
const handleJWTError = () => {
  return new ApiError(401, 'Invalid token. Please log in again');
};

