    this.alertThresholds = {
      errorRate: 0.05, // 5% error rate
      responseTime: 2000, // 2 seconds
      memoryUsage: 0.9 // 90% memory usage
    };

    this.alertCooldown = new Map();
  }

  async sendAlert(type, message, details = {}) {
    const cooldownKey = `${type}-${message}`;
    const lastAlert = this.alertCooldown.get(cooldownKey);

    // Prevent alert spam (5 minute cooldown)
    if (lastAlert && Date.now() - lastAlert < 300000) {
      return;
    }

    logger.error('Alert triggered', { type, message, details });

    try {
      await this.transporter.sendMail({
        from: process.env.ALERT_FROM_EMAIL,
        to: process.env.ALERT_TO_EMAIL,
        subject: `[${process.env.NODE_ENV}] API Alert: ${type}`,
        html: `
          <h2>Alert: ${type}</h2>
          <p><strong>Message:</strong> ${message}</p>
          <p><strong>Environment:</strong> ${process.env.NODE_ENV}</p>
          <p><strong>Timestamp:</strong> ${new Date().toISOString()}</p>
          <h3>Details:</h3>
          <pre>${JSON.stringify(details, null, 2)}</pre>
        `
      });

      this.alertCooldown.set(cooldownKey, Date.now());
    } catch (error) {
      logger.error('Failed to send alert', { error: error.message });
    }
  }

  checkMetrics(metrics) {
    // Check error rate
    const totalRequests = metrics.requests?.total || 0;
    const errorRequests = metrics.requests?.errors || 0;
    const errorRate = totalRequests > 0 ? errorRequests / totalRequests : 0;

    if (errorRate > this.alertThresholds.errorRate) {
      this.sendAlert(
        'High Error Rate',
        `Error rate is ${(errorRate * 100).toFixed(2)}%`,
        { errorRate, totalRequests, errorRequests }
      );
    }

    // Check response time
    if (metrics.avgResponseTime > this.alertThresholds.responseTime) {
      this.sendAlert(
        'Slow Response Time',
        `Average response time is ${metrics.avgResponseTime}ms`,
        { avgResponseTime: metrics.avgResponseTime }
      );
    }

    // Check memory usage
    const memUsage = process.memoryUsage();
    const memPercent = memUsage.heapUsed / memUsage.heapTotal;

    if (memPercent > this.alertThresholds.memoryUsage) {
      this.sendAlert(
        'High Memory Usage',
        `Memory usage is ${(memPercent * 100).toFixed(2)}%`,
        { memoryUsage: memUsage }
      );
    }
  }
}

module.exports = new AlertingService();
