### 10.1 Why Monitoring Matters

Monitoring is the final critical piece of a production-ready REST API. After deploying your application (Section 9), you need visibility into its health, performance, and behavior. Without proper monitoring, you're flying blind—unable to detect issues before they impact users, diagnose problems quickly, or make data-driven optimization decisions.

**The Three Pillars of Observability:**

1. **Metrics**: Numerical measurements over time (CPU usage, request rate, error rate)
2. **Logs**: Discrete events with context (error messages, user actions, system events)
3. **Traces**: Request flow through distributed systems (tracking a single request across services)

### 10.2 Application Performance Monitoring (APM)

**Popular APM Solutions:**

- **Prometheus + Grafana**: Open-source, highly customizable, industry standard
- **New Relic**: Commercial, comprehensive, easy setup
- **Datadog**: Commercial, excellent integrations, powerful analytics
- **Elastic APM**: Part of ELK stack, good for log correlation
- **Application Insights**: Azure-native, good for Microsoft ecosystems

**Setting up Prometheus with Express:**

```bash
npm install prom-client express-prometheus-middleware
```

```javascript
// monitoring/prometheus.js
const promClient = require('prom-client');
const promMiddleware = require('express-prometheus-middleware');

// Enable default metrics (CPU, memory, event loop lag)
promClient.collectDefaultMetrics({ timeout: 5000 });

// Custom metrics
const httpRequestDuration = new promClient.Histogram({
  name: 'http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.1, 0.5, 1, 2, 5]
});

const httpRequestTotal = new promClient.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

const activeConnections = new promClient.Gauge({
  name: 'active_connections',
  help: 'Number of active connections'
});

const databaseQueryDuration = new promClient.Histogram({
  name: 'database_query_duration_seconds',
  help: 'Duration of database queries',
  labelNames: ['operation', 'table'],
  buckets: [0.01, 0.05, 0.1, 0.5, 1]
});

module.exports = {
  promClient,
  httpRequestDuration,
  httpRequestTotal,
  activeConnections,
  databaseQueryDuration
};
```

**Metrics Middleware:**

```javascript
// middleware/metricsMiddleware.js
const { httpRequestDuration, httpRequestTotal } = require('../monitoring/prometheus');

function metricsMiddleware(req, res, next) {
  const start = Date.now();

  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route ? req.route.path : req.path;
    const labels = {
      method: req.method,
      route: route,
      status_code: res.statusCode
    };

    httpRequestDuration.observe(labels, duration);
    httpRequestTotal.inc(labels);
  });

  next();
}

module.exports = metricsMiddleware;
```

**Metrics Endpoint:**

```javascript
// routes/metrics.js
const express = require('express');
const router = express.Router();
const { promClient } = require('../monitoring/prometheus');

router.get('/metrics', async (req, res) => {
  res.set('Content-Type', promClient.register.contentType);
  const metrics = await promClient.register.metrics();
  res.send(metrics);
});

module.exports = router;
```

**Apply in app.js:**

```javascript
const metricsMiddleware = require('./middleware/metricsMiddleware');
const metricsRouter = require('./routes/metrics');

app.use(metricsMiddleware);
app.use('/api', metricsRouter);
```

### 10.3 Structured Logging

Building on the error handling from Section 7, implement comprehensive structured logging:

```bash
npm install winston winston-daily-rotate-file
```

```javascript
// config/logger.js
const winston = require('winston');
const DailyRotateFile = require('winston-daily-rotate-file');

const logLevels = {
  error: 0,
  warn: 1,
  info: 2,
  http: 3,
  debug: 4
};

const logColors = {
  error: 'red',
  warn: 'yellow',
  info: 'green',
  http: 'magenta',
  debug: 'blue'
};

winston.addColors(logColors);

const logFormat = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.errors({ stack: true }),
  winston.format.metadata({ fillExcept: ['message', 'level', 'timestamp'] }),
  winston.format.json()
);

const consoleFormat = winston.format.combine(
  winston.format.colorize({ all: true }),
  winston.format.printf(({ timestamp, level, message, metadata }) => {
    let msg = `${timestamp} [${level}]: ${message}`;
    if (Object.keys(metadata).length > 0) {
      msg += ` ${JSON.stringify(metadata)}`;
    }
    return msg;
  })
);

const transports = [
  // Console output
  new winston.transports.Console({
    format: consoleFormat,
    level: process.env.LOG_LEVEL || 'info'
  }),

  // Error logs
  new DailyRotateFile({
    filename: 'logs/error-%DATE%.log',
    datePattern: 'YYYY-MM-DD',
    level: 'error',
    maxSize: '20m',
    maxFiles: '30d',
    format: logFormat
  }),

  // Combined logs
  new DailyRotateFile({
    filename: 'logs/combined-%DATE%.log',
    datePattern: 'YYYY-MM-DD',
    maxSize: '20m',
    maxFiles: '14d',
    format: logFormat
  })
];

const logger = winston.createLogger({
  levels: logLevels,
  transports,
  exitOnError: false
});

// HTTP request logging
logger.http = (message, meta = {}) => {
  logger.log('http', message, meta);
};

module.exports = logger;
```

**HTTP Request Logger Middleware:**

```javascript
// middleware/httpLogger.js
const logger = require('../config/logger');

function httpLogger(req, res, next) {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    const logData = {
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id
    };

    if (res.statusCode >= 500) {
      logger.error('HTTP Request Error', logData);
    } else if (res.statusCode >= 400) {
      logger.warn('HTTP Request Warning', logData);
    } else {
      logger.http('HTTP Request', logData);
    }
  });

  next();
}

module.exports = httpLogger;
```

**Database Query Logging:**

```javascript
// middleware/databaseLogger.js
const logger = require('../config/logger');
const { databaseQueryDuration } = require('../monitoring/prometheus');

function logDatabaseQuery(operation, table, duration, error = null) {
  const logData = {
    operation,
    table,
    duration: `${duration}ms`
  };

  // Record metric
  databaseQueryDuration.observe(
    { operation, table },
    duration / 1000
  );

  if (error) {
    logger.error('Database Query Failed', { ...logData, error: error.message });
  } else if (duration > 1000) {
    logger.warn('Slow Database Query', logData);
  } else {
    logger.debug('Database Query', logData);
  }
}

// Prisma middleware example
function prismaLoggingMiddleware(params, next) {
  const start = Date.now();

  return next(params)
    .then(result => {
      const duration = Date.now() - start;
      logDatabaseQuery(params.action, params.model, duration);
      return result;
    })
    .catch(error => {
      const duration = Date.now() - start;
      logDatabaseQuery(params.action, params.model, duration, error);
      throw error;
    });
}

module.exports = { logDatabaseQuery, prismaLoggingMiddleware };
```

### 10.4 Health Check Endpoints

Essential for load balancers, orchestrators (from Section 9), and uptime monitoring:

```javascript
// routes/health.js
const express = require('express');
const router = express.Router();
const prisma = require('../config/database');
const logger = require('../config/logger');

// Basic liveness check
router.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Detailed readiness check
router.get('/health/ready', async (req, res) => {
  const checks = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    checks: {}
  };

  // Database check
  try {
    await prisma.$queryRaw`SELECT 1`;
    checks.checks.database = { status: 'ok' };
  } catch (error) {
    checks.status = 'error';
    checks.checks.database = { status: 'error', message: error.message };
    logger.error('Database health check failed', { error: error.message });
  }

  // Memory check
  const memUsage = process.memoryUsage();
  const memUsageMB = {
    rss: Math.round(memUsage.rss / 1024 / 1024),
    heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024),
    heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024)
  };
  checks.checks.memory = { status: 'ok', usage: memUsageMB };

  // Uptime
  checks.checks.uptime = {
    status: 'ok',
    seconds: Math.floor(process.uptime())
  };

  const statusCode = checks.status === 'ok' ? 200 : 503;
  res.status(statusCode).json(checks);
});

// Startup probe (for Kubernetes)
router.get('/health/startup', (req, res) => {
  // Check if app has finished initialization
  if (global.appReady) {
    res.status(200).json({ status: 'ready' });
  } else {
    res.status(503).json({ status: 'starting' });
  }
});

module.exports = router;
```

### 10.5 Distributed Tracing

For tracking requests across microservices:

```bash
npm install @opentelemetry/api @opentelemetry/sdk-node @opentelemetry/auto-instrumentations-node @opentelemetry/exporter-jaeger
```

```javascript
// tracing.js
const { NodeSDK } = require('@opentelemetry/sdk-node');
const { getNodeAutoInstrumentations } = require('@opentelemetry/auto-instrumentations-node');
const { JaegerExporter } = require('@opentelemetry/exporter-jaeger');
const { Resource } = require('@opentelemetry/resources');
const { SemanticResourceAttributes } = require('@opentelemetry/semantic-conventions');

const jaegerExporter = new JaegerExporter({
  endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces'
});

const sdk = new NodeSDK({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'rest-api',
    [SemanticResourceAttributes.SERVICE_VERSION]: process.env.APP_VERSION || '1.0.0'
  }),
  traceExporter: jaegerExporter,
  instrumentations: [
    getNodeAutoInstrumentations({
      '@opentelemetry/instrumentation-fs': { enabled: false }
    })
  ]
});

sdk.start();

process.on('SIGTERM', () => {
  sdk.shutdown()
    .then(() => console.log('Tracing terminated'))
    .catch((error) => console.error('Error terminating tracing', error))
    .finally(() => process.exit(0));
});

module.exports = sdk;
```

**Custom Spans:**

```javascript
// services/userService.js
const { trace } = require('@opentelemetry/api');

async function getUserWithOrders(userId) {
  const tracer = trace.getTracer('user-service');

  return tracer.startActiveSpan('getUserWithOrders', async (span) => {
    try {
      span.setAttribute('user.id', userId);

      const user = await prisma.user.findUnique({
        where: { id: userId },
        include: { orders: true }
      });

      span.setAttribute('orders.count', user.orders.length);
      span.setStatus({ code: 0 }); // OK

      return user;
    } catch (error) {
      span.setStatus({ code: 2, message: error.message }); // ERROR
      span.recordException(error);
      throw error;
    } finally {
      span.end();
    }
  });
}
```

### 10.6 Alerting and Incident Response

**Prometheus Alert Rules (prometheus-alerts.yml):**

```yaml
groups:
  - name: api_alerts
    interval: 30s
    rules:
      # High error rate
      - alert: HighErrorRate
        expr: |
          rate(http_requests_total{status_code=~"5.."}[5m]) / 
          rate(http_requests_total[5m]) > 0.05
        for: 5m
        labels:
          severity: critical
        annotations:
          summary: "High error rate detected"
          description: "Error rate is {{ $value | humanizePercentage }} over the last 5 minutes"

      # Slow response time
      - alert: SlowResponseTime
        expr: |
          histogram_quantile(0.95, 
            rate(http_request_duration_seconds_bucket[5m])
          ) > 2
        for: 5m
        labels:
          severity: warning
        annotations:
          summary: "95th percentile response time is high"
          description: "P95 response time is {{ $value }}s"

      # High memory usage
      - alert: HighMemoryUsage
        expr: process_resident_memory_bytes / 1024 / 1024 > 1024
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "High memory usage"
          description: "Memory usage is {{ $value }}MB"

      # Database connection issues
      - alert: DatabaseConnectionFailure
        expr: up{job="postgres"} == 0
        for: 1m
        labels:
          severity: critical
        annotations:
          summary: "Database is down"
          description: "Cannot connect to database"

      # API is down
      - alert: APIDown
        expr: up{job="api"} == 0
        for: 2m
        labels:
          severity: critical
        annotations:
          summary: "API is down"
          description: "API has been down for 2 minutes"
```

