### 6.2 Custom Validation Rules

**src/validators/custom.validator.js:**
```javascript
const Joi = require('joi');

// Custom validator for strong passwords
const strongPassword = (value, helpers) => {
  if (value.length < 8) {
    return helpers.error('password.min');
  }
  if (!/[a-z]/.test(value)) {
    return helpers.error('password.lowercase');
  }
  if (!/[A-Z]/.test(value)) {
    return helpers.error('password.uppercase');
  }
  if (!/\d/.test(value)) {
    return helpers.error('password.number');
  }
  if (!/[@$!%*?&]/.test(value)) {
    return helpers.error('password.special');
  }
  return value;
};

// Custom validator for file uploads
const fileUpload = (value, helpers) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/gif'];
  const maxSize = 5 * 1024 * 1024; // 5MB

  if (!allowedTypes.includes(value.mimetype)) {
    return helpers.error('file.type');
  }

  if (value.size > maxSize) {
    return helpers.error('file.size');
  }

  return value;
};

// Extend Joi with custom validators
const customJoi = Joi.extend((joi) => ({
  type: 'password',
  base: joi.string(),
  messages: {
    'password.min': 'Password must be at least 8 characters long',
    'password.lowercase': 'Password must contain at least one lowercase letter',
    'password.uppercase': 'Password must contain at least one uppercase letter',
    'password.number': 'Password must contain at least one number',
    'password.special': 'Password must contain at least one special character',
  },
  rules: {
    strong: {
      validate: strongPassword,
    },
  },
}));

module.exports = {
  customJoi,
  strongPassword,
  fileUpload,
};
```

