### 10.4 Structured Logging with Winston

Building on the error handling from Section 7, implement comprehensive logging:

```javascript
// config/logger.js
const winston = require('winston');
const { ElasticsearchTransport } = require('winston-elasticsearch');

const logLevels = {
  error: 0,
  warn: 1,
  info: 2,
  http: 3,
  debug: 4
};

const logColors = {
  error: 'red',
  warn: 'yellow',
  info: 'green',
  http: 'magenta',
  debug: 'blue'
};

winston.addColors(logColors);

// Custom format for structured logging
const structuredFormat = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.errors({ stack: true }),
  winston.format.metadata(),
  winston.format.json()
);

const consoleFormat = winston.format.combine(
  winston.format.colorize({ all: true }),
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.printf(
    (info) => `${info.timestamp} ${info.level}: ${info.message}`
  )
);

const transports = [
  // Console transport
  new winston.transports.Console({
    format: process.env.NODE_ENV === 'production' 
      ? structuredFormat 
      : consoleFormat
  }),

  // File transports
  new winston.transports.File({
    filename: 'logs/error.log',
    level: 'error',
    format: structuredFormat,
    maxsize: 5242880, // 5MB
    maxFiles: 5
  }),
  new winston.transports.File({
    filename: 'logs/combined.log',
    format: structuredFormat,
    maxsize: 5242880,
    maxFiles: 5
  })
];

// Add Elasticsearch transport in production
if (process.env.NODE_ENV === 'production' && process.env.ELASTICSEARCH_URL) {
  transports.push(
    new ElasticsearchTransport({
      level: 'info',
      clientOpts: { node: process.env.ELASTICSEARCH_URL },
      index: 'api-logs'
    })
  );
}

const logger = winston.createLogger({
  levels: logLevels,
  level: process.env.LOG_LEVEL || 'info',
  format: structuredFormat,
  transports,
  exitOnError: false
});

// Create a stream for Morgan HTTP logging
logger.stream = {
  write: (message) => logger.http(message.trim())
};

module.exports = logger;
```

#### Request Logging Middleware

```javascript
// middleware/requestLogger.js
const morgan = require('morgan');
const logger = require('../config/logger');

// Custom Morgan tokens
morgan.token('user-id', (req) => req.user?.id || 'anonymous');
morgan.token('request-id', (req) => req.id);

const requestLogger = morgan(
  ':request-id :method :url :status :response-time ms - :user-id',
  { stream: logger.stream }
);

module.exports = requestLogger;
```

#### Contextual Logging in Routes

```javascript
// Example route with contextual logging
router.post('/users', async (req, res, next) => {
  const requestId = req.id;

  logger.info('Creating new user', {
    requestId,
    email: req.body.email,
    ip: req.ip
  });

  try {
    const user = await userService.create(req.body);

    logger.info('User created successfully', {
      requestId,
      userId: user.id,
      email: user.email
    });

    res.status(201).json(user);
  } catch (error) {
    logger.error('Failed to create user', {
      requestId,
      email: req.body.email,
      error: error.message,
      stack: error.stack
    });

    next(error);
  }
});
```

### 10.5 Metrics Collection with Prometheus

Track custom metrics for your API:

```javascript
// config/metrics.js
const promClient = require('prom-client');

// Create a Registry
const register = new promClient.Registry();

// Add default metrics (CPU, memory, etc.)
promClient.collectDefaultMetrics({ register });

// Custom metrics
const httpRequestDuration = new promClient.Histogram({
  name: 'http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.1, 0.5, 1, 2, 5]
});

const httpRequestTotal = new promClient.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

const activeConnections = new promClient.Gauge({
  name: 'active_connections',
  help: 'Number of active connections'
});

const databaseQueryDuration = new promClient.Histogram({
  name: 'database_query_duration_seconds',
  help: 'Duration of database queries in seconds',
  labelNames: ['operation', 'table'],
  buckets: [0.01, 0.05, 0.1, 0.5, 1]
});

const authenticationAttempts = new promClient.Counter({
  name: 'authentication_attempts_total',
  help: 'Total authentication attempts',
  labelNames: ['status']
});

const cacheHits = new promClient.Counter({
  name: 'cache_hits_total',
  help: 'Total cache hits',
  labelNames: ['cache_type']
});

const cacheMisses = new promClient.Counter({
  name: 'cache_misses_total',
  help: 'Total cache misses',
  labelNames: ['cache_type']
});

// Register all metrics
register.registerMetric(httpRequestDuration);
register.registerMetric(httpRequestTotal);
register.registerMetric(activeConnections);
register.registerMetric(databaseQueryDuration);
register.registerMetric(authenticationAttempts);
register.registerMetric(cacheHits);
register.registerMetric(cacheMisses);

module.exports = {
  register,
  httpRequestDuration,
  httpRequestTotal,
  activeConnections,
  databaseQueryDuration,
  authenticationAttempts,
  cacheHits,
  cacheMisses
};
```

#### Metrics Middleware

```javascript
// middleware/metricsMiddleware.js
const { httpRequestDuration, httpRequestTotal, activeConnections } = require('../config/metrics');

const metricsMiddleware = (req, res, next) => {
  const start = Date.now();

  activeConnections.inc();

  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route?.path || req.path;
    const labels = {
      method: req.method,
      route,
      status_code: res.statusCode
    };

    httpRequestDuration.observe(labels, duration);
    httpRequestTotal.inc(labels);
    activeConnections.dec();
  });

  next();
};

module.exports = metricsMiddleware;
```

#### Metrics Endpoint

```javascript
// routes/metrics.js
const express = require('express');
const router = express.Router();
const { register } = require('../config/metrics');

router.get('/metrics', async (req, res) => {
  res.set('Content-Type', register.contentType);
  res.end(await register.metrics());
});

module.exports = router;
```

### 10.6 Error Tracking with Sentry

Integrate Sentry for real-time error tracking:

```javascript
// config/sentry.js
const Sentry = require('@sentry/node');
const Tracing = require('@sentry/tracing');

const initSentry = (app) => {
  if (process.env.SENTRY_DSN) {
    Sentry.init({
      dsn: process.env.SENTRY_DSN,
      environment: process.env.NODE_ENV,
      release: process.env.APP_VERSION,
      integrations: [
        new Sentry.Integrations.Http({ tracing: true }),
        new Tracing.Integrations.Express({ app }),
        new Tracing.Integrations.Postgres()
      ],
      tracesSampleRate: process.env.NODE_ENV === 'production' ? 0.1 : 1.0,
      beforeSend(event, hint) {
        // Filter out sensitive data
        if (event.request) {
          delete event.request.cookies;
          delete event.request.headers?.authorization;
        }
        return event;
      }
    });
  }
};

module.exports = { Sentry, initSentry };
```

```javascript
// server.js
const express = require('express');
const { Sentry, initSentry } = require('./config/sentry');

const app = express();

// Initialize Sentry first
initSentry(app);

// Sentry request handler must be first
app.use(Sentry.Handlers.requestHandler());
app.use(Sentry.Handlers.tracingHandler());

// ... your middleware and routes

// Sentry error handler must be before other error handlers
app.use(Sentry.Handlers.errorHandler());

// Your custom error handler
app.use((err, req, res, next) => {
  // ... your error handling logic
});
```

