## 6. Validation

### 6.1 Request Validation Schemas

**src/validators/auth.validator.js:**
```javascript
const Joi = require('joi');

const password = Joi.string()
  .min(8)
  .max(128)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .message('Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character');

const email = Joi.string()
  .email()
  .lowercase()
  .trim();

const register = Joi.object({
  body: Joi.object({
    email: email.required(),
    username: Joi.string()
      .alphanum()
      .min(3)
      .max(30)
      .required(),
    password: password.required(),
    confirmPassword: Joi.string()
      .valid(Joi.ref('password'))
      .required()
      .messages({
        'any.only': 'Passwords must match',
      }),
    firstName: Joi.string()
      .min(2)
      .max(50)
      .required(),
    lastName: Joi.string()
      .min(2)
      .max(50)
      .required(),
  }),
});

const login = Joi.object({
  body: Joi.object({
    email: email.required(),
    password: Joi.string().required(),
  }),
});

const refreshToken = Joi.object({
  body: Joi.object({
    refreshToken: Joi.string().required(),
  }),
});

const forgotPassword = Joi.object({
  body: Joi.object({
    email: email.required(),
  }),
});

const resetPassword = Joi.object({
  body: Joi.object({
    token: Joi.string().required(),
    password: password.required(),
    confirmPassword: Joi.string()
      .valid(Joi.ref('password'))
      .required()
      .messages({
        'any.only': 'Passwords must match',
      }),
  }),
});

const verifyEmail = Joi.object({
  body: Joi.object({
    token: Joi.string().required(),
  }),
});

module.exports = {
  register,
  login,
  refreshToken,
  forgotPassword,
  resetPassword,
  verifyEmail,
};
```

**src/validators/user.validator.js:**
```javascript
const Joi = require('joi');

const getUsers = Joi.object({
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    sort: Joi.string().valid('createdAt', '-createdAt', 'email', '-email', 'username', '-username'),
    search: Joi.string().max(100),
    role: Joi.string().valid('user', 'admin', 'manager'),
  }),
});

const getUserById = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
});

const createUser = Joi.object({
  body: Joi.object({
    email: Joi.string().email().lowercase().trim().required(),
    username: Joi.string().alphanum().min(3).max(30).required(),
    password: Joi.string()
      .min(8)
      .max(128)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required(),
    firstName: Joi.string().min(2).max(50).required(),
    lastName: Joi.string().min(2).max(50).required(),
    role: Joi.string().valid('user', 'admin', 'manager').default('user'),
  }),
});

const updateUser = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
  body: Joi.object({
    email: Joi.string().email().lowercase().trim(),
    username: Joi.string().alphanum().min(3).max(30),
    firstName: Joi.string().min(2).max(50),
    lastName: Joi.string().min(2).max(50),
    role: Joi.string().valid('user', 'admin', 'manager'),
    isActive: Joi.boolean(),
  }).min(1), // At least one field must be provided
});

const deleteUser = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
});

const changePassword = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
  body: Joi.object({
    currentPassword: Joi.string().required(),
    newPassword: Joi.string()
      .min(8)
      .max(128)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required()
      .invalid(Joi.ref('currentPassword'))
      .messages({
        'any.invalid': 'New password must be different from current password',
      }),
    confirmPassword: Joi.string()
      .valid(Joi.ref('newPassword'))
      .required()
      .messages({
        'any.only': 'Passwords must match',
      }),
  }),
});

module.exports = {
  getUsers,
  getUserById,
  createUser,
  updateUser,
  deleteUser,
  changePassword,
};
```

