const Joi = require('joi');

const getProducts = Joi.object({
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    sort: Joi.string().valid(
      'createdAt', '-createdAt',
      'price', '-price',
      'name', '-name',
      'stock', '-stock'
    ),
    search: Joi.string().max(100),
    status: Joi.string().valid('active', 'inactive', 'discontinued'),
    minPrice: Joi.number().min(0),
    maxPrice: Joi.number().min(0),
    categoryId: Joi.number().integer().positive(),
  }),
});

const getProductById = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
});

const createProduct = Joi.object({
  body: Joi.object({
    name: Joi.string().min(3).max(255).required(),
    slug: Joi.string().lowercase().pattern(/^[a-z0-9-]+$/).required(),
    description: Joi.string().max(5000),
    price: Joi.number().positive().precision(2).required(),
    stock: Joi.number().integer().min(0).default(0),
    sku: Joi.string().max(100),
    status: Joi.string().valid('active', 'inactive', 'discontinued').default('active'),
    categoryId: Joi.number().integer().positive(),
  }),
});

const updateProduct = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
  body: Joi.object({
    name: Joi.string().min(3).max(255),
    slug: Joi.string().lowercase().pattern(/^[a-z0-9-]+$/),
    description: Joi.string().max(5000),
    price: Joi.number().positive().precision(2),
    stock: Joi.number().integer().min(0),
    sku: Joi.string().max(100),
    status: Joi.string().valid('active', 'inactive', 'discontinued'),
    categoryId: Joi.number().integer().positive(),
  }).min(1),
});

const deleteProduct = Joi.object({
  params: Joi.object({
    id: Joi.number().integer().positive().required(),
  }),
});

const searchProducts = Joi.object({
  query: Joi.object({
    q: Joi.string().min(2).max(100).required(),
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
  }),
});

module.exports = {
  getProducts,
  getProductById,
  createProduct,
  updateProduct,
  deleteProduct,
  searchProducts,
};
