### Introduction to Monitoring and Observability

Monitoring is essential for maintaining a production-ready REST API. It enables you to detect issues before users report them, understand system behavior, optimize performance, and ensure reliability. Building on the deployment infrastructure from Section 9, this section covers comprehensive monitoring strategies.

### The Three Pillars of Observability

**1. Metrics** - Quantitative measurements over time  
**2. Logs** - Discrete event records  
**3. Traces** - Request flow through distributed systems

### Setting Up Application Performance Monitoring (APM)

#### Installing Prometheus Client

```bash
npm install prom-client
npm install express-prom-bundle
```

#### Metrics Service

Create `src/services/metrics.service.ts`:

```typescript
import { Registry, Counter, Histogram, Gauge } from 'prom-client';

class MetricsService {
  public registry: Registry;

  // HTTP metrics
  public httpRequestDuration: Histogram;
  public httpRequestTotal: Counter;
  public httpRequestErrors: Counter;

  // Business metrics
  public activeUsers: Gauge;
  public databaseConnections: Gauge;
  public apiCallsTotal: Counter;

  // Custom metrics
  public authenticationAttempts: Counter;
  public authenticationFailures: Counter;

  constructor() {
    this.registry = new Registry();

    // HTTP request duration histogram
    this.httpRequestDuration = new Histogram({
      name: 'http_request_duration_seconds',
      help: 'Duration of HTTP requests in seconds',
      labelNames: ['method', 'route', 'status_code'],
      buckets: [0.1, 0.5, 1, 2, 5, 10],
      registers: [this.registry],
    });

    // HTTP request counter
    this.httpRequestTotal = new Counter({
      name: 'http_requests_total',
      help: 'Total number of HTTP requests',
      labelNames: ['method', 'route', 'status_code'],
      registers: [this.registry],
    });

    // HTTP error counter
    this.httpRequestErrors = new Counter({
      name: 'http_request_errors_total',
      help: 'Total number of HTTP request errors',
      labelNames: ['method', 'route', 'error_type'],
      registers: [this.registry],
    });

    // Active users gauge
    this.activeUsers = new Gauge({
      name: 'active_users_total',
      help: 'Number of currently active users',
      registers: [this.registry],
    });

    // Database connections gauge
    this.databaseConnections = new Gauge({
      name: 'database_connections_active',
      help: 'Number of active database connections',
      registers: [this.registry],
    });

    // API calls counter
    this.apiCallsTotal = new Counter({
      name: 'api_calls_total',
      help: 'Total number of API calls',
      labelNames: ['endpoint', 'user_id'],
      registers: [this.registry],
    });

    // Authentication metrics
    this.authenticationAttempts = new Counter({
      name: 'authentication_attempts_total',
      help: 'Total number of authentication attempts',
      labelNames: ['method'],
      registers: [this.registry],
    });

    this.authenticationFailures = new Counter({
      name: 'authentication_failures_total',
      help: 'Total number of authentication failures',
      labelNames: ['method', 'reason'],
      registers: [this.registry],
    });
  }

  // Get metrics in Prometheus format
  async getMetrics(): Promise<string> {
    return this.registry.metrics();
  }

  // Record HTTP request
  recordHttpRequest(
    method: string,
    route: string,
    statusCode: number,
    duration: number
  ): void {
    this.httpRequestDuration
      .labels(method, route, statusCode.toString())
      .observe(duration);

    this.httpRequestTotal
      .labels(method, route, statusCode.toString())
      .inc();

    if (statusCode >= 400) {
      this.httpRequestErrors
        .labels(method, route, 'http_error')
        .inc();
    }
  }

  // Update active users
  setActiveUsers(count: number): void {
    this.activeUsers.set(count);
  }

  // Update database connections
  setDatabaseConnections(count: number): void {
    this.databaseConnections.set(count);
  }
}

export const metricsService = new MetricsService();
```

#### Metrics Middleware

Create `src/middleware/metrics.middleware.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { metricsService } from '../services/metrics.service';

export const metricsMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  const start = Date.now();

  // Capture response finish event
  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000; // Convert to seconds
    const route = req.route?.path || req.path;

    metricsService.recordHttpRequest(
      req.method,
      route,
      res.statusCode,
      duration
    );
  });

  next();
};
```

#### Metrics Endpoint

Add to `src/routes/index.ts`:

```typescript
import express from 'express';
import { metricsService } from '../services/metrics.service';

const router = express.Router();

// Metrics endpoint for Prometheus scraping
router.get('/metrics', async (req, res) => {
  try {
    res.set('Content-Type', metricsService.registry.contentType);
    const metrics = await metricsService.getMetrics();
    res.send(metrics);
  } catch (error) {
    res.status(500).send('Error collecting metrics');
  }
});

export default router;
```

### Structured Logging with Winston

#### Installing Winston

```bash
npm install winston winston-daily-rotate-file
```

#### Logger Configuration

Create `src/config/logger.ts`:

```typescript
import winston from 'winston';
import DailyRotateFile from 'winston-daily-rotate-file';

const { combine, timestamp, json, printf, colorize, errors } = winston.format;

// Custom format for console output
const consoleFormat = printf(({ level, message, timestamp, ...metadata }) => {
  let msg = `${timestamp} [${level}]: ${message}`;

  if (Object.keys(metadata).length > 0) {
    msg += ` ${JSON.stringify(metadata)}`;
  }

  return msg;
});

// Create logger instance
export const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: combine(
    errors({ stack: true }),
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    json()
  ),
  defaultMeta: {
    service: 'rest-api',
    environment: process.env.NODE_ENV,
  },
  transports: [
    // Error logs
    new DailyRotateFile({
      filename: 'logs/error-%DATE%.log',
      datePattern: 'YYYY-MM-DD',
      level: 'error',
      maxSize: '20m',
      maxFiles: '14d',
      format: combine(
        timestamp(),
        json()
      ),
    }),

    // Combined logs
    new DailyRotateFile({
      filename: 'logs/combined-%DATE%.log',
      datePattern: 'YYYY-MM-DD',
      maxSize: '20m',
      maxFiles: '14d',
      format: combine(
        timestamp(),
        json()
      ),
    }),

    // Console output
    new winston.transports.Console({
      format: combine(
        colorize(),
        timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
        consoleFormat
      ),
    }),
  ],
});

// Create child logger with additional context
export const createLogger = (context: Record<string, any>) => {
  return logger.child(context);
};
```

#### Request Logging Middleware

Update `src/middleware/logger.middleware.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { logger } from '../config/logger';
import { v4 as uuidv4 } from 'uuid';

export const requestLogger = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  const requestId = uuidv4();
  const startTime = Date.now();

  // Attach request ID to request object
  req.id = requestId;

  // Log incoming request
  logger.info('Incoming request', {
    requestId,
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    userId: req.user?.id,
  });

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - startTime;

    const logData = {
      requestId,
      method: req.method,
      url: req.url,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userId: req.user?.id,
    };

    if (res.statusCode >= 400) {
      logger.error('Request failed', logData);
    } else {
      logger.info('Request completed', logData);
    }
  });

  next();
};
```

### Distributed Tracing with OpenTelemetry

#### Installing OpenTelemetry

```bash
npm install @opentelemetry/api @opentelemetry/sdk-node
npm install @opentelemetry/auto-instrumentations-node
npm install @opentelemetry/exporter-jaeger
```

#### OpenTelemetry Configuration

Create `src/config/tracing.ts`:

```typescript
import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';

const jaegerExporter = new JaegerExporter({
  endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces',
});

const sdk = new NodeSDK({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'rest-api',
    [SemanticResourceAttributes.SERVICE_VERSION]: '1.0.0',
    environment: process.env.NODE_ENV,
  }),
  traceExporter: jaegerExporter,
  instrumentations: [
    getNodeAutoInstrumentations({
      '@opentelemetry/instrumentation-fs': {
        enabled: false,
      },
    }),
  ],
});

export const initTracing = async (): Promise<void> => {
  try {
    await sdk.start();
    console.log('Tracing initialized');
  } catch (error) {
    console.error('Error initializing tracing:', error);
  }
};

export const shutdownTracing = async (): Promise<void> => {
  try {
    await sdk.shutdown();
    console.log('Tracing shut down');
  } catch (error) {
    console.error('Error shutting down tracing:', error);
  }
};
```

### Health Check Endpoints

Create `src/routes/health.routes.ts`:

```typescript
import express, { Request, Response } from 'express';
import { prisma } from '../config/database';
import { logger } from '../config/logger';

const router = express.Router();

// Basic liveness probe
router.get('/health', (req: Request, res: Response) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// Detailed readiness probe
router.get('/health/ready', async (req: Request, res: Response) => {
  const checks = {
    database: false,
    memory: false,
    disk: false,
  };

  try {
    // Check database connection
    await prisma.$queryRaw`SELECT 1`;
    checks.database = true;

    // Check memory usage
    const memUsage = process.memoryUsage();
    const memThreshold = 0.9; // 90% threshold
    const heapUsedPercent = memUsage.heapUsed / memUsage.heapTotal;
    checks.memory = heapUsedPercent < memThreshold;

    // All checks passed
    if (Object.values(checks).every(check => check)) {
      res.status(200).json({
        status: 'ready',
        checks,
        timestamp: new Date().toISOString(),
      });
    } else {
      res.status(503).json({
        status: 'not ready',
        checks,
        timestamp: new Date().toISOString(),
      });
    }
  } catch (error) {
    logger.error('Health check failed', { error });
    res.status(503).json({
      status: 'not ready',
      checks,
      error: 'Health check failed',
      timestamp: new Date().toISOString(),
    });
  }
});

// Detailed status endpoint
router.get('/health/status', async (req: Request, res: Response) => {
  const memUsage = process.memoryUsage();

  res.status(200).json({
    status: 'ok',
    version: process.env.npm_package_version || '1.0.0',
    environment: process.env.NODE_ENV,
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    memory: {
      heapUsed: `${Math.round(memUsage.heapUsed / 1024 / 1024)}MB`,
      heapTotal: `${Math.round(memUsage.heapTotal / 1024 / 1024)}MB`,
      rss: `${Math.round(memUsage.rss / 1024 / 1024)}MB`,
    },
    cpu: process.cpuUsage(),
  });
});

export default router;
```

### Error Tracking with Sentry

#### Installing Sentry

```bash
npm install @sentry/node @sentry/tracing
```

#### Sentry Configuration

Create `src/config/sentry.ts`:

```typescript
import * as Sentry from '@sentry/node';
import * as Tracing from '@sentry/tracing';
import { Express } from 'express';

export const initSentry = (app: Express): void => {
  if (!process.env.SENTRY_DSN) {
    console.warn('Sentry DSN not configured, skipping initialization');
    return;
  }

  Sentry.init({
    dsn: process.env.SENTRY_DSN,
    environment: process.env.NODE_ENV,
    integrations: [
      new Sentry.Integrations.Http({ tracing: true }),
      new Tracing.Integrations.Express({ app }),
      new Tracing.Integrations.Prisma({ client: prisma }),
    ],
    tracesSampleRate: process.env.NODE_ENV === 'production' ? 0.1 : 1.0,
    beforeSend(event, hint) {
      // Filter out sensitive data
      if (event.request) {
        delete event.request.cookies;
        if (event.request.headers) {
          delete event.request.headers.authorization;
        }
      }
      return event;
    },
  });
};

export const sentryRequestHandler = Sentry.Handlers.requestHandler();
export const sentryTracingHandler = Sentry.Handlers.tracingHandler();
export const sentryErrorHandler = Sentry.Handlers.errorHandler();
```

