## 6. Validation

### 6.1 Request Validation Schemas

**src/validators/auth.validator.js:**
```javascript
const Joi = require('joi');

const password = Joi.string()
  .min(8)
  .max(128)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .message(
    'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character'
  );

const email = Joi.string()
  .email()
  .lowercase()
  .trim()
  .max(255);

exports.register = {
  body: Joi.object({
    email: email.required(),
    password: password.required(),
    firstName: Joi.string().trim().min(2).max(100).required(),
    lastName: Joi.string().trim().min(2).max(100).required()
  })
};

exports.login = {
  body: Joi.object({
    email: email.required(),
    password: Joi.string().required()
  })
};

exports.refreshToken = {
  body: Joi.object({
    refreshToken: Joi.string().required()
  })
};

exports.forgotPassword = {
  body: Joi.object({
    email: email.required()
  })
};

exports.resetPassword = {
  body: Joi.object({
    token: Joi.string().required(),
    newPassword: password.required()
  })
};

exports.verifyEmail = {
  body: Joi.object({
    token: Joi.string().required()
  })
};
```

**src/validators/user.validator.js:**
```javascript
const Joi = require('joi');

const id = Joi.number().integer().positive();

exports.getUsers = {
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(10),
    sort: Joi.string().valid(
      'createdAt', '-createdAt',
      'email', '-email',
      'firstName', '-firstName'
    ).default('-createdAt'),
    search: Joi.string().trim().max(255)
  })
};

exports.getUserById = {
  params: Joi.object({
    id: id.required()
  })
};

exports.createUser = {
  body: Joi.object({
    email: Joi.string().email().lowercase().trim().max(255).required(),
    password: Joi.string()
      .min(8)
      .max(128)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required(),
    firstName: Joi.string().trim().min(2).max(100).required(),
    lastName: Joi.string().trim().min(2).max(100).required(),
    role: Joi.string().valid('user', 'admin', 'manager').default('user')
  })
};

exports.updateUser = {
  params: Joi.object({
    id: id.required()
  }),
  body: Joi.object({
    firstName: Joi.string().trim().min(2).max(100),
    lastName: Joi.string().trim().min(2).max(100),
    role: Joi.string().valid('user', 'admin', 'manager'),
    isActive: Joi.boolean()
  }).min(1)
};

exports.deleteUser = {
  params: Joi.object({
    id: id.required()
  })
};

exports.changePassword = {
  params: Joi.object({
    id: id.required()
  }),
  body: Joi.object({
    currentPassword: Joi.string().required(),
    newPassword: Joi.string()
      .min(8)
      .max(128)
      .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
      .required()
  })
};
```

