### 6.2 Custom Validation Rules

**src/validators/custom.validators.js:**
```javascript
const Joi = require('joi');

/**
 * Custom phone number validator
 */
const phoneNumber = Joi.string().custom((value, helpers) => {
  const phoneRegex = /^\+?[1-9]\d{1,14}$/;
  if (!phoneRegex.test(value)) {
    return helpers.error('any.invalid');
  }
  return value;
}, 'Phone number validation');

/**
 * Custom date range validator
 */
const dateRange = Joi.object({
  startDate: Joi.date().iso().required(),
  endDate: Joi.date().iso().min(Joi.ref('startDate')).required()
});

/**
 * Custom file upload validator
 */
const fileUpload = Joi.object({
  filename: Joi.string().required(),
  mimetype: Joi.string().valid(
    'image/jpeg',
    'image/png',
    'image/gif',
    'application/pdf'
  ).required(),
  size: Joi.number().max(5 * 1024 * 1024).required() // 5MB max
});

/**
 * Custom credit card validator
 */
const creditCard = Joi.string().creditCard();

/**
 * Custom URL slug validator
 */
const slug = Joi.string().pattern(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);

module.exports = {
  phoneNumber,
  dateRange,
  fileUpload,
  creditCard,
  slug
};
```

### 6.3 Sanitization

**src/utils/sanitize.js:**
```javascript
const validator = require('validator');

/**
 * Sanitize string input
 */
exports.sanitizeString = (str) => {
  if (typeof str !== 'string') return str;

  return validator.escape(
    validator.trim(str)
  );
};

/**
 * Sanitize email
 */
exports.sanitizeEmail = (email) => {
  if (typeof email !== 'string') return email;

  return validator.normalizeEmail(email, {
    gmail_remove_dots: false,
    gmail_remove_subaddress: false
  });
};

/**
 * Sanitize HTML
 */
exports.sanitizeHTML = (html) => {
  if (typeof html !== 'string') return html;

  // Use a library like DOMPurify for more robust HTML sanitization
  return validator.stripLow(html);
};

/**
 * Sanitize object recursively
 */
exports.sanitizeObject = (obj) => {
  if (typeof obj !== 'object' || obj === null) {
    return obj;
  }

  const sanitized = Array.isArray(obj) ? [] : {};

  for (const key in obj) {
    if (obj.hasOwnProperty(key)) {
      const value = obj[key];

      if (typeof value === 'string') {
        sanitized[key] = exports.sanitizeString(value);
      } else if (typeof value === 'object') {
        sanitized[key] = exports.sanitizeObject(value);
      } else {
        sanitized[key] = value;
      }
    }
  }

  return sanitized;
};
```

