const logger = require('../config/logger');
const ApiError = require('../utils/ApiError');

/**
 * Handle specific error types
 */
const handleDatabaseError = (err) => {
  // PostgreSQL error codes
  const errorMap = {
    '23505': { status: 409, message: 'Duplicate entry' },
    '23503': { status: 400, message: 'Foreign key constraint violation' },
    '23502': { status: 400, message: 'Not null constraint violation' },
    '22P02': { status: 400, message: 'Invalid input syntax' }
  };

  const error = errorMap[err.code];
  if (error) {
    return new ApiError(error.status, error.message);
  }

  return new ApiError(500, 'Database error');
};

const handleJWTError = () => {
  return new ApiError(401, 'Invalid token. Please log in again');
};

const handleJWTExpiredError = () => {
  return new ApiError(401, 'Token expired. Please log in again');
};

const handleValidationError = (err) => {
  const errors = Object.values(err.errors).map(el => el.message);
  const message = `Invalid input data. ${errors.join('. ')}`;
  return new ApiError(400, message);
};

const handleCastError = (err) => {
  const message = `Invalid ${err.path}: ${err.value}`;
  return new ApiError(400, message);
};

