## Overview

Monitoring is the final and crucial piece of a production-ready REST API. Building upon the complete foundation established in Sections 1-9 (Project Setup, Routing, Middleware, Database, Authentication, Validation, Error Handling, Testing, and Deployment), this section covers how to observe, track, and maintain your API's health, performance, and reliability in production.

Effective monitoring enables you to:
- Detect and respond to issues before users are impacted
- Understand system performance and user behavior
- Make data-driven decisions for optimization
- Meet SLAs and maintain system reliability
- Debug production issues efficiently

## The Three Pillars of Observability

### 1. Metrics
Quantitative measurements of system behavior over time (CPU usage, request rate, response time).

### 2. Logs
Discrete events that occurred in your system with contextual information.

### 3. Traces
The journey of a request through your distributed system.

## Monitoring Stack Options

### Option 1: Prometheus + Grafana (Open Source)
**Best for:** Self-hosted solutions, cost-conscious teams, full control

### Option 2: ELK Stack (Elasticsearch, Logstash, Kibana)
**Best for:** Log-centric monitoring, search capabilities

### Option 3: Commercial Solutions
- **Datadog:** All-in-one monitoring platform
- **New Relic:** APM and infrastructure monitoring
- **Sentry:** Error tracking and performance monitoring
- **CloudWatch:** AWS-native monitoring

## Implementing Application Metrics with Prometheus

### Install Dependencies

```bash
npm install prom-client express-prom-bundle
npm install --save-dev @types/express-prom-bundle
```

### Create Metrics Service

```typescript
// src/services/metrics.service.ts
import { Registry, Counter, Histogram, Gauge } from 'prom-client';

class MetricsService {
  public registry: Registry;

  // HTTP metrics
  public httpRequestDuration: Histogram;
  public httpRequestTotal: Counter;
  public httpRequestErrors: Counter;

  // Business metrics
  public activeUsers: Gauge;
  public databaseConnections: Gauge;
  public authenticationAttempts: Counter;
  public authenticationFailures: Counter;

  constructor() {
    this.registry = new Registry();

    // HTTP request duration histogram
    this.httpRequestDuration = new Histogram({
      name: 'http_request_duration_seconds',
      help: 'Duration of HTTP requests in seconds',
      labelNames: ['method', 'route', 'status_code'],
      buckets: [0.1, 0.5, 1, 2, 5, 10]
    });

    // HTTP request counter
    this.httpRequestTotal = new Counter({
      name: 'http_requests_total',
      help: 'Total number of HTTP requests',
      labelNames: ['method', 'route', 'status_code']
    });

    // HTTP error counter
    this.httpRequestErrors = new Counter({
      name: 'http_request_errors_total',
      help: 'Total number of HTTP request errors',
      labelNames: ['method', 'route', 'error_type']
    });

    // Active users gauge
    this.activeUsers = new Gauge({
      name: 'active_users_total',
      help: 'Number of currently active users'
    });

    // Database connections gauge
    this.databaseConnections = new Gauge({
      name: 'database_connections_active',
      help: 'Number of active database connections'
    });

    // Authentication metrics
    this.authenticationAttempts = new Counter({
      name: 'authentication_attempts_total',
      help: 'Total number of authentication attempts',
      labelNames: ['method']
    });

    this.authenticationFailures = new Counter({
      name: 'authentication_failures_total',
      help: 'Total number of failed authentication attempts',
      labelNames: ['method', 'reason']
    });

    // Register all metrics
    this.registry.registerMetric(this.httpRequestDuration);
    this.registry.registerMetric(this.httpRequestTotal);
    this.registry.registerMetric(this.httpRequestErrors);
    this.registry.registerMetric(this.activeUsers);
    this.registry.registerMetric(this.databaseConnections);
    this.registry.registerMetric(this.authenticationAttempts);
    this.registry.registerMetric(this.authenticationFailures);

    // Collect default metrics (CPU, memory, etc.)
    this.registry.setDefaultLabels({
      app: 'rest-api',
      environment: process.env.NODE_ENV || 'development'
    });
  }

  /**
   * Get metrics in Prometheus format
   */
  async getMetrics(): Promise<string> {
    return this.registry.metrics();
  }
}

export const metricsService = new MetricsService();
```

### Metrics Middleware

```typescript
// src/middleware/metrics.middleware.ts
import { Request, Response, NextFunction } from 'express';
import { metricsService } from '../services/metrics.service';

export const metricsMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  const start = Date.now();

  // Capture response finish event
  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route?.path || req.path;
    const method = req.method;
    const statusCode = res.statusCode.toString();

    // Record metrics
    metricsService.httpRequestDuration.observe(
      { method, route, status_code: statusCode },
      duration
    );

    metricsService.httpRequestTotal.inc({
      method,
      route,
      status_code: statusCode
    });

    // Track errors
    if (statusCode.startsWith('4') || statusCode.startsWith('5')) {
      metricsService.httpRequestErrors.inc({
        method,
        route,
        error_type: statusCode.startsWith('4') ? 'client_error' : 'server_error'
      });
    }
  });

  next();
};
```

### Metrics Endpoint

```typescript
// src/routes/metrics.routes.ts
import { Router, Request, Response } from 'express';
import { metricsService } from '../services/metrics.service';

const router = Router();

router.get('/metrics', async (req: Request, res: Response) => {
  try {
    res.set('Content-Type', metricsService.registry.contentType);
    const metrics = await metricsService.getMetrics();
    res.send(metrics);
  } catch (error) {
    res.status(500).send('Error collecting metrics');
  }
});

export default router;
```

### Integrate Metrics in App

```typescript
// src/app.ts
import express from 'express';
import { metricsMiddleware } from './middleware/metrics.middleware';
import metricsRouter from './routes/metrics.routes';

const app = express();

// Apply metrics middleware early in the chain
app.use(metricsMiddleware);

// Other middleware...
app.use(express.json());

// Routes
app.use('/api', metricsRouter);
// ... other routes

export default app;
```

## Structured Logging with Winston

### Install Dependencies

```bash
npm install winston winston-daily-rotate-file
```

### Configure Logger

```typescript
// src/utils/logger.ts
import winston from 'winston';
import DailyRotateFile from 'winston-daily-rotate-file';

const logLevels = {
  error: 0,
  warn: 1,
  info: 2,
  http: 3,
  debug: 4,
};

const logColors = {
  error: 'red',
  warn: 'yellow',
  info: 'green',
  http: 'magenta',
  debug: 'blue',
};

winston.addColors(logColors);

// Custom format for structured logging
const logFormat = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.errors({ stack: true }),
  winston.format.metadata(),
  winston.format.json()
);

// Console format for development
const consoleFormat = winston.format.combine(
  winston.format.colorize({ all: true }),
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.printf(
    (info) => `${info.timestamp} ${info.level}: ${info.message}`
  )
);

// File rotation transport
const fileRotateTransport = new DailyRotateFile({
  filename: 'logs/application-%DATE%.log',
  datePattern: 'YYYY-MM-DD',
  maxSize: '20m',
  maxFiles: '14d',
  format: logFormat,
});

// Error log rotation
const errorRotateTransport = new DailyRotateFile({
  filename: 'logs/error-%DATE%.log',
  datePattern: 'YYYY-MM-DD',
  maxSize: '20m',
  maxFiles: '30d',
  level: 'error',
  format: logFormat,
});

const transports: winston.transport[] = [
  fileRotateTransport,
  errorRotateTransport,
];

// Add console transport in development
if (process.env.NODE_ENV !== 'production') {
  transports.push(
    new winston.transports.Console({
      format: consoleFormat,
    })
  );
}

export const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  levels: logLevels,
  transports,
  exitOnError: false,
});

// Create a stream for Morgan HTTP logging
export const logStream = {
  write: (message: string) => {
    logger.http(message.trim());
  },
};
```

### HTTP Request Logging

```typescript
// src/middleware/logging.middleware.ts
import morgan from 'morgan';
import { logStream } from '../utils/logger';

// Custom Morgan token for request ID
morgan.token('request-id', (req: any) => req.id);

// Custom format with request ID
const morganFormat = ':method :url :status :response-time ms - :request-id';

export const httpLogger = morgan(morganFormat, { stream: logStream });
```

### Contextual Logging in Controllers

```typescript
// src/controllers/user.controller.ts
import { Request, Response } from 'express';
import { logger } from '../utils/logger';
import { userService } from '../services/user.service';

export class UserController {
  async getUser(req: Request, res: Response): Promise<void> {
    const userId = req.params.id;

    logger.info('Fetching user', {
      userId,
      requestId: (req as any).id,
      ip: req.ip,
    });

    try {
      const user = await userService.findById(userId);

      if (!user) {
        logger.warn('User not found', { userId });
        res.status(404).json({ error: 'User not found' });
        return;
      }

      logger.info('User fetched successfully', { userId });
      res.json({ user });
    } catch (error) {
      logger.error('Error fetching user', {
        userId,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
      });

      res.status(500).json({ error: 'Internal server error' });
    }
  }
}
```

## Health Checks and Readiness Probes

### Comprehensive Health Check

```typescript
// src/routes/health.routes.ts
import { Router, Request, Response } from 'express';
import { prisma } from '../config/database';
import { logger } from '../utils/logger';

const router = Router();

interface HealthStatus {
  status: 'healthy' | 'unhealthy' | 'degraded';
  timestamp: string;
  uptime: number;
  checks: {
    database: boolean;
    memory: boolean;
    disk?: boolean;
  };
  details?: any;
}

/**
 * Liveness probe - is the application running?
 */
router.get('/health/live', (req: Request, res: Response) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * Readiness probe - is the application ready to serve traffic?
 */
router.get('/health/ready', async (req: Request, res: Response) => {
  const health: HealthStatus = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    checks: {
      database: false,
      memory: false,
    },
  };

  try {
    // Check database connection
    await prisma.$queryRaw`SELECT 1`;
    health.checks.database = true;
  } catch (error) {
    health.status = 'unhealthy';
    health.checks.database = false;
    logger.error('Database health check failed', { error });
  }

  // Check memory usage
  const memUsage = process.memoryUsage();
  const memThreshold = 0.9; // 90% threshold
  const heapUsedPercent = memUsage.heapUsed / memUsage.heapTotal;

  health.checks.memory = heapUsedPercent < memThreshold;

  if (!health.checks.memory) {
    health.status = health.status === 'unhealthy' ? 'unhealthy' : 'degraded';
  }

  health.details = {
    memory: {
      heapUsed: `${Math.round(memUsage.heapUsed / 1024 / 1024)}MB`,
      heapTotal: `${Math.round(memUsage.heapTotal / 1024 / 1024)}MB`,
      external: `${Math.round(memUsage.external / 1024 / 1024)}MB`,
    },
  };

  const statusCode = health.status === 'healthy' ? 200 : 503;
  res.status(statusCode).json(health);
});

