### 5.3 OAuth 2.0 Integration (Google Example)

**src/services/oauth.service.js:**
```javascript
const { OAuth2Client } = require('google-auth-library');
const User = require('../models/user.model');
const authService = require('./auth.service');
const ApiError = require('../utils/ApiError');

const client = new OAuth2Client(process.env.GOOGLE_CLIENT_ID);

class OAuthService {
  /**
   * Verify Google token and login/register user
   */
  static async googleAuth(token, req) {
    try {
      // Verify token with Google
      const ticket = await client.verifyIdToken({
        idToken: token,
        audience: process.env.GOOGLE_CLIENT_ID
      });

      const payload = ticket.getPayload();
      const { email, given_name, family_name, picture, sub } = payload;

      // Check if user exists
      let user = await User.findByEmail(email);

      if (!user) {
        // Create new user
        user = await User.create({
          email,
          username: email.split('@')[0] + '_' + sub.substring(0, 6),
          firstName: given_name,
          lastName: family_name,
          password: crypto.randomBytes(32).toString('hex'), // Random password
          isEmailVerified: true,
          authProvider: 'google',
          authProviderId: sub
        });
      }

      // Generate tokens
      const accessToken = authService.generateAccessToken(user.id, user.role);
      const refreshToken = authService.generateRefreshToken(user.id);

      // Store refresh token
      await authService.storeRefreshToken(user.id, refreshToken, req);

      // Update last login
      await User.updateLastLogin(user.id);

      return {
        user: User.sanitize(user),
        accessToken,
        refreshToken
      };
    } catch (error) {
      throw new ApiError(401, 'Invalid Google token');
    }
  }
}

module.exports = OAuthService;
```

### 5.4 Two-Factor Authentication (2FA)

**src/services/twoFactor.service.js:**
```javascript
const speakeasy = require('speakeasy');
const QRCode = require('qrcode');
const User = require('../models/user.model');
const ApiError = require('../utils/ApiError');

class TwoFactorService {
  /**
   * Generate 2FA secret
   */
  static async generateSecret(userId) {
    const user = await User.findById(userId);
    if (!user) {
      throw new ApiError(404, 'User not found');
    }

    const secret = speakeasy.generateSecret({
      name: `ProductionAPI (${user.email})`,
      length: 32
    });

    // Store secret temporarily (not enabled yet)
    await User.update(userId, {
      twoFactorSecret: secret.base32,
      twoFactorEnabled: false
    });

    // Generate QR code
    const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url);

    return {
      secret: secret.base32,
      qrCode: qrCodeUrl
    };
  }

  /**
   * Enable 2FA
   */
  static async enable(userId, token) {
    const user = await User.findById(userId);
    if (!user || !user.twoFactorSecret) {
      throw new ApiError(400, '2FA secret not generated');
    }

    // Verify token
    const verified = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2
    });

    if (!verified) {
      throw new ApiError(400, 'Invalid 2FA token');
    }

    // Enable 2FA
    await User.update(userId, {
      twoFactorEnabled: true
    });

    // Generate backup codes
    const backupCodes = this.generateBackupCodes();
    await this.storeBackupCodes(userId, backupCodes);

    return { backupCodes };
  }

  /**
   * Verify 2FA token
   */
  static async verify(userId, token) {
    const user = await User.findById(userId);
    if (!user || !user.twoFactorEnabled) {
      throw new ApiError(400, '2FA not enabled');
    }

    // Try regular token
    const verified = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2
    });

    if (verified) {
      return true;
    }

    // Try backup code
    const backupCodeValid = await this.verifyBackupCode(userId, token);
    return backupCodeValid;
  }

  /**
   * Disable 2FA
   */
  static async disable(userId, password) {
    const user = await User.findById(userId);
    if (!user) {
      throw new ApiError(404, 'User not found');
    }

    // Verify password
    const isPasswordValid = await User.verifyPassword(password, user.password);
    if (!isPasswordValid) {
      throw new ApiError(401, 'Invalid password');
    }

    await User.update(userId, {
      twoFactorEnabled: false,
      twoFactorSecret: null
    });

    await this.deleteBackupCodes(userId);
  }

  /**
   * Generate backup codes
   */
  static generateBackupCodes(count = 10) {
    const codes = [];
    for (let i = 0; i < count; i++) {
      codes.push(crypto.randomBytes(4).toString('hex').toUpperCase());
    }
    return codes;
  }

  /**
   * Store backup codes
   */
  static async storeBackupCodes(userId, codes) {
    const hashedCodes = await Promise.all(
      codes.map(code => bcrypt.hash(code, 10))
    );

    await db('backup_codes').insert(
      hashedCodes.map(hash => ({
        userId,
        code: hash,
        used: false
      }))
    );
  }

  /**
   * Verify backup code
   */
  static async verifyBackupCode(userId, code) {
    const backupCodes = await db('backup_codes')
      .where({ userId, used: false });

    for (const backupCode of backupCodes) {
      const isValid = await bcrypt.compare(code, backupCode.code);
      if (isValid) {
        // Mark as used
        await db('backup_codes')
          .where({ id: backupCode.id })
          .update({ used: true });
        return true;
      }
    }

    return false;
  }

  /**
   * Delete backup codes
   */
  static async deleteBackupCodes(userId) {
    await db('backup_codes').where({ userId }).delete();
  }
}

module.exports = TwoFactorService;
```

