### 10.3 Metrics Collection with Prometheus

Install Prometheus client:

```bash
npm install prom-client
```

**Metrics Service:**

```typescript
// src/services/metrics.service.ts
import { Registry, Counter, Histogram, Gauge } from 'prom-client';

class MetricsService {
  public registry: Registry;
  public httpRequestDuration: Histogram;
  public httpRequestTotal: Counter;
  public httpRequestErrors: Counter;
  public activeConnections: Gauge;
  public databaseConnections: Gauge;

  constructor() {
    this.registry = new Registry();

    // HTTP request duration histogram
    this.httpRequestDuration = new Histogram({
      name: 'http_request_duration_seconds',
      help: 'Duration of HTTP requests in seconds',
      labelNames: ['method', 'route', 'status_code'],
      buckets: [0.1, 0.5, 1, 2, 5, 10]
    });

    // HTTP request counter
    this.httpRequestTotal = new Counter({
      name: 'http_requests_total',
      help: 'Total number of HTTP requests',
      labelNames: ['method', 'route', 'status_code']
    });

    // HTTP error counter
    this.httpRequestErrors = new Counter({
      name: 'http_request_errors_total',
      help: 'Total number of HTTP request errors',
      labelNames: ['method', 'route', 'error_type']
    });

    // Active connections gauge
    this.activeConnections = new Gauge({
      name: 'active_connections',
      help: 'Number of active connections'
    });

    // Database connections gauge
    this.databaseConnections = new Gauge({
      name: 'database_connections',
      help: 'Number of database connections',
      labelNames: ['state'] // active, idle
    });

    // Register all metrics
    this.registry.registerMetric(this.httpRequestDuration);
    this.registry.registerMetric(this.httpRequestTotal);
    this.registry.registerMetric(this.httpRequestErrors);
    this.registry.registerMetric(this.activeConnections);
    this.registry.registerMetric(this.databaseConnections);

    // Collect default metrics (CPU, memory, etc.)
    const collectDefaultMetrics = require('prom-client').collectDefaultMetrics;
    collectDefaultMetrics({ register: this.registry });
  }

  // Custom business metrics
  public recordLogin(success: boolean) {
    const loginCounter = new Counter({
      name: 'user_logins_total',
      help: 'Total number of user login attempts',
      labelNames: ['status']
    });
    this.registry.registerMetric(loginCounter);
    loginCounter.inc({ status: success ? 'success' : 'failure' });
  }

  public recordApiCall(endpoint: string, duration: number) {
    const apiCallHistogram = new Histogram({
      name: 'api_call_duration_seconds',
      help: 'Duration of external API calls',
      labelNames: ['endpoint'],
      buckets: [0.1, 0.5, 1, 2, 5]
    });
    this.registry.registerMetric(apiCallHistogram);
    apiCallHistogram.observe({ endpoint }, duration);
  }
}

export const metricsService = new MetricsService();
```

**Metrics Middleware:**

```typescript
// src/middleware/metrics.middleware.ts
import { Request, Response, NextFunction } from 'express';
import { metricsService } from '../services/metrics.service';

export const metricsMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  const start = Date.now();

  // Increment active connections
  metricsService.activeConnections.inc();

  // Record metrics after response
  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route?.path || req.path;

    metricsService.httpRequestDuration.observe(
      {
        method: req.method,
        route,
        status_code: res.statusCode
      },
      duration
    );

    metricsService.httpRequestTotal.inc({
      method: req.method,
      route,
      status_code: res.statusCode
    });

    // Decrement active connections
    metricsService.activeConnections.dec();

    // Record errors
    if (res.statusCode >= 400) {
      metricsService.httpRequestErrors.inc({
        method: req.method,
        route,
        error_type: res.statusCode >= 500 ? 'server_error' : 'client_error'
      });
    }
  });

  next();
};
```

**Metrics Endpoint:**

```typescript
// src/routes/metrics.routes.ts
import { Router, Request, Response } from 'express';
import { metricsService } from '../services/metrics.service';

const router = Router();

router.get('/metrics', async (req: Request, res: Response) => {
  res.set('Content-Type', metricsService.registry.contentType);
  const metrics = await metricsService.registry.metrics();
  res.send(metrics);
});

export default router;
```

### 10.4 Structured Logging with Winston

Enhance the logging from Section 7:

```typescript
// src/utils/logger.ts
import winston from 'winston';
import { ElasticsearchTransport } from 'winston-elasticsearch';

const esTransportOpts = {
  level: 'info',
  clientOpts: {
    node: process.env.ELASTICSEARCH_URL || 'http://localhost:9200'
  },
  index: 'api-logs'
};

export const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: {
    service: 'rest-api',
    environment: process.env.NODE_ENV
  },
  transports: [
    // Console transport
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    // File transports
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),
    new winston.transports.File({
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5
    })
  ]
});

// Add Elasticsearch in production
if (process.env.NODE_ENV === 'production') {
  logger.add(new ElasticsearchTransport(esTransportOpts));
}

// Request logging middleware
export const requestLogger = (req: any, res: any, next: any) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info('HTTP Request', {
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id
    });
  });

  next();
};
```

### 10.5 Distributed Tracing with OpenTelemetry

```bash
npm install @opentelemetry/sdk-node @opentelemetry/auto-instrumentations-node \
  @opentelemetry/exporter-jaeger @opentelemetry/resources @opentelemetry/semantic-conventions
```

```typescript
// src/tracing.ts
import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';

const jaegerExporter = new JaegerExporter({
  endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces'
});

const sdk = new NodeSDK({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'rest-api',
    [SemanticResourceAttributes.SERVICE_VERSION]: '1.0.0'
  }),
  traceExporter: jaegerExporter,
  instrumentations: [
    getNodeAutoInstrumentations({
      '@opentelemetry/instrumentation-fs': {
        enabled: false
      }
    })
  ]
});

sdk.start();

process.on('SIGTERM', () => {
  sdk.shutdown()
    .then(() => console.log('Tracing terminated'))
    .catch((error) => console.log('Error terminating tracing', error))
    .finally(() => process.exit(0));
});

export default sdk;
```

### 10.6 Health Check Endpoints

Implement comprehensive health checks:

```typescript
// src/routes/health.routes.ts
import { Router, Request, Response } from 'express';
import { AppDataSource } from '../config/database';
import { redisClient } from '../config/redis';

const router = Router();

// Liveness probe - is the app running?
router.get('/health/live', (req: Request, res: Response) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Readiness probe - is the app ready to serve traffic?
router.get('/health/ready', async (req: Request, res: Response) => {
  const checks = {
    database: false,
    redis: false
  };

  try {
    // Check database
    await AppDataSource.query('SELECT 1');
    checks.database = true;

    // Check Redis
    await redisClient.ping();
    checks.redis = true;

    const allHealthy = Object.values(checks).every(check => check === true);

    res.status(allHealthy ? 200 : 503).json({
      status: allHealthy ? 'ready' : 'not ready',
      checks,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    res.status(503).json({
      status: 'not ready',
      checks,
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Detailed health check
router.get('/health', async (req: Request, res: Response) => {
  const health = {
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    status: 'ok',
    checks: {
      database: { status: 'unknown' },
      redis: { status: 'unknown' },
      memory: { status: 'unknown' },
      disk: { status: 'unknown' }
    }
  };

  try {
    // Database check
    const dbStart = Date.now();
    await AppDataSource.query('SELECT 1');
    health.checks.database = {
      status: 'healthy',
      responseTime: Date.now() - dbStart
    };

    // Redis check
    const redisStart = Date.now();
    await redisClient.ping();
    health.checks.redis = {
      status: 'healthy',
      responseTime: Date.now() - redisStart
    };

    // Memory check
    const memUsage = process.memoryUsage();
    health.checks.memory = {
      status: 'healthy',
      heapUsed: `${Math.round(memUsage.heapUsed / 1024 / 1024)}MB`,
      heapTotal: `${Math.round(memUsage.heapTotal / 1024 / 1024)}MB`,
      rss: `${Math.round(memUsage.rss / 1024 / 1024)}MB`
    };

    res.status(200).json(health);
  } catch (error) {
    health.status = 'degraded';
    res.status(503).json(health);
  }
});

export default router;
```

### 10.7 Error Tracking with Sentry

```bash
npm install @sentry/node @sentry/tracing
```

```typescript
// src/config/sentry.ts
import * as Sentry from '@sentry/node';
import * as Tracing from '@sentry/tracing';
import { Express } from 'express';

export const initSentry = (app: Express) => {
  Sentry.init({
    dsn: process.env.SENTRY_DSN,
    environment: process.env.NODE_ENV,
    integrations: [
      new Sentry.Integrations.Http({ tracing: true }),
      new Tracing.Integrations.Express({ app }),
      new Tracing.Integrations.Postgres(),
      new Tracing.Integrations.Mysql()
    ],
    tracesSampleRate: process.env.NODE_ENV === 'production' ? 0.1 : 1.0,
    beforeSend(event, hint) {
      // Filter out sensitive data
      if (event.request) {
        delete event.request.cookies;
        delete event.request.headers?.authorization;
      }
      return event;
    }
  });

  // Request handler must be first
  app.use(Sentry.Handlers.requestHandler());
  app.use(Sentry.Handlers.tracingHandler());
};

export const sentryErrorHandler = Sentry.Handlers.errorHandler();
```

