### 5.2 Auth Controller

**src/controllers/auth.controller.js:**
```javascript
const authService = require('../services/auth.service');
const asyncHandler = require('../utils/asyncHandler');
const ApiResponse = require('../utils/ApiResponse');

class AuthController {
  /**
   * Register new user
   */
  register = asyncHandler(async (req, res) => {
    const result = await authService.register(req.body);

    res.status(201).json(
      new ApiResponse(201, result, 'User registered successfully')
    );
  });

  /**
   * Login user
   */
  login = asyncHandler(async (req, res) => {
    const { email, password } = req.body;
    const ipAddress = req.ip;
    const userAgent = req.get('user-agent');

    const result = await authService.login(email, password, ipAddress, userAgent);

    // Set refresh token in HTTP-only cookie
    res.cookie('refreshToken', result.tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    });

    res.status(200).json(
      new ApiResponse(200, {
        user: result.user,
        accessToken: result.tokens.accessToken,
      }, 'Login successful')
    );
  });

  /**
   * Refresh access token
   */
  refreshToken = asyncHandler(async (req, res) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;
    const ipAddress = req.ip;
    const userAgent = req.get('user-agent');

    const tokens = await authService.refreshToken(refreshToken, ipAddress, userAgent);

    // Update refresh token cookie
    res.cookie('refreshToken', tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 30 * 24 * 60 * 60 * 1000,
    });

    res.status(200).json(
      new ApiResponse(200, { accessToken: tokens.accessToken }, 'Token refreshed successfully')
    );
  });

  /**
   * Logout user
   */
  logout = asyncHandler(async (req, res) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

    await authService.logout(refreshToken);

    // Clear refresh token cookie
    res.clearCookie('refreshToken');

    res.status(200).json(
      new ApiResponse(200, null, 'Logout successful')
    );
  });

  /**
   * Verify email
   */
  verifyEmail = asyncHandler(async (req, res) => {
    const { token } = req.params;

    const result = await authService.verifyEmail(token);

    res.status(200).json(
      new ApiResponse(200, result, 'Email verified successfully')
    );
  });

  /**
   * Forgot password
   */
  forgotPassword = asyncHandler(async (req, res) => {
    const { email } = req.body;

    const result = await authService.forgotPassword(email);

    res.status(200).json(
      new ApiResponse(200, result, 'Password reset email sent')
    );
  });

  /**
   * Reset password
   */
  resetPassword = asyncHandler(async (req, res) => {
    const { token, password } = req.body;

    const result = await authService.resetPassword(token, password);

    res.status(200).json(
      new ApiResponse(200, result, 'Password reset successfully')
    );
  });

  /**
   * Change password
   */
  changePassword = asyncHandler(async (req, res) => {
    const { currentPassword, newPassword } = req.body;

    const result = await authService.changePassword(
      req.user.id,
      currentPassword,
      newPassword
    );

    res.status(200).json(
      new ApiResponse(200, result, 'Password changed successfully')
    );
  });
}

module.exports = new AuthController();
```

### 5.3 OAuth Integration (Optional)

**src/services/oauth.service.js:**
```javascript
const axios = require('axios');
const config = require('../config/environment');
const userModel = require('../models/user.model');
const authService = require('./auth.service');
const ApiError = require('../utils/ApiError');

class OAuthService {
  /**
   * Google OAuth
   */
  async googleAuth(code, ipAddress, userAgent) {
    try {
      // Exchange code for tokens
      const tokenResponse = await axios.post('https://oauth2.googleapis.com/token', {
        code,
        client_id: config.oauth.google.clientId,
        client_secret: config.oauth.google.clientSecret,
        redirect_uri: config.oauth.google.redirectUri,
        grant_type: 'authorization_code',
      });

      const { access_token } = tokenResponse.data;

      // Get user info
      const userResponse = await axios.get('https://www.googleapis.com/oauth2/v2/userinfo', {
        headers: { Authorization: `Bearer ${access_token}` },
      });

      const { email, given_name, family_name, id } = userResponse.data;

      // Find or create user
      let user = await userModel.findByEmail(email);

      if (!user) {
        user = await userModel.create({
          email,
          firstName: given_name,
          lastName: family_name,
          password: crypto.randomBytes(32).toString('hex'), // Random password
          emailVerified: true,
          oauthProvider: 'google',
          oauthId: id,
        });
      }

      // Generate tokens
      const tokens = await authService.generateTokenPair(user.id, ipAddress, userAgent);

      return {
        user: {
          id: user.id,
          email: user.email,
          firstName: user.firstName,
          lastName: user.lastName,
          role: user.role,
        },
        tokens,
      };
    } catch (error) {
      throw new ApiError(400, 'Google authentication failed');
    }
  }
}

module.exports = new OAuthService();
```

