### 5.4 OAuth 2.0 Integration

**src/services/oauth.service.js:**
```javascript
const axios = require('axios');
const config = require('../config/env');
const UserModel = require('../models/user.model');
const TokenService = require('./token.service');
const ApiError = require('../utils/ApiError');

class OAuthService {
  /**
   * Google OAuth login
   */
  static async googleLogin(code) {
    try {
      // Exchange code for tokens
      const tokenResponse = await axios.post('https://oauth2.googleapis.com/token', {
        code,
        client_id: config.google.clientId,
        client_secret: config.google.clientSecret,
        redirect_uri: config.google.redirectUri,
        grant_type: 'authorization_code',
      });

      const { access_token } = tokenResponse.data;

      // Get user info
      const userResponse = await axios.get('https://www.googleapis.com/oauth2/v2/userinfo', {
        headers: { Authorization: `Bearer ${access_token}` },
      });

      const { email, given_name, family_name, id: googleId } = userResponse.data;

      // Find or create user
      let user = await UserModel.findByEmail(email);

      if (!user) {
        user = await UserModel.create({
          email,
          firstName: given_name,
          lastName: family_name,
          password: crypto.randomBytes(32).toString('hex'), // Random password
          emailVerified: true,
          googleId,
        });
      }

      // Generate tokens
      const accessToken = TokenService.generateAccessToken(user.id, user.role);
      const refreshToken = TokenService.generateRefreshToken();

      await TokenService.saveRefreshToken(user.id, refreshToken);

      return {
        user: UserModel.sanitize(user),
        accessToken,
        refreshToken,
      };
    } catch (error) {
      throw new ApiError(401, 'Google authentication failed');
    }
  }

  /**
   * GitHub OAuth login
   */
  static async githubLogin(code) {
    // Similar implementation for GitHub
  }
}

module.exports = OAuthService;
```

### 5.5 Two-Factor Authentication

**src/services/twoFactor.service.js:**
```javascript
const speakeasy = require('speakeasy');
const QRCode = require('qrcode');
const UserModel = require('../models/user.model');
const ApiError = require('../utils/ApiError');

class TwoFactorService {
  /**
   * Generate 2FA secret
   */
  static async generateSecret(userId) {
    const user = await UserModel.findById(userId);

    const secret = speakeasy.generateSecret({
      name: `ProductionAPI (${user.email})`,
      length: 32,
    });

    // Save secret to user (encrypted in production)
    await UserModel.update(userId, {
      twoFactorSecret: secret.base32,
      twoFactorEnabled: false, // Not enabled until verified
    });

    // Generate QR code
    const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url);

    return {
      secret: secret.base32,
      qrCode: qrCodeUrl,
    };
  }

  /**
   * Verify and enable 2FA
   */
  static async enableTwoFactor(userId, token) {
    const user = await db('users').where({ id: userId }).first();

    if (!user.twoFactorSecret) {
      throw new ApiError(400, '2FA secret not generated');
    }

    const isValid = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2,
    });

    if (!isValid) {
      throw new ApiError(400, 'Invalid 2FA token');
    }

    await UserModel.update(userId, {
      twoFactorEnabled: true,
    });

    return { message: '2FA enabled successfully' };
  }

  /**
   * Verify 2FA token
   */
  static async verifyToken(userId, token) {
    const user = await db('users').where({ id: userId }).first();

    if (!user.twoFactorEnabled) {
      throw new ApiError(400, '2FA not enabled');
    }

    const isValid = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2,
    });

    if (!isValid) {
      throw new ApiError(401, 'Invalid 2FA token');
    }

    return true;
  }

  /**
   * Disable 2FA
   */
  static async disableTwoFactor(userId, token) {
    await this.verifyToken(userId, token);

    await UserModel.update(userId, {
      twoFactorEnabled: false,
      twoFactorSecret: null,
    });

    return { message: '2FA disabled successfully' };
  }
}

module.exports = TwoFactorService;
```

