### 6.3 Custom Validation Rules

**src/validators/custom.validator.js:**
```javascript
const Joi = require('joi');

/**
 * Custom phone number validation
 */
const phoneNumber = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Please provide a valid phone number',
  });

/**
 * Custom URL validation
 */
const url = Joi.string()
  .uri({ scheme: ['http', 'https'] })
  .messages({
    'string.uri': 'Please provide a valid URL',
  });

/**
 * Custom date range validation
 */
const dateRange = Joi.object({
  startDate: Joi.date()
    .iso()
    .required(),

  endDate: Joi.date()
    .iso()
    .min(Joi.ref('startDate'))
    .required()
    .messages({
      'date.min': 'End date must be after start date',
    }),
});

/**
 * Custom file upload validation
 */
const fileUpload = Joi.object({
  filename: Joi.string()
    .required(),

  mimetype: Joi.string()
    .valid('image/jpeg', 'image/png', 'image/gif', 'application/pdf')
    .required()
    .messages({
      'any.only': 'File type not allowed',
    }),

  size: Joi.number()
    .max(5 * 1024 * 1024) // 5MB
    .required()
    .messages({
      'number.max': 'File size cannot exceed 5MB',
    }),
});

/**
 * Custom credit card validation
 */
const creditCard = Joi.string()
  .creditCard()
  .messages({
    'string.creditCard': 'Please provide a valid credit card number',
  });

/**
 * Custom postal code validation
 */
const postalCode = Joi.alternatives().try(
  Joi.string().pattern(/^\d{5}$/), // US
  Joi.string().pattern(/^[A-Z]\d[A-Z] \d[A-Z]\d$/), // Canada
  Joi.string().pattern(/^[A-Z]{1,2}\d{1,2} \d[A-Z]{2}$/), // UK
);

/**
 * Custom password strength validation
 */
const strongPassword = Joi.string()
  .min(12)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .custom((value, helpers) => {
    // Check for common passwords
    const commonPasswords = ['password123', 'admin123', 'qwerty123'];
    if (commonPasswords.includes(value.toLowerCase())) {
      return helpers.error('password.common');
    }
