### 10.10 Performance Profiling

Monitor and optimize performance:

```javascript
// utils/profiler.js
const logger = require('./logger');

class Profiler {
  static async profileFunction(fn, name) {
    const start = process.hrtime.bigint();
    const memBefore = process.memoryUsage();

    try {
      const result = await fn();
      const end = process.hrtime.bigint();
      const memAfter = process.memoryUsage();

      const duration = Number(end - start) / 1000000; // Convert to ms
      const memDiff = memAfter.heapUsed - memBefore.heapUsed;

      logger.debug('Function profiled', {
        function: name,
        duration: `${duration.toFixed(2)}ms`,
        memoryDelta: `${Math.round(memDiff / 1024)}KB`
      });

      return result;
    } catch (error) {
      logger.error('Profiled function error', {
        function: name,
        error: error.message
      });
      throw error;
    }
  }

  static startCPUProfile() {
    if (process.env.NODE_ENV === 'production') return;

    const profiler = require('v8-profiler-next');
    const title = `profile-${Date.now()}`;
    profiler.startProfiling(title, true);

    return () => {
      const profile = profiler.stopProfiling(title);
      profile.export((error, result) => {
        if (error) {
          logger.error('CPU profile export failed', { error });
          return;
        }
        require('fs').writeFileSync(`./profiles/${title}.cpuprofile`, result);
        profile.delete();
      });
    };
  }
}

module.exports = Profiler;
```

### 10.11 Business Metrics Tracking

Track business-relevant metrics:

```javascript
// utils/businessMetrics.js
const { Counter, Gauge } = require('prom-client');

const userRegistrations = new Counter({
  name: 'user_registrations_total',
  help: 'Total number of user registrations'
});

const activeUsers = new Gauge({
  name: 'active_users',
  help: 'Number of currently active users'
});

const apiCallsByEndpoint = new Counter({
  name: 'api_calls_by_endpoint',
  help: 'API calls grouped by endpoint',
  labelNames: ['endpoint', 'user_type']
});

const revenueMetric = new Counter({
  name: 'revenue_total',
  help: 'Total revenue generated',
  labelNames: ['currency']
});

module.exports = {
  userRegistrations,
  activeUsers,
  apiCallsByEndpoint,
  revenueMetric
};
```

### 10.12 SLA/SLO Definition

Define Service Level Objectives:

```javascript
// config/slo.js
module.exports = {
  availability: {
    target: 99.9, // 99.9% uptime
    measurement: 'monthly',
    allowedDowntime: '43.2 minutes/month'
  },

  performance: {
    p95ResponseTime: 500, // ms
    p99ResponseTime: 1000, // ms
    target: 'API responses under threshold 95% of the time'
  },

  errorRate: {
    target: 0.1, // 0.1% error rate
    measurement: '5xx errors / total requests'
  },

  dataFreshness: {
    target: 5, // seconds
    description: 'Data updated within 5 seconds'
  }
};
```

### 10.13 Incident Response Workflow

```javascript
// utils/incidentManager.js
const logger = require('./logger');
const alertManager = require('./alerting');

class IncidentManager {
  async detectIncident(metrics) {
    const incidents = [];

    // Check for high error rate
    if (metrics.errorRate > 10) {
      incidents.push({
        severity: 'critical',
        type: 'high_error_rate',
        description: `Error rate at ${metrics.errorRate}%`,
        threshold: '10%'
      });
    }

    // Check for slow responses
    if (metrics.p99ResponseTime > 5000) {
      incidents.push({
        severity: 'warning',
        type: 'slow_response',
        description: `P99 response time at ${metrics.p99ResponseTime}ms`,
        threshold: '5000ms'
      });
    }

    // Check for database issues
    if (metrics.dbConnectionErrors > 0) {
      incidents.push({
        severity: 'critical',
        type: 'database_connection',
        description: 'Database connection failures detected',
        count: metrics.dbConnectionErrors
      });
    }

    return incidents;
  }

  async handleIncident(incident) {
    logger.error('Incident detected', incident);

    // Send alerts based on severity
    if (incident.severity === 'critical') {
      await alertManager.triggerPagerDuty(
        incident.description,
        incident
      );
    }

    await alertManager.sendSlackAlert(
      `${incident.type}: ${incident.description}`,
      incident.severity
    );

    // Log to incident tracking system
    await this.logIncident(incident);
  }

  async logIncident(incident) {
    // Store in database or external incident management system
    logger.info('Incident logged', {
      ...incident,
      timestamp: new Date().toISOString()
    });
  }
}

module.exports = new IncidentManager();
```

### 10.14 Monitoring Best Practices

**1. Monitor What Matters**
- Focus on user-impacting metrics
- Avoid alert fatigue with too many notifications
- Use the RED method: Rate, Errors, Duration

**2. Set Meaningful Alerts**
- Alert on symptoms, not causes
- Use appropriate thresholds
- Include context in alert messages

**3. Implement Gradual Degradation**
```javascript
// Example: Graceful degradation
async function getRecommendations(userId) {
  try {
    return await recommendationService.get(userId);
  } catch (error) {
    logger.warn('Recommendation service unavailable, using fallback');
    return getFallbackRecommendations(userId);
  }
}
```

**4. Regular Review**
- Review dashboards weekly
- Analyze trends monthly
- Update thresholds based on actual performance

**5. Cost Optimization**
- Sample high-volume metrics
- Adjust retention periods
- Use appropriate log levels in production

### 10.15 Complete Monitoring Setup

```javascript
// server.js - Final integration
require('./config/apm'); // APM must be first
const express = require('express');
const metricsMiddleware = require('./middleware/metrics');
const requestLogger = require('./middleware/requestLogger');
const healthRoutes = require('./routes/health');
const metricsRoutes = require('./routes/metrics');
const logger = require('./utils/logger');

const app = express();

// Monitoring middleware
app.use(requestLogger);
app.use(metricsMiddleware);

// Health and metrics endpoints
app.use(healthRoutes);
app.use(metricsRoutes);

// ... other routes and middleware

// Error tracking
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    requestId: req.id
  });

  // Track error in APM
  if (global.apm) {
    global.apm.captureError(err);
  }

  res.status(500).json({ error: 'Internal server error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server started on port ${PORT}`, {
    environment: process.env.NODE_ENV,
    nodeVersion: process.version
  });
});
```

### 10.16 Monitoring Checklist

✅ **Metrics Collection**
- [ ] APM solution configured
- [ ] Custom metrics implemented
- [ ] Prometheus endpoint exposed
- [ ] Business metrics tracked

✅ **Logging**
- [ ] Structured logging with Winston
- [ ] Log rotation configured
- [ ] Request IDs for tracing
- [ ] Appropriate log levels set

✅ **Health Checks**
- [ ] Liveness probe implemented
- [ ] Readiness probe implemented
- [ ] Dependency checks included

✅ **Alerting**
- [ ] Critical alerts configured
- [ ] Notification channels set up
- [ ] Alert thresholds defined
- [ ] On-call rotation established

✅ **Dashboards**
- [ ] Grafana dashboards created
- [ ] Key metrics visualized
- [ ] Team has access
- [ ] Mobile-friendly views

✅ **Incident Management**
- [ ] Incident response plan documented
- [ ] Runbooks created
- [ ] Post-mortem process defined
- [ ] SLO/SLA documented

### Conclusion

Monitoring and observability complete your production-ready REST API. With comprehensive metrics, logging, tracing, and alerting in place, you can:

- **Detect issues** before users report them
- **Diagnose problems** quickly with detailed traces
- **Optimize performance** based on real data
- **Meet SLAs** with proactive monitoring
- **Make data-driven decisions** about infrastructure and features

This monitoring foundation, combined with the previous nine sections (Project Setup, Routing, Middleware, Database, Authentication, Validation, Error Handling, Testing, and Deployment), provides everything needed to build, deploy, and maintain a robust, production-ready REST API.

**Remember**: Monitoring is not a one-time setup—it's an ongoing practice. Continuously refine your dashboards, adjust alert thresholds, and improve observability as your API evolves.

