### Performance Monitoring Service

Create `src/monitoring/performance.ts`:

```typescript
import { performance } from 'perf_hooks';
import { logger } from './logger';

export class PerformanceMonitor {
  private measurements: Map<string, number[]> = new Map();

  startMeasurement(name: string): () => void {
    const start = performance.now();

    return () => {
      const duration = performance.now() - start;
      this.recordMeasurement(name, duration);
    };
  }

  private recordMeasurement(name: string, duration: number): void {
    if (!this.measurements.has(name)) {
      this.measurements.set(name, []);
    }

    const measurements = this.measurements.get(name)!;
    measurements.push(duration);

    // Keep only last 100 measurements
    if (measurements.length > 100) {
      measurements.shift();
    }
  }

  getStats(name: string): {
    avg: number;
    min: number;
    max: number;
    p95: number;
  } | null {
    const measurements = this.measurements.get(name);

    if (!measurements || measurements.length === 0) {
      return null;
    }

    const sorted = [...measurements].sort((a, b) => a - b);
    const sum = sorted.reduce((a, b) => a + b, 0);

    return {
      avg: sum / sorted.length,
      min: sorted[0],
      max: sorted[sorted.length - 1],
      p95: sorted[Math.floor(sorted.length * 0.95)],
    };
  }

  logStats(): void {
    for (const [name, _] of this.measurements) {
      const stats = this.getStats(name);
      if (stats) {
        logger.info('Performance stats', { operation: name, ...stats });
      }
    }
  }
}

export const performanceMonitor = new PerformanceMonitor();

// Log stats every 5 minutes
setInterval(() => {
  performanceMonitor.logStats();
}, 5 * 60 * 1000);
```

### Update Application with Monitoring

Update `src/app.ts`:

```typescript
import express, { Application } from 'express';
import { config } from './config';
import { registerMiddleware } from './middleware';
import { RouteRegistry } from './routes/registry';
import { metricsMiddleware } from './middleware/metrics.middleware';
import metricsRoutes from './routes/metrics.routes';
import healthRoutes from './routes/health.routes';

const app: Application = express();

// Metrics middleware (early in chain)
app.use(metricsMiddleware);

// Register all middleware
registerMiddleware(app);

// Health and metrics endpoints
app.use(healthRoutes);
app.use(metricsRoutes);

// Register API routes
RouteRegistry.register(app);

export default app;
```

Update `src/server.ts`:

```typescript
// Initialize tracing first
if (process.env.ENABLE_TRACING === 'true') {
  require('./monitoring/tracing').initTracing();
}

// Then New Relic
if (process.env.NEW_RELIC_LICENSE_KEY) {
  require('newrelic');
}

import app from './app';
import { config } from './config';
import { connectDatabase, disconnectDatabase } from './config/database';
import { logger } from './monitoring/logger';
import { register } from './monitoring/metrics';

async function startServer() {
  try {
    config.validate();
    await connectDatabase();

    const PORT = config.port;

    const server = app.listen(PORT, () => {
      logger.info('Server started', {
        port: PORT,
        environment: config.env,
        version: process.env.npm_package_version,
      });
    });

    // Graceful shutdown
    const shutdown = async (signal: string) => {
      logger.info('Shutdown initiated', { signal });

      server.close(async () => {
        logger.info('HTTP server closed');

        try {
          await disconnectDatabase();
          await register.clear();
          logger.info('Cleanup completed');
          process.exit(0);
        } catch (error) {
          logger.error('Error during shutdown', { error });
          process.exit(1);
        }
      });

      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

  } catch (error) {
    logger.error('Failed to start server', { error });
    process.exit(1);
  }
}

startServer();
```

### Monitoring Docker Compose

Create `monitoring/docker-compose.monitoring.yml`:

```yaml
version: '3.8'

services:
  prometheus:
    image: prom/prometheus:latest
    ports:
      - "9090:9090"
    volumes:
      - ./prometheus/prometheus.yml:/etc/prometheus/prometheus.yml
      - prometheus-data:/prometheus
    command:
      - '--config.file=/etc/prometheus/prometheus.yml'
      - '--storage.tsdb.path=/prometheus'

  grafana:
    image: grafana/grafana:latest
    ports:
      - "3001:3000"
    environment:
      - GF_SECURITY_ADMIN_PASSWORD=admin
    volumes:
      - grafana-data:/var/lib/grafana
      - ./grafana/dashboards:/etc/grafana/provisioning/dashboards
      - ./grafana/datasources:/etc/grafana/provisioning/datasources

  jaeger:
    image: jaegertracing/all-in-one:latest
    ports:
      - "5775:5775/udp"
      - "6831:6831/udp"
      - "6832:6832/udp"
      - "5778:5778"
      - "16686:16686"
      - "14268:14268"
      - "14250:14250"
      - "9411:9411"

  elasticsearch:
    image: docker.elastic.co/elasticsearch/elasticsearch:8.11.0
    environment:
      - discovery.type=single-node
      - "ES_JAVA_OPTS=-Xms512m -Xmx512m"
    ports:
      - "9200:9200"
    volumes:
      - elasticsearch-data:/usr/share/elasticsearch/data

  kibana:
    image: docker.elastic.co/kibana/kibana:8.11.0
    ports:
      - "5601:5601"
    environment:
      - ELASTICSEARCH_HOSTS=http://elasticsearch:9200
    depends_on:
      - elasticsearch

volumes:
  prometheus-data:
  grafana-data:
  elasticsearch-data:
```

