Building on the deployment infrastructure from Section 9, monitoring is essential for maintaining a production-ready REST API. Effective monitoring provides visibility into system health, performance, and user experience, enabling proactive issue detection and rapid incident response.

### 10.1 The Three Pillars of Observability

**Metrics, Logs, and Traces:**

```javascript
// config/observability.js
module.exports = {
  // Metrics: Quantitative measurements over time
  metrics: {
    enabled: true,
    interval: 15000, // 15 seconds
    retention: '30d'
  },

  // Logs: Discrete events with context
  logs: {
    level: process.env.LOG_LEVEL || 'info',
    format: 'json',
    destination: 'stdout'
  },

  // Traces: Request flow through distributed systems
  traces: {
    enabled: process.env.TRACING_ENABLED === 'true',
    sampleRate: 0.1 // 10% of requests
  }
};
```

### 10.2 Application Performance Monitoring (APM)

**New Relic Integration:**

```javascript
// server.js
// Must be first require
require('newrelic');

const express = require('express');
const app = express();

// Your application code...
```

**New Relic Configuration:**

```javascript
// newrelic.js
'use strict';

exports.config = {
  app_name: [process.env.NEW_RELIC_APP_NAME || 'My REST API'],
  license_key: process.env.NEW_RELIC_LICENSE_KEY,
  logging: {
    level: 'info'
  },

  // Custom attributes for all transactions
  attributes: {
    include: ['request.headers.x-request-id']
  },

  // Distributed tracing
  distributed_tracing: {
    enabled: true
  },

  // Transaction tracer
  transaction_tracer: {
    enabled: true,
    transaction_threshold: 'apdex_f',
    record_sql: 'obfuscated'
  },

  // Error collector
  error_collector: {
    enabled: true,
    ignore_status_codes: [404]
  }
};
```

**Datadog APM Alternative:**

```javascript
// tracer.js
const tracer = require('dd-trace').init({
  hostname: process.env.DD_AGENT_HOST,
  port: process.env.DD_TRACE_AGENT_PORT,
  service: 'rest-api',
  env: process.env.NODE_ENV,
  version: process.env.APP_VERSION,
  logInjection: true,
  analytics: true
});

module.exports = tracer;
```

### 10.3 Custom Metrics with Prometheus

**Prometheus Client Setup:**

```javascript
// middleware/metrics.js
const promClient = require('prom-client');

// Create a Registry
const register = new promClient.Registry();

// Add default metrics (CPU, memory, etc.)
promClient.collectDefaultMetrics({ register });

// Custom metrics
const httpRequestDuration = new promClient.Histogram({
  name: 'http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.1, 0.5, 1, 2, 5]
});

const httpRequestTotal = new promClient.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

const activeConnections = new promClient.Gauge({
  name: 'active_connections',
  help: 'Number of active connections'
});

const databaseQueryDuration = new promClient.Histogram({
  name: 'database_query_duration_seconds',
  help: 'Duration of database queries',
  labelNames: ['operation', 'table'],
  buckets: [0.01, 0.05, 0.1, 0.5, 1]
});

// Register metrics
register.registerMetric(httpRequestDuration);
register.registerMetric(httpRequestTotal);
register.registerMetric(activeConnections);
register.registerMetric(databaseQueryDuration);

// Metrics middleware
const metricsMiddleware = (req, res, next) => {
  const start = Date.now();

  activeConnections.inc();

  res.on('finish', () => {
    const duration = (Date.now() - start) / 1000;
    const route = req.route ? req.route.path : req.path;

    httpRequestDuration.observe(
      { method: req.method, route, status_code: res.statusCode },
      duration
    );

    httpRequestTotal.inc({
      method: req.method,
      route,
      status_code: res.statusCode
    });

    activeConnections.dec();
  });

  next();
};

// Metrics endpoint
const metricsEndpoint = async (req, res) => {
  res.set('Content-Type', register.contentType);
  res.end(await register.metrics());
};

module.exports = {
  metricsMiddleware,
  metricsEndpoint,
  metrics: {
    httpRequestDuration,
    httpRequestTotal,
    activeConnections,
    databaseQueryDuration
  }
};
```

**Database Query Monitoring:**

```javascript
// utils/database-monitor.js
const { metrics } = require('../middleware/metrics');

const monitorQuery = async (operation, table, queryFn) => {
  const start = Date.now();

  try {
    const result = await queryFn();
    const duration = (Date.now() - start) / 1000;

    metrics.databaseQueryDuration.observe(
      { operation, table },
      duration
    );

    return result;
  } catch (error) {
    const duration = (Date.now() - start) / 1000;
    metrics.databaseQueryDuration.observe(
      { operation, table },
      duration
    );
    throw error;
  }
};

module.exports = { monitorQuery };
```

### 10.4 Health Check Endpoints

**Comprehensive Health Checks:**

```javascript
// routes/health.js
const express = require('express');
const router = express.Router();
const { PrismaClient } = require('@prisma/client');
const redis = require('../config/redis');

const prisma = new PrismaClient();

// Liveness probe - is the app running?
router.get('/health/live', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Readiness probe - is the app ready to serve traffic?
router.get('/health/ready', async (req, res) => {
  const checks = {
    database: false,
    redis: false,
    memory: false
  };

  try {
    // Database check
    await prisma.$queryRaw`SELECT 1`;
    checks.database = true;
  } catch (error) {
    console.error('Database health check failed:', error);
  }

  try {
    // Redis check
    await redis.ping();
    checks.redis = true;
  } catch (error) {
    console.error('Redis health check failed:', error);
  }

  // Memory check
  const memUsage = process.memoryUsage();
  const memThreshold = 0.9; // 90% of heap
  checks.memory = memUsage.heapUsed / memUsage.heapTotal < memThreshold;

  const allHealthy = Object.values(checks).every(check => check === true);

  res.status(allHealthy ? 200 : 503).json({
    status: allHealthy ? 'ready' : 'not ready',
    checks,
    timestamp: new Date().toISOString()
  });
});

// Detailed health check
router.get('/health', async (req, res) => {
  const health = {
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    status: 'ok',
    version: process.env.APP_VERSION || '1.0.0',
    environment: process.env.NODE_ENV,
    checks: {}
  };

  // Database
  try {
    const start = Date.now();
    await prisma.$queryRaw`SELECT 1`;
    health.checks.database = {
      status: 'healthy',
      responseTime: Date.now() - start
    };
  } catch (error) {
    health.checks.database = {
      status: 'unhealthy',
      error: error.message
    };
    health.status = 'degraded';
  }

  // Redis
  try {
    const start = Date.now();
    await redis.ping();
    health.checks.redis = {
      status: 'healthy',
      responseTime: Date.now() - start
    };
  } catch (error) {
    health.checks.redis = {
      status: 'unhealthy',
      error: error.message
    };
    health.status = 'degraded';
  }

  // Memory
  const memUsage = process.memoryUsage();
  health.checks.memory = {
    status: 'healthy',
    heapUsed: `${Math.round(memUsage.heapUsed / 1024 / 1024)}MB`,
    heapTotal: `${Math.round(memUsage.heapTotal / 1024 / 1024)}MB`,
    external: `${Math.round(memUsage.external / 1024 / 1024)}MB`,
    rss: `${Math.round(memUsage.rss / 1024 / 1024)}MB`
  };

  const statusCode = health.status === 'ok' ? 200 : 503;
  res.status(statusCode).json(health);
});

module.exports = router;
```

### 10.5 Distributed Tracing with OpenTelemetry

**OpenTelemetry Setup:**

```javascript
// tracing.js
const { NodeTracerProvider } = require('@opentelemetry/sdk-trace-node');
const { registerInstrumentations } = require('@opentelemetry/instrumentation');
const { HttpInstrumentation } = require('@opentelemetry/instrumentation-http');
const { ExpressInstrumentation } = require('@opentelemetry/instrumentation-express');
const { PrismaInstrumentation } = require('@prisma/instrumentation');
const { JaegerExporter } = require('@opentelemetry/exporter-jaeger');
const { Resource } = require('@opentelemetry/resources');
const { SemanticResourceAttributes } = require('@opentelemetry/semantic-conventions');

const provider = new NodeTracerProvider({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'rest-api',
    [SemanticResourceAttributes.SERVICE_VERSION]: process.env.APP_VERSION,
    [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: process.env.NODE_ENV
  })
});

// Configure Jaeger exporter
const jaegerExporter = new JaegerExporter({
  endpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces'
});

provider.addSpanProcessor(
  new SimpleSpanProcessor(jaegerExporter)
);

provider.register();

// Register instrumentations
registerInstrumentations({
  instrumentations: [
    new HttpInstrumentation(),
    new ExpressInstrumentation(),
    new PrismaInstrumentation()
  ]
});

module.exports = provider;
```

**Custom Span Creation:**

```javascript
// services/user.service.js
const { trace } = require('@opentelemetry/api');

class UserService {
  async createUser(userData) {
    const tracer = trace.getTracer('user-service');

    return tracer.startActiveSpan('createUser', async (span) => {
      try {
        span.setAttribute('user.email', userData.email);
        span.setAttribute('user.role', userData.role);

        // Hash password
        const passwordSpan = tracer.startSpan('hashPassword');
        const hashedPassword = await bcrypt.hash(userData.password, 10);
        passwordSpan.end();

        // Create user in database
        const dbSpan = tracer.startSpan('database.createUser');
        const user = await prisma.user.create({
          data: { ...userData, password: hashedPassword }
        });
        dbSpan.end();

        span.setStatus({ code: SpanStatusCode.OK });
        return user;
      } catch (error) {
        span.recordException(error);
        span.setStatus({ code: SpanStatusCode.ERROR, message: error.message });
        throw error;
      } finally {
        span.end();
      }
    });
  }
}
```

### 10.6 Error Tracking with Sentry

**Sentry Integration:**

```javascript
// config/sentry.js
const Sentry = require('@sentry/node');
const Tracing = require('@sentry/tracing');

const initSentry = (app) => {
  Sentry.init({
    dsn: process.env.SENTRY_DSN,
    environment: process.env.NODE_ENV,
    release: process.env.APP_VERSION,

    // Performance monitoring
    tracesSampleRate: 0.1,

    integrations: [
      new Sentry.Integrations.Http({ tracing: true }),
      new Tracing.Integrations.Express({ app }),
      new Tracing.Integrations.Postgres(),
      new Tracing.Integrations.Prisma({ client: prisma })
    ],

    // Filter sensitive data
    beforeSend(event, hint) {
      // Remove sensitive headers
      if (event.request?.headers) {
        delete event.request.headers.authorization;
        delete event.request.headers.cookie;
      }

      // Remove password fields
      if (event.request?.data) {
        const data = JSON.parse(JSON.stringify(event.request.data));
        if (data.password) data.password = '[Filtered]';
        event.request.data = data;
      }

      return event;
    }
  });

  // Request handler must be first middleware
  app.use(Sentry.Handlers.requestHandler());
  app.use(Sentry.Handlers.tracingHandler());
};

// Error handler must be before other error middleware
const sentryErrorHandler = Sentry.Handlers.errorHandler({
  shouldHandleError(error) {
    // Capture 5xx errors
    return error.status >= 500;
  }
});

module.exports = { initSentry, sentryErrorHandler };
```

**Custom Error Context:**

```javascript
// middleware/error-handler.js
const Sentry = require('@sentry/node');

const errorHandler = (err, req, res, next) => {
  // Add custom context to Sentry
  Sentry.withScope((scope) => {
    scope.setUser({
      id: req.user?.id,
      email: req.user?.email
    });

    scope.setContext('request', {
      method: req.method,
      url: req.url,
      query: req.query,
      params: req.params
    });

    scope.setTag('error.type', err.name);
    scope.setLevel(err.status >= 500 ? 'error' : 'warning');

    Sentry.captureException(err);
  });

  // Send response
  res.status(err.status || 500).json({
    error: {
      message: err.message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  });
};
```

