{"runType":"STIGMERGY","runId":"5ed581a5-9d1b-4e18-83df-b82b50551a5c-STIGMERGY-1","contentTransferTokens":2570,"mechanismOverheadTokens":13924,"coordinationInstructionsTokens":4097,"taskReasoningTokens":14482,"systemIdentityTokens":0,"interAgentTokens":20591,"agentAutonomousTokens":14482,"totalTokens":35073,"cachedTokens":0,"effectiveTokens":35073,"cacheHitRate":0,"wallClockMs":163451,"agentCount":5,"apiCallCount":15,"success":true,"output":"## Section 5: Authentication

Building on the database integration from Section 4, implementing robust authentication is critical for securing your production REST API. This section covers modern authentication strategies and best practices.

### 5.1 Authentication Strategies

**JWT (JSON Web Tokens)**
- Stateless authentication ideal for distributed systems
- Tokens contain encoded user claims and are cryptographically signed
- No server-side session storage required

**Session-Based Authentication**
- Traditional approach using server-side sessions
- Requires session store (Redis, database)
- Better for applications requiring immediate token revocation

**OAuth 2.0 / OpenID Connect**
- Industry standard for third-party authentication
- Delegate authentication to providers (Google, GitHub, Auth0)
- Ideal for social login and enterprise SSO

### 5.2 Implementing JWT Authentication

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

// User registration
app.post('/api/auth/register', async (req, res) => {
  try {
    const { email, password, name } = req.body;

    // Hash password
    const saltRounds = 12;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    // Create user (using database from Section 4)
    const user = await db.query(
      'INSERT INTO users (email, password, name) VALUES ($1, $2, $3) RETURNING id, email, name',
      [email, hashedPassword, name]
    );

    res.status(201).json({ user: user.rows[0] });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// User login
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Find user
    const result = await db.query(
      'SELECT * FROM users WHERE email = $1',
      [email]
    );

    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];

    // Verify password
    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT
    const token = jwt.sign(
      { userId: user.id, email: user.email },
      process.env.JWT_SECRET,
      { expiresIn: '24h' }
    );

    res.json({ 
      token,
      user: { id: user.id, email: user.email, name: user.name }
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});
```

### 5.3 Authentication Middleware

Create middleware to protect routes (building on Section 3's middleware concepts):

```javascript
// middleware/auth.js
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// Role-based authorization
const authorize = (...roles) => {
  return async (req, res, next) => {
    const user = await db.query(
      'SELECT role FROM users WHERE id = $1',
      [req.user.userId]
    );

    if (!roles.includes(user.rows[0].role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

module.exports = { authenticateToken, authorize };
```

### 5.4 Protecting Routes

Apply authentication to your routes (from Section 2):

```javascript
const { authenticateToken, authorize } = require('./middleware/auth');

// Public route
app.get('/api/products', async (req, res) => {
  // Anyone can view products
});

// Protected route - requires authentication
app.get('/api/profile', authenticateToken, async (req, res) => {
  const user = await db.query(
    'SELECT id, email, name FROM users WHERE id = $1',
    [req.user.userId]
  );
  res.json(user.rows[0]);
});

// Admin-only route
app.delete('/api/users/:id', 
  authenticateToken, 
  authorize('admin'), 
  async (req, res) => {
    await db.query('DELETE FROM users WHERE id = $1', [req.params.id]);
    res.status(204).send();
  }
);
```

### 5.5 Security Best Practices

**Password Security**
- Use bcrypt with salt rounds ≥ 12
- Enforce strong password policies
- Implement rate limiting on login attempts
- Never log or expose passwords

**Token Management**
- Store JWT_SECRET in environment variables
- Use short expiration times (15min-24h)
- Implement refresh tokens for long-lived sessions
- Blacklist tokens on logout (if needed)

**Additional Security Measures**
```javascript
// Refresh token implementation
app.post('/api/auth/refresh', async (req, res) => {
  const { refreshToken } = req.body;

  if (!refreshToken) {
    return res.status(401).json({ error: 'Refresh token required' });
  }

  try {
    const payload = jwt.verify(refreshToken, process.env.REFRESH_TOKEN_SECRET);

    // Generate new access token
    const accessToken = jwt.sign(
      { userId: payload.userId, email: payload.email },
      process.env.JWT_SECRET,
      { expiresIn: '15m' }
    );

    res.json({ accessToken });
  } catch (error) {
    res.status(403).json({ error: 'Invalid refresh token' });
  }
});

// Logout with token blacklist
const tokenBlacklist = new Set(); // Use Redis in production

app.post('/api/auth/logout', authenticateToken, (req, res) => {
  const token = req.headers['authorization'].split(' ')[1];
  tokenBlacklist.add(token);
  res.json({ message: 'Logged out successfully' });
});
```

### 5.6 Production Considerations

**Environment Configuration**
```bash
# .env
JWT_SECRET=your-super-secret-key-min-256-bits
REFRESH_TOKEN_SECRET=different-secret-for-refresh
TOKEN_EXPIRY=15m
REFRESH_TOKEN_EXPIRY=7d
BCRYPT_ROUNDS=12
```

**Rate Limiting**
```javascript
const rateLimit = require('express-rate-limit');

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per window
  message: 'Too many login attempts, please try again later'
});

app.post('/api/auth/login', authLimiter, async (req, res) => {
  // Login logic
});
```

**HTTPS Only**
- Always use HTTPS in production
- Set secure cookie flags
- Enable HSTS headers

**Monitoring & Logging**
- Log authentication failures
- Monitor for brute force attacks
- Track token usage patterns
- Alert on suspicious activity

### 5.7 Testing Authentication

```javascript
// tests/auth.test.js
const request = require('supertest');
const app = require('../app');

describe('Authentication', () => {
  test('should register new user', async () => {
    const res = await request(app)
      .post('/api/auth/register')
      .send({
        email: 'test@example.com',
        password: 'SecurePass123!',
        name: 'Test User'
      });

    expect(res.status).toBe(201);
    expect(res.body.user).toHaveProperty('email', 'test@example.com');
  });

  test('should login and return token', async () => {
    const res = await request(app)
      .post('/api/auth/login')
      .send({
        email: 'test@example.com',
        password: 'SecurePass123!'
      });

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('token');
  });

  test('should access protected route with valid token', async () => {
    const loginRes = await request(app)
      .post('/api/auth/login')
      .send({ email: 'test@example.com', password: 'SecurePass123!' });

    const res = await request(app)
      .get('/api/profile')
      .set('Authorization', `Bearer ${loginRes.body.token}`);

    expect(res.status).toBe(200);
  });
});
```

