### Authentication Controller

**`src/controllers/auth.controller.js`:**
```javascript
const AuthService = require('../services/auth.service');
const { asyncHandler } = require('../middleware/errorHandler');

class AuthController {
  // Register
  static register = asyncHandler(async (req, res) => {
    const { email, password, firstName, lastName } = req.body;

    const result = await AuthService.register({
      email,
      password,
      firstName,
      lastName,
    });

    res.status(201).json({
      status: 'success',
      message: 'Registration successful',
      data: result,
    });
  });

  // Login
  static login = asyncHandler(async (req, res) => {
    const { email, password } = req.body;

    const result = await AuthService.login(email, password);

    // Set refresh token in HTTP-only cookie
    res.cookie('refreshToken', result.tokens.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    });

    res.json({
      status: 'success',
      message: 'Login successful',
      data: {
        user: result.user,
        accessToken: result.tokens.accessToken,
      },
    });
  });

  // Refresh token
  static refreshToken = asyncHandler(async (req, res) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

    if (!refreshToken) {
      return res.status(401).json({
        status: 'error',
        message: 'Refresh token required',
      });
    }

    const result = await AuthService.refreshToken(refreshToken);

    res.json({
      status: 'success',
      data: result,
    });
  });

  // Logout
  static logout = asyncHandler(async (req, res) => {
    await AuthService.logout(req.user.id);

    // Clear refresh token cookie
    res.clearCookie('refreshToken');

    res.json({
      status: 'success',
      message: 'Logged out successfully',
    });
  });

  // Forgot password
  static forgotPassword = asyncHandler(async (req, res) => {
    const { email } = req.body;

    const result = await AuthService.forgotPassword(email);

    res.json({
      status: 'success',
      message: result.message,
    });
  });

  // Reset password
  static resetPassword = asyncHandler(async (req, res) => {
    const { token, password } = req.body;

    const result = await AuthService.resetPassword(token, password);

    res.json({
      status: 'success',
      message: result.message,
    });
  });

  // Verify email
  static verifyEmail = asyncHandler(async (req, res) => {
    const { token } = req.params;

    const result = await AuthService.verifyEmail(token);

    res.json({
      status: 'success',
      message: result.message,
    });
  });

  // Change password
  static changePassword = asyncHandler(async (req, res) => {
    const { currentPassword, newPassword } = req.body;

    const result = await AuthService.changePassword(
      req.user.id,
      currentPassword,
      newPassword
    );

    res.json({
      status: 'success',
      message: result.message,
    });
  });

  // Get current user
  static getCurrentUser = asyncHandler(async (req, res) => {
    res.json({
      status: 'success',
      data: {
        user: AuthService.sanitizeUser(req.user),
      },
    });
  });
}

module.exports = AuthController;
```

### OAuth 2.0 Integration (Google Example)

**`src/services/oauth.service.js`:**
```javascript
const { OAuth2Client } = require('google-auth-library');
const User = require('../models/user.model');
const TokenService = require('./token.service');
const { UnauthorizedError } = require('../utils/errors');

const client = new OAuth2Client(process.env.GOOGLE_CLIENT_ID);

class OAuthService {
  // Verify Google token
  static async verifyGoogleToken(token) {
    try {
      const ticket = await client.verifyIdToken({
        idToken: token,
        audience: process.env.GOOGLE_CLIENT_ID,
      });

      return ticket.getPayload();
    } catch (error) {
      throw new UnauthorizedError('Invalid Google token');
    }
  }

  // Google login/register
  static async googleAuth(googleToken) {
    const payload = await this.verifyGoogleToken(googleToken);

    const { email, given_name, family_name, sub: googleId } = payload;

    // Check if user exists
    let user = await User.findByEmail(email);

    if (!user) {
      // Create new user
      user = await User.create({
        email,
        firstName: given_name,
        lastName: family_name,
        password: crypto.randomBytes(32).toString('hex'), // Random password
        isEmailVerified: true, // Google emails are verified
        oauthProvider: 'google',
        oauthId: googleId,
      });
    }

    // Generate tokens
    const tokens = TokenService.generateTokenPair(user.id, user.role);

    return {
      user: AuthService.sanitizeUser(user),
      tokens,
    };
  }
}

module.exports = OAuthService;
```

### Two-Factor Authentication (2FA)

**`src/services/twoFactor.service.js`:**
```javascript
const speakeasy = require('speakeasy');
const QRCode = require('qrcode');
const User = require('../models/user.model');
const { UnauthorizedError } = require('../utils/errors');

class TwoFactorService {
  // Generate 2FA secret
  static async generateSecret(userId) {
    const user = await User.findById(userId);

    const secret = speakeasy.generateSecret({
      name: `YourApp (${user.email})`,
      length: 32,
    });

    // Save secret to user (encrypted in production)
    await User.update(userId, {
      twoFactorSecret: secret.base32,
      twoFactorEnabled: false, // Not enabled until verified
    });

    // Generate QR code
    const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url);

    return {
      secret: secret.base32,
      qrCode: qrCodeUrl,
    };
  }

  // Verify and enable 2FA
  static async enableTwoFactor(userId, token) {
    const user = await User.findById(userId);

    if (!user.twoFactorSecret) {
      throw new Error('2FA secret not generated');
    }

    const verified = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2,
    });

    if (!verified) {
      throw new UnauthorizedError('Invalid 2FA token');
    }

    // Enable 2FA
    await User.update(userId, { twoFactorEnabled: true });

    // Generate backup codes
    const backupCodes = this.generateBackupCodes();
    await User.saveBackupCodes(userId, backupCodes);

    return {
      message: '2FA enabled successfully',
      backupCodes,
    };
  }

  // Verify 2FA token
  static async verifyToken(userId, token) {
    const user = await User.findById(userId);

    if (!user.twoFactorEnabled) {
      return true; // 2FA not enabled
    }

    // Check if it's a backup code
    const isBackupCode = await User.verifyBackupCode(userId, token);
    if (isBackupCode) {
      return true;
    }

    // Verify TOTP token
    const verified = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2,
    });

    if (!verified) {
      throw new UnauthorizedError('Invalid 2FA token');
    }

    return true;
  }

  // Disable 2FA
  static async disableTwoFactor(userId, password) {
    const user = await User.findById(userId);

    // Verify password
    const isPasswordValid = await User.verifyPassword(password, user.password_hash);
    if (!isPasswordValid) {
      throw new UnauthorizedError('Invalid password');
    }

    await User.update(userId, {
      twoFactorEnabled: false,
      twoFactorSecret: null,
    });

    await User.clearBackupCodes(userId);

    return { message: '2FA disabled successfully' };
  }

  // Generate backup codes
  static generateBackupCodes(count = 10) {
    const codes = [];
    for (let i = 0; i < count; i++) {
      codes.push(crypto.randomBytes(4).toString('hex'));
    }
    return codes;
  }
}

module.exports = TwoFactorService;
```

### Session Management (Redis)

**`src/services/session.service.js`:**
```javascript
const Redis = require('ioredis');
const config = require('../config/env');

const redis = new Redis({
  host: config.redis.host,
  port: config.redis.port,
  password: config.redis.password,
  db: 0,
});

class SessionService {
  // Store session
  static async createSession(userId, sessionData, expiresIn = 86400) {
    const sessionId = crypto.randomBytes(32).toString('hex');
    const key = `session:${sessionId}`;

    await redis.setex(
      key,
      expiresIn,
      JSON.stringify({
        userId,
        ...sessionData,
        createdAt: new Date().toISOString(),
      })
    );

    return sessionId;
  }

  // Get session
  static async getSession(sessionId) {
    const key = `session:${sessionId}`;
    const data = await redis.get(key);

    return data ? JSON.parse(data) : null;
  }

  // Update session
  static async updateSession(sessionId, updates) {
    const session = await this.getSession(sessionId);
    if (!session) {
      return null;
    }

    const key = `session:${sessionId}`;
    const ttl = await redis.ttl(key);

    await redis.setex(
      key,
      ttl,
      JSON.stringify({
        ...session,
        ...updates,
        updatedAt: new Date().toISOString(),
      })
    );

    return true;
  }

  // Delete session
  static async deleteSession(sessionId) {
    const key = `session:${sessionId}`;
    await redis.del(key);
  }

  // Delete all user sessions
  static async deleteUserSessions(userId) {
    const pattern = `session:*`;
    const keys = await redis.keys(pattern);

    for (const key of keys) {
      const data = await redis.get(key);
      const session = JSON.parse(data);

      if (session.userId === userId) {
        await redis.del(key);
      }
    }
  }

  // Token blacklist (for logout)
  static async blacklistToken(token, expiresIn) {
    const key = `blacklist:${token}`;
    await redis.setex(key, expiresIn, '1');
  }

  // Check if token is blacklisted
  static async isTokenBlacklisted(token) {
    const key = `blacklist:${token}`;
    const result = await redis.get(key);
    return result !== null;
  }
}

module.exports = SessionService;
```

