{"runType":"STIGMERGY","runId":"5ed581a5-9d1b-4e18-83df-b82b50551a5c-STIGMERGY-2","contentTransferTokens":2586,"mechanismOverheadTokens":13909,"coordinationInstructionsTokens":4087,"taskReasoningTokens":14993,"systemIdentityTokens":0,"interAgentTokens":20582,"agentAutonomousTokens":14993,"totalTokens":35575,"cachedTokens":0,"effectiveTokens":35575,"cacheHitRate":0,"wallClockMs":162590,"agentCount":5,"apiCallCount":15,"success":true,"output":"## Section 5: Authentication

Authentication is critical for securing your production REST API. This section covers implementing robust authentication mechanisms to protect your endpoints and manage user access.

### 5.1 Authentication Strategies

**JWT (JSON Web Tokens)**
The most popular stateless authentication method for REST APIs:

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

// Generate JWT token
function generateToken(user) {
  return jwt.sign(
    { 
      id: user.id, 
      email: user.email,
      role: user.role 
    },
    process.env.JWT_SECRET,
    { 
      expiresIn: '24h',
      issuer: 'your-api-name'
    }
  );
}

// Verify JWT token
function verifyToken(token) {
  try {
    return jwt.verify(token, process.env.JWT_SECRET);
  } catch (error) {
    throw new Error('Invalid or expired token');
  }
}
```

**Session-Based Authentication**
For applications requiring server-side session management:

```javascript
const session = require('express-session');
const RedisStore = require('connect-redis')(session);

app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true, // HTTPS only
    httpOnly: true,
    maxAge: 24 * 60 * 60 * 1000 // 24 hours
  }
}));
```

### 5.2 User Registration and Login

**Registration Endpoint**

```javascript
app.post('/api/auth/register', async (req, res) => {
  try {
    const { email, password, name } = req.body;

    // Validate input
    if (!email || !password || password.length < 8) {
      return res.status(400).json({ 
        error: 'Invalid input. Password must be at least 8 characters.' 
      });
    }

    // Check if user exists
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(409).json({ error: 'User already exists' });
    }

    // Hash password
    const saltRounds = 12;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    // Create user
    const user = await User.create({
      email,
      password: hashedPassword,
      name
    });

    // Generate token
    const token = generateToken(user);

    res.status(201).json({
      message: 'User registered successfully',
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name
      }
    });
  } catch (error) {
    res.status(500).json({ error: 'Registration failed' });
  }
});
```

**Login Endpoint**

```javascript
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Find user
    const user = await User.findOne({ email });
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Verify password
    const isValidPassword = await bcrypt.compare(password, user.password);
    if (!isValidPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate token
    const token = generateToken(user);

    res.json({
      message: 'Login successful',
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role
      }
    });
  } catch (error) {
    res.status(500).json({ error: 'Login failed' });
  }
});
```

### 5.3 Authentication Middleware

**JWT Authentication Middleware**

```javascript
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = verifyToken(token);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Usage
app.get('/api/protected', authenticateToken, (req, res) => {
  res.json({ 
    message: 'Access granted',
    user: req.user 
  });
});
```

**Role-Based Access Control (RBAC)**

```javascript
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Insufficient permissions' 
      });
    }

    next();
  };
}

// Usage
app.delete('/api/users/:id', 
  authenticateToken, 
  authorize('admin', 'moderator'),
  async (req, res) => {
    // Only admins and moderators can delete users
    await User.findByIdAndDelete(req.params.id);
    res.json({ message: 'User deleted' });
  }
);
```

### 5.4 Token Refresh Strategy

Implement refresh tokens for enhanced security:

```javascript
function generateRefreshToken(user) {
  return jwt.sign(
    { id: user.id },
    process.env.REFRESH_TOKEN_SECRET,
    { expiresIn: '7d' }
  );
}

app.post('/api/auth/refresh', async (req, res) => {
  const { refreshToken } = req.body;

  if (!refreshToken) {
    return res.status(401).json({ error: 'Refresh token required' });
  }

  try {
    const decoded = jwt.verify(refreshToken, process.env.REFRESH_TOKEN_SECRET);
    const user = await User.findById(decoded.id);

    if (!user) {
      return res.status(403).json({ error: 'Invalid refresh token' });
    }

    const newAccessToken = generateToken(user);

    res.json({ accessToken: newAccessToken });
  } catch (error) {
    res.status(403).json({ error: 'Invalid or expired refresh token' });
  }
});
```

### 5.5 Security Best Practices

**Password Security**
```javascript
// Password strength validation
function validatePassword(password) {
  const minLength = 8;
  const hasUpperCase = /[A-Z]/.test(password);
  const hasLowerCase = /[a-z]/.test(password);
  const hasNumbers = /\d/.test(password);
  const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);

  return password.length >= minLength && 
         hasUpperCase && 
         hasLowerCase && 
         hasNumbers && 
         hasSpecialChar;
}
```

**Rate Limiting for Auth Endpoints**
```javascript
const rateLimit = require('express-rate-limit');

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per window
  message: 'Too many login attempts, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.post('/api/auth/login', authLimiter, loginHandler);
```

**Token Blacklisting (for logout)**
```javascript
const blacklistedTokens = new Set(); // Use Redis in production

app.post('/api/auth/logout', authenticateToken, (req, res) => {
  const token = req.headers['authorization'].split(' ')[1];
  blacklistedTokens.add(token);

  res.json({ message: 'Logged out successfully' });
});

// Update authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  if (blacklistedTokens.has(token)) {
    return res.status(403).json({ error: 'Token has been revoked' });
  }

  // ... rest of verification
}
```

### 5.6 OAuth 2.0 Integration

For third-party authentication (Google, GitHub, etc.):

```javascript
const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;

passport.use(new GoogleStrategy({
    clientID: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    callbackURL: '/api/auth/google/callback'
  },
  async (accessToken, refreshToken, profile, done) => {
    try {
      let user = await User.findOne({ googleId: profile.id });

      if (!user) {
        user = await User.create({
          googleId: profile.id,
          email: profile.emails[0].value,
          name: profile.displayName
        });
      }

      return done(null, user);
    } catch (error) {
      return done(error, null);
    }
  }
));

app.get('/api/auth/google',
  passport.authenticate('google', { scope: ['profile', 'email'] })
);

app.get('/api/auth/google/callback',
  passport.authenticate('google', { session: false }),
  (req, res) => {
    const token = generateToken(req.user);
    res.redirect(`${process.env.CLIENT_URL}?token=${token}`);
  }
);
```

### 5.7 Production Checklist

- ✅ Use HTTPS in production (enforce with middleware)
- ✅ Store secrets in environment variables, never in code
- ✅ Implement rate limiting on authentication endpoints
- ✅ Use strong password hashing (bcrypt with 12+ rounds)
- ✅ Set appropriate token expiration times
- ✅ Implement refresh token rotation
- ✅ Add CORS configuration for allowed origins
- ✅ Log authentication attempts for security monitoring
- ✅ Implement account lockout after failed attempts
- ✅ Use secure, httpOnly cookies for tokens when possible
- ✅ Validate and sanitize all user inputs
- ✅ Implement multi-factor authentication (MFA) for sensitive operations

**Environment Variables Example**
```bash
JWT_SECRET=your-super-secret-jwt-key-min-32-chars
REFRESH_TOKEN_SECRET=your-refresh-token-secret-key
SESSION_SECRET=your-session-secret-key
TOKEN_EXPIRY=24h
REFRESH_TOKEN_EXPIRY=7d
BCRYPT_ROUNDS=12
```

