**src/config/passport.ts:**
```typescript
import passport from 'passport';
import { Strategy as GoogleStrategy } from 'passport-google-oauth20';
import { env } from './environment';
import { prisma } from './database';
import bcrypt from 'bcryptjs';

passport.use(
  new GoogleStrategy(
    {
      clientID: env.GOOGLE_CLIENT_ID,
      clientSecret: env.GOOGLE_CLIENT_SECRET,
      callbackURL: `${env.API_URL}/api/${env.API_VERSION}/auth/google/callback`,
    },
    async (accessToken, refreshToken, profile, done) => {
      try {
        // Check if user exists
        let user = await prisma.user.findUnique({
          where: { email: profile.emails![0].value },
        });

        if (!user) {
          // Create new user
          const randomPassword = await bcrypt.hash(
            crypto.randomBytes(32).toString('hex'),
            12
          );

          user = await prisma.user.create({
            data: {
              email: profile.emails![0].value,
              password: randomPassword,
              firstName: profile.name!.givenName,
              lastName: profile.name!.familyName,
              emailVerified: true,
            },
          });
        }

        return done(null, user);
      } catch (error) {
        return done(error as Error);
      }
    }
  )
);

export default passport;
```

### Two-Factor Authentication (2FA)

```bash
npm install speakeasy qrcode
npm install -D @types/speakeasy @types/qrcode
```

**src/services/twoFactor.service.ts:**
```typescript
import speakeasy from 'speakeasy';
import QRCode from 'qrcode';
import { prisma } from '../config/database';
import { ApiError } from '../utils/ApiError';

export const generateTwoFactorSecret = async (userId: string) => {
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });

  if (!user) {
    throw new ApiError(404, 'User not found');
  }

  const secret = speakeasy.generateSecret({
    name: `MyApp (${user.email})`,
    length: 32,
  });

  // Generate QR code
  const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url!);

  // Store secret (encrypted in production)
  await prisma.user.update({
    where: { id: userId },
    data: {
      twoFactorSecret: secret.base32,
      twoFactorEnabled: false, // Enable after verification
    },
  });

  return {
    secret: secret.base32,
    qrCode: qrCodeUrl,
  };
};

export const verifyTwoFactorToken = async (
  userId: string,
  token: string
): Promise<boolean> => {
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });

  if (!user || !user.twoFactorSecret) {
    throw new ApiError(400, 'Two-factor authentication not set up');
  }

  const verified = speakeasy.totp.verify({
    secret: user.twoFactorSecret,
    encoding: 'base32',
    token,
    window: 2, // Allow 2 time steps before/after
  });

  return verified;
};

export const enableTwoFactor = async (userId: string, token: string) => {
  const verified = await verifyTwoFactorToken(userId, token);

  if (!verified) {
    throw new ApiError(400, 'Invalid verification code');
  }

  await prisma.user.update({
    where: { id: userId },
    data: { twoFactorEnabled: true },
  });
};

export const disableTwoFactor = async (userId: string, token: string) => {
  const verified = await verifyTwoFactorToken(userId, token);

  if (!verified) {
    throw new ApiError(400, 'Invalid verification code');
  }

  await prisma.user.update({
    where: { id: userId },
    data: {
      twoFactorEnabled: false,
      twoFactorSecret: null,
    },
  });
};
```

### Server Entry Point

**src/server.ts:**
```typescript
import app from './app';
import { env } from './config/environment';
import { logger } from './config/logger';
import { prisma } from './config/database';

const PORT = env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${env.NODE_ENV} mode`);
});

// Graceful shutdown
const gracefulShutdown = async (signal: string) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);

  server.close(async () => {
    logger.info('HTTP server closed');

    try {
      await prisma.$disconnect();
      logger.info('Database connection closed');
      process.exit(0);
    } catch (error) {
      logger.error('Error during shutdown:', error);
      process.exit(1);
    }
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    logger.error('Forced shutdown after timeout');
    process.exit(1);
  }, 30000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

export default server;
```

