    } catch (error) {
      if (error instanceof ApiError) throw error;
      logger.error('Password reset error', { error: error.message });
      throw new ApiError(500, 'Password reset failed');
    }
  }

  /**
   * Verify email
   */
  async verifyEmail(token) {
    try {
      const user = await tokenService.verifyEmailToken(token);

      if (user.isEmailVerified) {
        throw new ApiError(400, 'Email already verified');
      }

      user.isEmailVerified = true;
      await user.save();

      // Blacklist the verification token
      await tokenService.blacklistToken(token);

      logger.info('Email verified', { userId: user.id });

      return user;
    } catch (error) {
      if (error instanceof ApiError) throw error;
      logger.error('Email verification error', { error: error.message });
      throw new ApiError(500, 'Email verification failed');
    }
  }

  /**
   * Resend verification email
   */
  async resendVerificationEmail(userId) {
    try {
      const user = await userService.getUserById(userId);

      if (user.isEmailVerified) {
        throw new ApiError(400, 'Email already verified');
      }

      const verifyToken = await tokenService.generateVerifyEmailToken(user.id);
      await emailService.sendVerificationEmail(user, verifyToken);

      logger.info('Verification email resent', { userId: user.id });
    } catch (error) {
      if (error instanceof ApiError) throw error;
      logger.error('Resend verification error', { error: error.message });
      throw new ApiError(500, 'Failed to resend verification email');
    }
  }

  /**
   * Change password
   */
  async changePassword(userId, oldPassword, newPassword) {
    try {
      const user = await userService.getUserById(userId);

      const isPasswordValid = await user.comparePassword(oldPassword);
      if (!isPasswordValid) {
        throw new ApiError(401, 'Incorrect current password');
      }

      user.password = newPassword;
      await user.save();

      // Revoke all existing tokens
      await tokenService.revokeUserTokens(user.id);

      // Send confirmation email
      await emailService.sendPasswordChangedEmail(user);

      logger.info('Password changed', { userId: user.id });
    } catch (error) {
      if (error instanceof ApiError) throw error;
      logger.error('Change password error', { error: error.message });
      throw new ApiError(500, 'Password change failed');
    }
  }
}

module.exports = new AuthService();
```

### Authentication Controller

Create `src/controllers/auth.controller.js`:

```javascript
const authService = require('../services/auth.service');
const catchAsync = require('../utils/catchAsync');

const register = catchAsync(async (req, res) => {
  const { user, tokens } = await authService.register(req.body);

  res.status(201).json({
    success: true,
    message: 'Registration successful. Please verify your email.',
    data: {
      user: user.toJSON(),
      tokens,
    },
  });
});

const login = catchAsync(async (req, res) => {
  const { email, password } = req.body;
  const { user, tokens } = await authService.login(email, password);

  res.json({
    success: true,
    message: 'Login successful',
    data: {
      user: user.toJSON(),
      tokens,
    },
  });
});

const logout = catchAsync(async (req, res) => {
  await authService.logout(req.body.refreshToken);

  res.json({
    success: true,
    message: 'Logout successful',
  });
});

const refreshTokens = catchAsync(async (req, res) => {
  const tokens = await authService.refreshTokens(req.body.refreshToken);

  res.json({
    success: true,
    message: 'Tokens refreshed',
    data: { tokens },
  });
});

const forgotPassword = catchAsync(async (req, res) => {
  await authService.forgotPassword(req.body.email);

  res.json({
    success: true,
    message: 'If the email exists, a password reset link has been sent',
  });
});

const resetPassword = catchAsync(async (req, res) => {
  await authService.resetPassword(req.body.token, req.body.password);

  res.json({
    success: true,
    message: 'Password reset successful',
  });
});

const verifyEmail = catchAsync(async (req, res) => {
  await authService.verifyEmail(req.query.token);

  res.json({
    success: true,
    message: 'Email verified successfully',
  });
});

const resendVerificationEmail = catchAsync(async (req, res) => {
  await authService.resendVerificationEmail(req.user.id);

  res.json({
    success: true,
    message: 'Verification email sent',
  });
});

const changePassword = catchAsync(async (req, res) => {
  await authService.changePassword(
    req.user.id,
    req.body.oldPassword,
    req.body.newPassword
  );

  res.json({
    success: true,
    message: 'Password changed successfully',
  });
});

const getProfile = catchAsync(async (req, res) => {
  res.json({
    success: true,
    data: { user: req.user.toJSON() },
  });
});

module.exports = {
  register,
  login,
  logout,
  refreshTokens,
  forgotPassword,
  resetPassword,
  verifyEmail,
  resendVerificationEmail,
  changePassword,
  getProfile,
};
```

### Authentication Routes

Create `src/routes/v1/auth.routes.js`:

```javascript
const express = require('express');
const authController = require('../../controllers/auth.controller');
const { authenticate } = require('../../middleware/auth');
const { validateBody } = require('../../middleware/validate');
const { authLimiter } = require('../../middleware/rateLimiter');
const { authSchemas } = require('../../validations/auth.validation');

const router = express.Router();

// Public routes
router.post(
  '/register',
  authLimiter,
  validateBody(authSchemas.register),
  authController.register
);

router.post(
  '/login',
  authLimiter,
  validateBody(authSchemas.login),
  authController.login
);

router.post(
  '/logout',
  validateBody(authSchemas.logout),
  authController.logout
);

router.post(
  '/refresh-tokens',
  validateBody(authSchemas.refreshTokens),
  authController.refreshTokens
);

router.post(
  '/forgot-password',
  authLimiter,
  validateBody(authSchemas.forgotPassword),
  authController.forgotPassword
);

router.post(
  '/reset-password',
  authLimiter,
  validateBody(authSchemas.resetPassword),
  authController.resetPassword
);

router.get(
  '/verify-email',
  authController.verifyEmail
);

// Protected routes
router.post(
  '/resend-verification',
  authenticate,
  authController.resendVerificationEmail
);

router.post(
  '/change-password',
  authenticate,
  validateBody(authSchemas.changePassword),
  authController.changePassword
);

router.get(
  '/profile',
  authenticate,
  authController.getProfile
);

module.exports = router;
```

### Auth Validation Schemas

Create `src/validations/auth.validation.js`:

```javascript
const Joi = require('joi');

const authSchemas = {
  register: Joi.object({
    email: Joi.string().email().required(),
    password: Joi.string().min(8).required(),
    firstName: Joi.string().required(),
    lastName: Joi.string().required(),
  }),

  login: Joi.object({
    email: Joi.string().email().required(),
    password: Joi.string().required(),
  }),

  logout: Joi.object({
    refreshToken: Joi.string().required(),
  }),

  refreshTokens: Joi.object({
    refreshToken: Joi.string().required(),
  }),

  forgotPassword: Joi.object({
    email: Joi.string().email().required(),
  }),

  resetPassword: Joi.object({
    token: Joi.string().required(),
    password: Joi.string().min(8).required(),
  }),

  changePassword: Joi.object({
    oldPassword: Joi.string().required(),
    newPassword: Joi.string().min(8).required(),
  }),
};

module.exports = { authSchemas };
```

