### Testing Authentication

Create `tests/integration/auth.test.js`:

```javascript
const request = require('supertest');
const app = require('../../src/app');
const User = require('../../src/models/user.model');
const Token = require('../../src/models/token.model');

describe('Authentication', () => {
  const userData = {
    email: 'test@example.com',
    password: 'password123',
    firstName: 'John',
    lastName: 'Doe',
  };

  beforeEach(async () => {
    await User.deleteMany({});
    await Token.deleteMany({});
  });

  describe('POST /api/v1/auth/register', () => {
    it('should register a new user', async () => {
      const res = await request(app)
        .post('/api/v1/auth/register')
        .send(userData)
        .expect(201);

      expect(res.body.success).toBe(true);
      expect(res.body.data.user.email).toBe(userData.email);
      expect(res.body.data.tokens).toBeDefined();
      expect(res.body.data.tokens.access).toBeDefined();
      expect(res.body.data.tokens.refresh).toBeDefined();
    });

    it('should not register duplicate email', async () => {
      await request(app).post('/api/v1/auth/register').send(userData);

      const res = await request(app)
        .post('/api/v1/auth/register')
        .send(userData)
        .expect(400);

      expect(res.body.success).toBe(false);
    });
  });

  describe('POST /api/v1/auth/login', () => {
    beforeEach(async () => {
      await request(app).post('/api/v1/auth/register').send(userData);
    });

    it('should login with valid credentials', async () => {
      const res = await request(app)
        .post('/api/v1/auth/login')
        .send({ email: userData.email, password: userData.password })
        .expect(200);

      expect(res.body.success).toBe(true);
      expect(res.body.data.tokens).toBeDefined();
    });

    it('should reject invalid credentials', async () => {
      const res = await request(app)
        .post('/api/v1/auth/login')
        .send({ email: userData.email, password: 'wrongpassword' })
        .expect(401);

      expect(res.body.success).toBe(false);
    });
  });

  describe('POST /api/v1/auth/refresh-tokens', () => {
    it('should refresh tokens with valid refresh token', async () => {
      const registerRes = await request(app)
        .post('/api/v1/auth/register')
        .send(userData);

      const refreshToken = registerRes.body.data.tokens.refresh.token;

      const res = await request(app)
        .post('/api/v1/auth/refresh-tokens')
        .send({ refreshToken })
        .expect(200);

      expect(res.body.success).toBe(true);
      expect(res.body.data.tokens.access).toBeDefined();
    });
  });
});
```

### Production Security Checklist

1. **Environment Variables**: Never commit secrets
2. **HTTPS Only**: Enforce HTTPS in production
3. **Token Security**: Use secure, random secrets
4. **Rate Limiting**: Protect auth endpoints
5. **Password Policy**: Enforce strong passwords
6. **Account Lockout**: Implement after failed attempts
7. **Email Verification**: Require for sensitive operations
8. **Token Expiry**: Use short-lived access tokens
9. **Refresh Token Rotation**: Rotate on each use
10. **Audit Logging**: Log all auth events

### Best Practices Summary

1. **JWT Strategy**: Use short-lived access tokens with refresh tokens
2. **Password Security**: Hash with bcrypt, enforce strong policies
3. **Email Verification**: Verify emails before full access
4. **Token Management**: Store refresh tokens, blacklist on logout
5. **Error Messages**: Don't reveal user existence
6. **Rate Limiting**: Protect against brute force
7. **Multi-Factor Auth**: Consider implementing for sensitive operations
8. **Session Management**: Provide logout from all devices
9. **Password Reset**: Use secure, time-limited tokens
10. **Audit Trail**: Log all authentication events

### Deployment Considerations

**Environment Setup:**
```bash
# Generate secure JWT secret
node -e "console.log(require('crypto').randomBytes(64).toString('hex'))"

# Set in production environment
export JWT_SECRET=<generated-secret>
export NODE_ENV=production
```

**Monitoring:**
- Track failed login attempts
- Monitor token refresh patterns
- Alert on suspicious activity
- Log all authentication events

**Maintenance:**
- Regularly rotate JWT secrets
- Clean up expired tokens
- Review and update security policies
- Keep dependencies updated

