const app = express();

// Security middleware
app.use(helmet());
app.use(cors());

// Logging
app.use(morgan('combined'));

// Request processing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(requestId);

// Routes
app.use('/api', routes);

// Error handling
app.use(errorHandler);

export default app;
