import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import { UserModel } from '../models/user.model';
import { ApiError } from '../utils/ApiError';
import { env } from '../config/environment';
import prisma from '../config/database';
import { sendPasswordResetEmail } from './email.service';

interface TokenPayload {
  id: string;
  email: string;
  role: string;
}

interface AuthTokens {
  accessToken: string;
  refreshToken: string;
}

export class AuthService {
  // Generate access token
  static generateAccessToken(payload: TokenPayload): string {
    return jwt.sign(payload, env.JWT_SECRET, {
      expiresIn: env.JWT_EXPIRE,
    });
  }

  // Generate refresh token
  static generateRefreshToken(payload: TokenPayload): string {
    return jwt.sign(payload, env.JWT_REFRESH_SECRET, {
      expiresIn: env.JWT_REFRESH_EXPIRE,
    });
  }

  // Generate both tokens
  static async generateAuthTokens(user: {
    id: string;
    email: string;
    role: string;
  }): Promise<AuthTokens> {
    const payload: TokenPayload = {
      id: user.id,
      email: user.email,
      role: user.role,
    };

    const accessToken = this.generateAccessToken(payload);
    const refreshToken = this.generateRefreshToken(payload);

    // Store refresh token in database
    await prisma.refreshToken.create({
      data: {
        token: refreshToken,
        userId: user.id,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
      },
    });

    return { accessToken, refreshToken };
  }

  // Register new user
  static async register(data: {
    email: string;
    password: string;
    firstName: string;
    lastName: string;
  }) {
    const user = await UserModel.create(data);
    const tokens = await this.generateAuthTokens(user);

    return { user, tokens };
  }

  // Login user
  static async login(email: string, password: string) {
    // Find user with password
    const user = await UserModel.findByEmail(email);

    if (!user) {
      throw new ApiError(401, 'Invalid email or password');
    }

    // Verify password
    const isPasswordValid = await UserModel.verifyPassword(
      password,
      user.password
    );

    if (!isPasswordValid) {
      throw new ApiError(401, 'Invalid email or password');
    }

    // Check if user is active
    if (!user.isActive) {
      throw new ApiError(401, 'Your account has been deactivated');
    }

    // Update last login
    await UserModel.updateLastLogin(user.id);

    // Generate tokens
    const tokens = await this.generateAuthTokens({
      id: user.id,
      email: user.email,
      role: user.role,
    });

    // Remove password from response
    const { password: _, ...userWithoutPassword } = user;

    return { user: userWithoutPassword, tokens };
  }

  // Logout user
  static async logout(refreshToken: string) {
    await prisma.refreshToken.delete({
      where: { token: refreshToken },
    });
  }

  // Refresh access token
  static async refreshAccessToken(refreshToken: string) {
    try {
      // Verify refresh token
      const decoded = jwt.verify(
        refreshToken,
        env.JWT_REFRESH_SECRET
      ) as TokenPayload;

      // Check if refresh token exists in database
      const storedToken = await prisma.refreshToken.findUnique({
        where: { token: refreshToken },
        include: { user: true },
      });

      if (!storedToken) {
        throw new ApiError(401, 'Invalid refresh token');
      }

      // Check if token is expired
      if (new Date() > storedToken.expiresAt) {
        await prisma.refreshToken.delete({
          where: { token: refreshToken },
        });
        throw new ApiError(401, 'Refresh token expired');
      }

      // Generate new access token
      const accessToken = this.generateAccessToken({
        id: decoded.id,
        email: decoded.email,
        role: decoded.role,
      });

      return { accessToken };
    } catch (error) {
      if (error instanceof jwt.JsonWebTokenError) {
        throw new ApiError(401, 'Invalid refresh token');
      }
      throw error;
    }
  }

  // Forgot password
  static async forgotPassword(email: string) {
    const resetToken = await UserModel.generatePasswordResetToken(email);

    if (!resetToken) {
      // Don't reveal if email exists
      return { message: 'If the email exists, a reset link has been sent' };
    }

    await sendPasswordResetEmail(email, resetToken);

    return { message: 'Password reset link sent to email' };
  }

  // Reset password
  static async resetPassword(token: string, newPassword: string) {
    const hashedToken = crypto.createHash('sha256').update(token).digest('hex');

    const user = await prisma.user.findFirst({
      where: {
        passwordResetToken: hashedToken,
        passwordResetExpires: {
          gt: new Date(),
        },
      },
    });

    if (!user) {
      throw new ApiError(400, 'Invalid or expired reset token');
    }

    await UserModel.updatePassword(user.id, newPassword);

    // Clear reset token
    await prisma.user.update({
      where: { id: user.id },
      data: {
        passwordResetToken: null,
        passwordResetExpires: null,
      },
    });

    return { message: 'Password reset successful' };
  }

  // Verify email
  static async verifyEmail(token: string) {
    const isVerified = await UserModel.verifyEmail(token);

    if (!isVerified) {
      throw new ApiError(400, 'Invalid or expired verification token');
    }

    return { message: 'Email verified successfully' };
  }

  // Cleanup expired refresh tokens
  static async cleanupExpiredTokens() {
    await prisma.refreshToken.deleteMany({
      where: {
        expiresAt: {
          lt: new Date(),
        },
      },
    });
  }
}
```

### Authentication Controllers

**src/controllers/auth.controller.ts:**
```typescript
import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiResponse } from '../utils/ApiResponse';
import { AuthService } from '../services/auth.service';

export const register = asyncHandler(async (req: Request, res: Response) => {
  const { email, password, firstName, lastName } = req.body;

  const { user, tokens } = await AuthService.register({
    email,
    password,
    firstName,
    lastName,
  });

  res.status(201).json(
    new ApiResponse(
      201,
      { user, tokens },
      'User registered successfully. Please verify your email.'
    )
  );
});

export const login = asyncHandler(async (req: Request, res: Response) => {
  const { email, password } = req.body;

  const { user, tokens } = await AuthService.login(email, password);

  // Set refresh token as httpOnly cookie
  res.cookie('refreshToken', tokens.refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  });

  res.status(200).json(
    new ApiResponse(
      200,
      { user, accessToken: tokens.accessToken },
      'Login successful'
    )
  );
});

export const logout = asyncHandler(async (req: Request, res: Response) => {
  const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

  if (refreshToken) {
    await AuthService.logout(refreshToken);
  }

  res.clearCookie('refreshToken');

  res.status(200).json(new ApiResponse(200, null, 'Logout successful'));
});

export const refreshToken = asyncHandler(
  async (req: Request, res: Response) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

    const { accessToken } = await AuthService.refreshAccessToken(refreshToken);

    res.status(200).json(
      new ApiResponse(200, { accessToken }, 'Token refreshed successfully')
    );
  }
);

export const forgotPassword = asyncHandler(
  async (req: Request, res: Response) => {
    const { email } = req.body;

    const result = await AuthService.forgotPassword(email);

    res.status(200).json(new ApiResponse(200, null, result.message));
  }
);

export const resetPassword = asyncHandler(
  async (req: Request, res: Response) => {
    const { token } = req.params;
    const { password } = req.body;

    const result = await AuthService.resetPassword(token, password);

    res.status(200).json(new ApiResponse(200, null, result.message));
  }
);

export const verifyEmail = asyncHandler(async (req: Request, res: Response) => {
  const { token } = req.params;

  const result = await AuthService.verifyEmail(token);

  res.status(200).json(new ApiResponse(200, null, result.message));
});
```

### OAuth 2.0 Integration (Google Example)

```bash
npm install passport passport-google-oauth20
npm install -D @types/passport @types/passport-google-oauth20
```

**src/config/passport.ts:**
```typescript
import passport from 'passport';
import { Strategy as GoogleStrategy } from 'passport-google-oauth20';
import { env } from './environment';
import { UserModel } from '../models/user.model';
import crypto from 'crypto';

passport.use(
  new GoogleStrategy(
    {
      clientID: env.GOOGLE_CLIENT_ID,
      clientSecret: env.GOOGLE_CLIENT_SECRET,
      callbackURL: `${env.API_URL}/api/${env.API_VERSION}/auth/google/callback`,
    },
    async (accessToken, refreshToken, profile, done) => {
      try {
        // Check if user exists
        let user = await UserModel.findByEmail(profile.emails![0].value);

        if (!user) {
          // Create new user
          user = await UserModel.create({
            email: profile.emails![0].value,
            firstName: profile.name!.givenName,
            lastName: profile.name!.familyName,
            password: crypto.randomBytes(32).toString('hex'), // Random password
            isEmailVerified: true,
          });
        }

        return done(null, user);
      } catch (error) {
        return done(error as Error);
      }
    }
  )
);

export default passport;
```

### Server Setup

**src/server.ts:**
```typescript
import app from './app';
import { env } from './config/environment';
import { logger } from './config/logger';
import { connectDatabase, disconnectDatabase } from './config/database';

const startServer = async () => {
  try {
    // Connect to database
    await connectDatabase();

    // Start server
    const server = app.listen(env.PORT, () => {
      logger.info(`Server running on port ${env.PORT} in ${env.NODE_ENV} mode`);
    });

    // Graceful shutdown
    const gracefulShutdown = async (signal: string) => {
      logger.info(`${signal} received. Starting graceful shutdown...`);

      server.close(async () => {
        logger.info('HTTP server closed');

        await disconnectDatabase();

        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

startServer();
```

