### Email Utility

**src/utils/email.ts:**
```typescript
import nodemailer from 'nodemailer';
import { logger } from '../config/logger';
import { env } from '../config/environment';

interface EmailOptions {
  to: string;
  subject: string;
  text?: string;
  html?: string;
}

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST,
  port: parseInt(process.env.SMTP_PORT || '587'),
  secure: process.env.SMTP_SECURE === 'true',
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS,
  },
});

export async function sendEmail(options: EmailOptions): Promise<void> {
  try {
    const mailOptions = {
      from: `${process.env.SMTP_FROM_NAME} <${process.env.SMTP_FROM_EMAIL}>`,
      to: options.to,
      subject: options.subject,
      text: options.text,
      html: options.html,
    };

    await transporter.sendMail(mailOptions);
    logger.info(`Email sent to ${options.to}`);
  } catch (error) {
    logger.error('Error sending email:', error);
    throw new ApiError(500, 'Failed to send email');
  }
}
```

### Main Application File

**src/app.ts:**
```typescript
import express, { Application } from 'express';
import cookieParser from 'cookie-parser';
import { env } from './config/environment';
import { corsConfig } from './middleware/security.middleware';
import { helmetConfig } from './middleware/security.middleware';
import { compressionConfig } from './middleware/compression.middleware';
import { requestLogger, responseTime, requestId } from './middleware/requestLogger.middleware';
import { rateLimiter } from './middleware/rateLimiter.middleware';
import { errorConverter, errorHandler, notFound } from './middleware/error.middleware';
import routes from './routes';

const app: Application = express();

// Security middleware
app.use(helmetConfig);
app.use(corsConfig);

// Request parsing
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));
app.use(cookieParser());

// Compression
app.use(compressionConfig);

// Logging and monitoring
app.use(requestId);
app.use(responseTime);
app.use(requestLogger);

// Rate limiting
app.use(rateLimiter());

// API routes
app.use(`/api/${env.API_VERSION}`, routes);

// Error handling
app.use(notFound);
app.use(errorConverter);
app.use(errorHandler);

export default app;
```

**src/server.ts:**
```typescript
import app from './app';
import { env } from './config/environment';
import { logger } from './config/logger';
import { connectDatabase, disconnectDatabase } from './config/database';

const startServer = async () => {
  try {
    // Connect to database
    await connectDatabase();

    // Start server
    const server = app.listen(env.PORT, () => {
      logger.info(`Server running on port ${env.PORT} in ${env.NODE_ENV} mode`);
      logger.info(`API available at http://localhost:${env.PORT}/api/${env.API_VERSION}`);
    });

    // Graceful shutdown
    const gracefulShutdown = async (signal: string) => {
      logger.info(`${signal} received. Starting graceful shutdown...`);

      server.close(async () => {
        logger.info('HTTP server closed');
        await disconnectDatabase();
        process.exit(0);
      });

      // Force shutdown after 30 seconds
      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 30000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

startServer();
```

### Testing Authentication

**tests/auth.test.ts:**
```typescript
import request from 'supertest';
import app from '../src/app';
import { prisma } from '../src/config/database';

describe('Authentication', () => {
  beforeAll(async () => {
    await prisma.$connect();
  });

  afterAll(async () => {
    await prisma.user.deleteMany();
    await prisma.$disconnect();
  });

  describe('POST /api/v1/auth/register', () => {
    it('should register a new user', async () => {
      const response = await request(app)
        .post('/api/v1/auth/register')
        .send({
          email: 'test@example.com',
          password: 'Test@123',
          firstName: 'Test',
          lastName: 'User',
        });

      expect(response.status).toBe(201);
      expect(response.body.success).toBe(true);
      expect(response.body.data.user.email).toBe('test@example.com');
    });

    it('should not register with existing email', async () => {
      const response = await request(app)
        .post('/api/v1/auth/register')
        .send({
          email: 'test@example.com',
          password: 'Test@123',
          firstName: 'Test',
          lastName: 'User',
        });

      expect(response.status).toBe(409);
    });
  });

  describe('POST /api/v1/auth/login', () => {
    it('should login with valid credentials', async () => {
      // First verify email
      const user = await prisma.user.findUnique({
        where: { email: 'test@example.com' },
      });

      await prisma.user.update({
        where: { id: user!.id },
        data: { emailVerified: true },
      });

      const response = await request(app)
        .post('/api/v1/auth/login')
        .send({
          email: 'test@example.com',
          password: 'Test@123',
        });

      expect(response.status).toBe(200);
      expect(response.body.data.accessToken).toBeDefined();
    });
  });
});
