### Protected Route Example

Apply authentication to protected routes:

```javascript
// src/routes/user.routes.js - Updated with auth
const express = require('express');
const userController = require('../controllers/user.controller');
const auth = require('../middleware/auth');
const { validate } = require('../middleware/validation');
const userValidation = require('../validators/user.validator');

const router = express.Router();

// Public routes (none for users)

// Protected routes - require authentication
router.use(auth());

router
  .route('/')
  .get(auth('getUsers'), userController.getAllUsers)
  .post(auth('manageUsers'), validate(userValidation.createUser), userController.createUser);

router
  .route('/:id')
  .get(auth('getUsers'), userController.getUserById)
  .put(auth('manageUsers'), validate(userValidation.updateUser), userController.updateUser)
  .delete(auth('manageUsers'), userController.deleteUser);

// User can access their own profile
router.get('/me/profile', userController.getMyProfile);
router.put('/me/profile', validate(userValidation.updateProfile), userController.updateMyProfile);

module.exports = router;
```

### API Key Authentication

Implement API key authentication for service-to-service communication:

```javascript
// src/middleware/apiKey.js
const ApiError = require('../utils/ApiError');
const ApiKey = require('../models/apiKey.model');
const crypto = require('crypto');

const apiKeyAuth = async (req, res, next) => {
  try {
    const apiKey = req.headers['x-api-key'];

    if (!apiKey) {
      throw new ApiError(401, 'API key required');
    }

    const hashedKey = crypto.createHash('sha256').update(apiKey).digest('hex');
    const keyDoc = await ApiKey.findOne({ key: hashedKey, active: true });

    if (!keyDoc) {
      throw new ApiError(401, 'Invalid API key');
    }

    // Update last used timestamp
    keyDoc.lastUsed = new Date();
    keyDoc.requestCount += 1;
    await keyDoc.save();

    req.apiKey = keyDoc;
    next();
  } catch (error) {
    next(error);
  }
};

module.exports = apiKeyAuth;
```

### Security Best Practices Implementation

Implement additional security measures:

```javascript
// src/middleware/security.js - Enhanced
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per window
  message: 'Too many authentication attempts, please try again later',
  standardHeaders: true,
  legacyHeaders: false
});

// Account lockout after failed attempts
const loginAttemptTracker = new Map();

const trackLoginAttempts = (req, res, next) => {
  const email = req.body.email;

  if (!email) {
    return next();
  }

  const attempts = loginAttemptTracker.get(email) || { count: 0, lockedUntil: null };

  if (attempts.lockedUntil && attempts.lockedUntil > Date.now()) {
    const remainingTime = Math.ceil((attempts.lockedUntil - Date.now()) / 1000 / 60);
    throw new ApiError(429, `Account locked. Try again in ${remainingTime} minutes`);
  }

  // Store original send to intercept response
  const originalJson = res.json.bind(res);

  res.json = (data) => {
    if (res.statusCode === 401) {
      attempts.count += 1;

      if (attempts.count >= 5) {
        attempts.lockedUntil = Date.now() + 30 * 60 * 1000; // 30 minutes
      }

      loginAttemptTracker.set(email, attempts);
    } else if (res.statusCode === 200) {
      loginAttemptTracker.delete(email);
    }

    return originalJson(data);
  };

  next();
};

module.exports = {
  authLimiter,
  trackLoginAttempts,
  mongoSanitize: mongoSanitize(),
  hpp: hpp()
};
```

### Testing Authentication

Comprehensive authentication tests:

```javascript
// tests/integration/auth.test.js
const request = require('supertest');
const app = require('../../src/app');
const { setupTestDB } = require('../utils/setupTestDB');
const User = require('../../src/models/user.model');

setupTestDB();

describe('Auth Routes', () => {
  describe('POST /api/v1/auth/register', () => {
    test('should register new user successfully', async () => {
      const newUser = {
        name: 'Test User',
        email: 'test@example.com',
        password: 'Password123!'
      };

      const res = await request(app)
        .post('/api/v1/auth/register')
        .send(newUser)
        .expect(201);

      expect(res.body.data.user).toHaveProperty('id');
      expect(res.body.data.user.email).toBe(newUser.email);
      expect(res.body.data.tokens).toHaveProperty('access');
      expect(res.body.data.tokens).toHaveProperty('refresh');
    });

    test('should return 400 if email already exists', async () => {
      await User.create({
        name: 'Existing User',
        email: 'existing@example.com',
        password: 'Password123!'
      });

      await request(app)
        .post('/api/v1/auth/register')
        .send({
          name: 'New User',
          email: 'existing@example.com',
          password: 'Password123!'
        })
        .expect(400);
    });
  });

  describe('POST /api/v1/auth/login', () => {
    test('should login successfully with valid credentials', async () => {
      const user = await User.create({
        name: 'Test User',
        email: 'test@example.com',
        password: 'Password123!',
        isEmailVerified: true
      });

      const res = await request(app)
        .post('/api/v1/auth/login')
        .send({
          email: 'test@example.com',
          password: 'Password123!'
        })
        .expect(200);

      expect(res.body.data.tokens).toHaveProperty('access');
      expect(res.body.data.tokens).toHaveProperty('refresh');
    });

    test('should return 401 with invalid credentials', async () => {
      await request(app)
        .post('/api/v1/auth/login')
        .send({
          email: 'wrong@example.com',
          password: 'WrongPassword123!'
        })
        .expect(401);
    });
  });
});
```

### Best Practices for Authentication & Authorization

1. **Password Security**: Use bcrypt with high cost factor (12+), enforce strong password policies
2. **Token Management**: Use short-lived access tokens, longer refresh tokens, implement token rotation
3. **HTTPS Only**: Always use HTTPS in production, set secure cookie flags
4. **Rate Limiting**: Implement aggressive rate limiting on auth endpoints
5. **Account Lockout**: Lock accounts after repeated failed login attempts
6. **Email Verification**: Require email verification before full account access
7. **Password Reset**: Use time-limited, single-use tokens for password reset
8. **Session Management**: Implement proper logout, token revocation, and session invalidation
9. **RBAC**: Use role-based access control for fine-grained permissions
10. **Audit Logging**: Log all authentication events for security monitoring
11. **Multi-Factor Authentication**: Consider implementing 2FA for sensitive operations
12. **Token Storage**: Never store tokens in localStorage; use httpOnly cookies when possible

### Production Deployment Checklist

Before deploying your API to production:

- [ ] All environment variables configured securely
- [ ] HTTPS enforced across all endpoints
- [ ] Database connections use SSL/TLS
- [ ] Rate limiting configured appropriately
- [ ] CORS configured for specific origins only
- [ ] Security headers properly set (CSP, HSTS, etc.)
- [ ] Input validation on all endpoints
- [ ] Error messages don't leak sensitive information
- [ ] Logging configured (but not logging sensitive data)
- [ ] Database indexes created for performance
- [ ] Backup and recovery procedures tested
- [ ] Monitoring and alerting configured
- [ ] API documentation complete and accurate
- [ ] Load testing performed
- [ ] Security audit completed

### Conclusion

You now have a complete, production-ready REST API with:

1. **Solid Foundation**: Well-organized project structure with proper configuration management
2. **Robust Routing**: RESTful routes with versioning, validation, and error handling
3. **Comprehensive Middleware**: Security, logging, rate limiting, caching, and request processing
4. **Database Integration**: MongoDB with Mongoose, transactions, caching, and health checks
5. **Secure Authentication**: JWT-based auth, password hashing, RBAC, and token management

This API follows industry best practices and is ready to scale. Continue to monitor, test, and iterate based on real-world usage patterns and security requirements.

