### Custom Validation Rules

Create `src/validators/custom.validators.ts`:

```typescript
import { z } from 'zod';

// Custom phone number validator
export const phoneNumberSchema = z
  .string()
  .regex(/^\+?[1-9]\d{1,14}$/, 'Invalid phone number format');

// Custom URL validator
export const urlSchema = z
  .string()
  .url('Invalid URL format')
  .refine(
    (url) => {
      try {
        const parsed = new URL(url);
        return ['http:', 'https:'].includes(parsed.protocol);
      } catch {
        return false;
      }
    },
    { message: 'URL must use HTTP or HTTPS protocol' }
  );

// Custom date range validator
export const dateRangeSchema = z
  .object({
    startDate: z.string().datetime(),
    endDate: z.string().datetime(),
  })
  .refine((data) => new Date(data.startDate) < new Date(data.endDate), {
    message: 'End date must be after start date',
    path: ['endDate'],
  });

// Custom file upload validator
export const fileUploadSchema = z.object({
  filename: z.string().min(1, 'Filename is required'),
  mimetype: z.enum(['image/jpeg', 'image/png', 'image/gif', 'application/pdf'], {
    errorMap: () => ({ message: 'Invalid file type' }),
  }),
  size: z.number().max(5 * 1024 * 1024, 'File size must not exceed 5MB'),
});

// Custom pagination validator
export const paginationSchema = z.object({
  page: z
    .string()
    .optional()
    .transform((val) => (val ? parseInt(val, 10) : 1))
    .refine((val) => val > 0, 'Page must be greater than 0'),
  limit: z
    .string()
    .optional()
    .transform((val) => (val ? parseInt(val, 10) : 10))
    .refine((val) => val > 0 && val <= 100, 'Limit must be between 1 and 100'),
});

// Custom sort validator
export const sortSchema = z
  .string()
  .optional()
  .transform((val) => {
    if (!val) return { createdAt: -1 };
    const [field, order] = val.split(':');
    return { [field]: order === 'desc' ? -1 : 1 };
  });
```

### Query Parameter Validation

Create `src/validators/query.validator.ts`:

```typescript
import { z } from 'zod';

export const queryValidators = {
  list: z.object({
    query: z.object({
      page: z
        .string()
        .optional()
        .transform((val) => (val ? parseInt(val, 10) : 1)),
      limit: z
        .string()
        .optional()
        .transform((val) => (val ? parseInt(val, 10) : 10)),
      sort: z.string().optional(),
      search: z.string().optional(),
      status: z.enum(['active', 'inactive', 'pending']).optional(),
      role: z.enum(['user', 'admin']).optional(),
      startDate: z.string().datetime().optional(),
      endDate: z.string().datetime().optional(),
    }),
  }),

  search: z.object({
    query: z.object({
      q: z.string().min(1, 'Search query is required'),
      fields: z
        .string()
        .optional()
        .transform((val) => (val ? val.split(',') : undefined)),
      limit: z
        .string()
        .optional()
        .transform((val) => (val ? parseInt(val, 10) : 10)),
    }),
  }),
};
