Create `src/routes/product.routes.js`:

```javascript
const express = require('express');
const productController = require('../controllers/product.controller');
const { protect, restrictTo, optionalAuth } = require('../middleware/auth');
const {
  validateCreateProduct,
  validateUpdateProduct,
  validateProductId,
  validateGetProductsQuery
} = require('../middleware/validation');

const router = express.Router();

// Public routes (with optional auth for personalization)
router.get('/', optionalAuth, validateGetProductsQuery, productController.getAllProducts);
router.get('/:id', optionalAuth, validateProductId, productController.getProductById);

// Protected routes
router.use(protect);
router.use(restrictTo('admin', 'moderator'));

router.post('/', validateCreateProduct, productController.createProduct);
router.put('/:id', validateProductId, validateUpdateProduct, productController.updateProduct);
router.delete('/:id', validateProductId, productController.deleteProduct);

module.exports = router;
```

### Enhanced Error Handler for Validation

Update `src/middleware/errorHandler.js` to handle validation errors:

```javascript
const logger = require('../utils/logger');
const { ValidationError } = require('../utils/validation');

const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;

  // Log error
  logger.error('Error:', {
    message: err.message,
    stack: err.stack,
    requestId: req.context?.requestId
  });

  // Validation errors
  if (err.isValidationError) {
    return res.status(err.statusCode).json({
      status: 'error',
      message: err.message,
      errors: err.errors,
      requestId: req.context?.requestId
    });
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => ({
      field: e.path,
      message: e.message
    }));

    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors,
      requestId: req.context?.requestId
    });
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyPattern)[0];
    return res.status(400).json({
      status: 'error',
      message: `${field} already exists`,
      requestId: req.context?.requestId
    });
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      status: 'error',
      message: 'Invalid token',
      requestId: req.context?.requestId
    });
  }

  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({
      status: 'error',
      message: 'Token expired',
      requestId: req.context?.requestId
    });
  }

  // Operational errors
  if (err.isOperational) {
    return res.status(err.statusCode || 500).json({
      status: 'error',
      message: err.message,
      requestId: req.context?.requestId
    });
  }

  // Programming or unknown errors
  return res.status(500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message,
    requestId: req.context?.requestId
  });
};

module.exports = errorHandler;
```

### Validation Testing

Create `tests/validators/user.validator.test.js`:

```javascript
const { createUserSchema, updateUserSchema } = require('../../src/validators/user.validator');

describe('User Validators', () => {
  describe('createUserSchema', () => {
    it('should validate correct user data', () => {
      const validUser = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'Password123!',
        role: 'user'
      };

      const { error, value } = createUserSchema.validate(validUser);
      expect(error).toBeUndefined();
      expect(value).toMatchObject(validUser);
    });

    it('should reject invalid email', () => {
      const invalidUser = {
        name: 'John Doe',
        email: 'invalid-email',
        password: 'Password123!'
      };

      const { error } = createUserSchema.validate(invalidUser);
      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('email');
    });

    it('should reject short password', () => {
      const invalidUser = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'short'
      };

      const { error } = createUserSchema.validate(invalidUser);
      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('password');
    });

    it('should reject invalid role', () => {
      const invalidUser = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'Password123!',
        role: 'superadmin'
      };

      const { error } = createUserSchema.validate(invalidUser);
      expect(error).toBeDefined();
    });
  });

  describe('updateUserSchema', () => {
    it('should validate partial updates', () => {
      const partialUpdate = {
        name: 'Jane Doe'
      };

      const { error, value } = updateUserSchema.validate(partialUpdate);
      expect(error).toBeUndefined();
      expect(value.name).toBe('Jane Doe');
    });

    it('should reject empty updates', () => {
      const { error } = updateUserSchema.validate({});
      expect(error).toBeDefined();
    });
  });
});
```

### Best Practices Implemented

- **Comprehensive validation**: All inputs validated with detailed schemas
- **Custom validators**: Reusable validation patterns for common fields
- **Clear error messages**: User-friendly validation error messages
- **Type safety**: Proper type checking and coercion
- **Security**: Input sanitization and XSS prevention
- **Consistency**: Standardized validation across all endpoints
- **Testability**: Validation logic easily testable
- **Performance**: Efficient validation with early abort options
- **Flexibility**: Support for optional fields and partial updates
- **Documentation**: Self-documenting schemas

