Input validation is critical for building secure, reliable REST APIs. Proper validation prevents invalid data from entering your system, provides clear error messages to clients, and protects against security vulnerabilities.

### Why Validation Matters

Validation serves multiple purposes in production APIs:
- **Security**: Prevents injection attacks, XSS, and malformed data exploits
- **Data Integrity**: Ensures only valid data reaches your database
- **User Experience**: Provides clear, actionable error messages
- **Documentation**: Validation schemas serve as living documentation of your API contracts

### Choosing a Validation Library

Popular validation libraries for Node.js/Express:

**Joi** - Feature-rich, expressive schema validation
```javascript
const Joi = require('joi');

const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).required(),
  age: Joi.number().integer().min(18).max(120)
});
```

**Yup** - Similar to Joi, works well with React/frontend
```javascript
const yup = require('yup');

const userSchema = yup.object({
  email: yup.string().email().required(),
  password: yup.string().min(8).required(),
  age: yup.number().positive().integer().min(18)
});
```

**express-validator** - Built on validator.js, Express-native
```javascript
const { body, validationResult } = require('express-validator');

app.post('/users', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }),
  body('age').isInt({ min: 18, max: 120 })
], handler);
```

### Implementing Validation Middleware

Create reusable validation middleware using Joi:

```javascript
// middleware/validate.js
const validate = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false, // Return all errors, not just first
      stripUnknown: true // Remove unknown fields
    });

    if (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));

      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors
      });
    }

    // Replace req.body with validated/sanitized value
    req.body = value;
    next();
  };
};

module.exports = validate;
```

### Validation Schemas

Define schemas for each resource:

```javascript
// schemas/user.schema.js
const Joi = require('joi');

const createUserSchema = Joi.object({
  email: Joi.string()
    .email()
    .required()
    .messages({
      'string.email': 'Please provide a valid email address',
      'any.required': 'Email is required'
    }),

  password: Joi.string()
    .min(8)
    .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .required()
    .messages({
      'string.min': 'Password must be at least 8 characters',
      'string.pattern.base': 'Password must contain uppercase, lowercase, and number'
    }),

  username: Joi.string()
    .alphanum()
    .min(3)
    .max(30)
    .required(),

  role: Joi.string()
    .valid('user', 'admin', 'moderator')
    .default('user')
});

const updateUserSchema = Joi.object({
  email: Joi.string().email(),
  username: Joi.string().alphanum().min(3).max(30),
  role: Joi.string().valid('user', 'admin', 'moderator')
}).min(1); // At least one field required

module.exports = {
  createUserSchema,
  updateUserSchema
};
```

### Applying Validation to Routes

```javascript
// routes/users.js
const express = require('express');
const router = express.Router();
const validate = require('../middleware/validate');
const { createUserSchema, updateUserSchema } = require('../schemas/user.schema');
const userController = require('../controllers/user.controller');

router.post('/', 
  validate(createUserSchema), 
  userController.create
);

router.put('/:id', 
  validate(updateUserSchema), 
  userController.update
);

module.exports = router;
```

### Query Parameter Validation

Don't forget to validate query parameters and URL params:

```javascript
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));

      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters',
        errors
      });
    }

    req.query = value;
    next();
  };
};

// Pagination schema
const paginationSchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(20),
  sort: Joi.string().valid('createdAt', 'updatedAt', 'name'),
  order: Joi.string().valid('asc', 'desc').default('desc')
});

router.get('/users', 
  validateQuery(paginationSchema), 
  userController.list
);
```

### Advanced Validation Patterns

**Conditional Validation**:
```javascript
const paymentSchema = Joi.object({
  method: Joi.string().valid('card', 'paypal').required(),

  // Only required if method is 'card'
  cardNumber: Joi.when('method', {
    is: 'card',
    then: Joi.string().creditCard().required(),
    otherwise: Joi.forbidden()
  }),

  // Only required if method is 'paypal'
  paypalEmail: Joi.when('method', {
    is: 'paypal',
    then: Joi.string().email().required(),
    otherwise: Joi.forbidden()
  })
});
```

**Custom Validation**:
```javascript
const userSchema = Joi.object({
  email: Joi.string().email().required(),

  password: Joi.string()
    .required()
    .custom((value, helpers) => {
      // Check against common passwords list
      if (commonPasswords.includes(value)) {
        return helpers.error('password.common');
      }
      return value;
    })
    .messages({
      'password.common': 'This password is too common. Please choose a stronger password.'
    })
});
```

**Async Validation** (e.g., checking uniqueness):
```javascript
const createUserSchema = Joi.object({
  email: Joi.string()
    .email()
    .required()
    .external(async (value) => {
      const exists = await User.findOne({ email: value });
      if (exists) {
        throw new Error('Email already registered');
      }
    })
});

// Use with async validation
const validate = (schema) => {
  return async (req, res, next) => {
    try {
      const value = await schema.validateAsync(req.body, {
        abortEarly: false,
        stripUnknown: true
      });

      req.body = value;
      next();
    } catch (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));

      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors
      });
    }
  };
};
```

### File Upload Validation

```javascript
const multer = require('multer');

const fileFilter = (req, file, cb) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/gif'];

  if (allowedTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Invalid file type. Only JPEG, PNG and GIF allowed.'), false);
  }
};

const upload = multer({
  storage: multer.diskStorage({
    destination: 'uploads/',
    filename: (req, file, cb) => {
      const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
      cb(null, file.fieldname + '-' + uniqueSuffix);
    }
  }),
  fileFilter,
  limits: {
    fileSize: 5 * 1024 * 1024 // 5MB
  }
});

router.post('/avatar', 
  upload.single('avatar'),
  (error, req, res, next) => {
    if (error instanceof multer.MulterError) {
      return res.status(400).json({
        status: 'error',
        message: error.message
      });
    } else if (error) {
      return res.status(400).json({
        status: 'error',
        message: error.message
      });
    }
    next();
  },
  userController.uploadAvatar
);
```

### Sanitization

Always sanitize input to prevent XSS and injection attacks:

```javascript
const Joi = require('joi');
const sanitizeHtml = require('sanitize-html');

const postSchema = Joi.object({
  title: Joi.string()
    .min(3)
    .max(200)
    .required()
    .custom((value) => sanitizeHtml(value, { allowedTags: [] })),

  content: Joi.string()
    .required()
    .custom((value) => sanitizeHtml(value, {
      allowedTags: ['b', 'i', 'em', 'strong', 'a', 'p'],
      allowedAttributes: {
        'a': ['href']
      }
    }))
});
```

### Best Practices

1. **Validate Early**: Validate at the API boundary before processing
2. **Fail Fast**: Return validation errors immediately with clear messages
3. **Whitelist, Don't Blacklist**: Define what's allowed, not what's forbidden
4. **Strip Unknown Fields**: Remove unexpected fields to prevent mass assignment
5. **Provide Helpful Errors**: Return field-specific error messages
6. **Validate Everything**: Body, query params, URL params, headers, files
7. **Use Type Coercion Carefully**: Be explicit about type conversions
8. **Document Schemas**: Keep validation schemas as API documentation
9. **Test Validation**: Write tests for both valid and invalid inputs
10. **Centralize Schemas**: Reuse validation schemas across routes

### Testing Validation

```javascript
// tests/validation/user.test.js
const { createUserSchema } = require('../../schemas/user.schema');

describe('User Validation', () => {
  describe('createUserSchema', () => {
    it('should accept valid user data', () => {
      const validUser = {
        email: 'test@example.com',
        password: 'SecurePass123',
        username: 'testuser'
      };

      const { error, value } = createUserSchema.validate(validUser);
      expect(error).toBeUndefined();
      expect(value).toMatchObject(validUser);
    });

    it('should reject invalid email', () => {
      const invalidUser = {
        email: 'not-an-email',
        password: 'SecurePass123',
        username: 'testuser'
      };

      const { error } = createUserSchema.validate(invalidUser);
      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('email');
    });

    it('should reject weak password', () => {
      const invalidUser = {
        email: 'test@example.com',
        password: 'weak',
        username: 'testuser'
      };

      const { error } = createUserSchema.validate(invalidUser);
      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('password');
    });
  });
});
```

### Production Checklist

- ✅ All endpoints have input validation
- ✅ Query parameters and URL params are validated
- ✅ File uploads have type and size restrictions
- ✅ Custom error messages are user-friendly
- ✅ Validation errors return 400 status codes
- ✅ Unknown fields are stripped from requests
- ✅ Input is sanitized to prevent XSS
- ✅ Async validation for uniqueness checks
- ✅ Validation schemas are tested
- ✅ Rate limiting on validation-heavy endpoints

