### Authentication Controller

Create `src/controllers/auth.controller.ts`:

```typescript
import { Request, Response } from 'express';
import { BaseController } from './base.controller';
import { AuthService } from '../services/auth.service';
import { AuthRequest } from '../types';

export class AuthController extends BaseController {
  private authService: AuthService;

  constructor() {
    super();
    this.authService = new AuthService();
  }

  register = this.wrap(async (req: Request, res: Response) => {
    const result = await this.authService.register(req.body);
    this.sendCreated(res, result, 'User registered successfully');
  });

  login = this.wrap(async (req: Request, res: Response) => {
    const result = await this.authService.login(req.body);
    this.sendSuccess(res, result, 'Login successful');
  });

  refreshToken = this.wrap(async (req: Request, res: Response) => {
    const { refreshToken } = req.body;
    const tokens = await this.authService.refreshToken(refreshToken);
    this.sendSuccess(res, { tokens }, 'Token refreshed successfully');
  });

  logout = this.wrap(async (req: AuthRequest, res: Response) => {
    const { refreshToken } = req.body;
    await this.authService.logout(req.user!.id, refreshToken);
    this.sendSuccess(res, null, 'Logout successful');
  });

  forgotPassword = this.wrap(async (req: Request, res: Response) => {
    const message = await this.authService.forgotPassword(req.body.email);
    this.sendSuccess(res, null, message);
  });

  resetPassword = this.wrap(async (req: Request, res: Response) => {
    const { token, password } = req.body;
    await this.authService.resetPassword(token, password);
    this.sendSuccess(res, null, 'Password reset successful');
  });

  changePassword = this.wrap(async (req: AuthRequest, res: Response) => {
    const { currentPassword, newPassword } = req.body;
    await this.authService.changePassword(
      req.user!.id,
      currentPassword,
      newPassword
    );
    this.sendSuccess(res, null, 'Password changed successfully');
  });

  verifyEmail = this.wrap(async (req: Request, res: Response) => {
    const { token } = req.body;
    await this.authService.verifyEmail(token);
    this.sendSuccess(res, null, 'Email verified successfully');
  });
}
