Update `src/routes/product.routes.js`:

```javascript
const express = require('express');
const productController = require('../controllers/product.controller');
const { protect, restrictTo } = require('../middleware/auth');
const { validate, validateMultiple } = require('../middleware/validate');
const productSchemas = require('../validation/schemas/product.schema');
const commonSchemas = require('../validation/schemas/common.schema');

const router = express.Router();

// Public routes
router.get(
  '/',
  validate(commonSchemas.pagination, 'query'),
  productController.getAllProducts
);

router.get(
  '/search',
  validate(productSchemas.search, 'query'),
  productController.searchProducts
);

router.get(
  '/:id',
  validate(commonSchemas.id, 'params'),
  productController.getProduct
);

// Protected routes
router.use(protect);

// Admin only routes
router.post(
  '/',
  restrictTo('admin'),
  validate(productSchemas.create),
  productController.createProduct
);

router.patch(
  '/:id',
  restrictTo('admin'),
  validateMultiple({
    params: commonSchemas.id,
    body: productSchemas.update
  }),
  productController.updateProduct
);

router.delete(
  '/:id',
  restrictTo('admin'),
  validate(commonSchemas.id, 'params'),
  productController.deleteProduct
);

module.exports = router;
```

### Custom Validators

Create `src/validation/customValidators.js`:

```javascript
const Joi = require('joi');

/**
 * Custom validator for strong passwords
 */
const strongPassword = Joi.string()
  .min(8)
  .max(128)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .messages({
    'string.pattern.base': 'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character'
  });

/**
 * Custom validator for MongoDB ObjectId
 */
const objectId = Joi.string()
  .pattern(/^[0-9a-fA-F]{24}$/)
  .messages({
    'string.pattern.base': 'Invalid ID format'
  });

/**
 * Custom validator for phone numbers
 */
const phoneNumber = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Invalid phone number format'
  });

/**
 * Custom validator for URLs
 */
const url = Joi.string()
  .uri({ scheme: ['http', 'https'] })
  .messages({
    'string.uri': 'Invalid URL format'
  });

/**
 * Custom validator for dates in the future
 */
const futureDate = Joi.date()
  .greater('now')
  .messages({
    'date.greater': 'Date must be in the future'
  });

/**
 * Custom validator for dates in the past
 */
const pastDate = Joi.date()
  .less('now')
  .messages({
    'date.less': 'Date must be in the past'
  });

module.exports = {
  strongPassword,
  objectId,
  phoneNumber,
  url,
  futureDate,
  pastDate
};
```

### Validation Testing

Create `tests/validation/user.validation.test.js`:

```javascript
const userSchemas = require('../../src/validation/schemas/user.schema');

describe('User Validation Schemas', () => {
  describe('Register Schema', () => {
    it('should validate correct registration data', () => {
      const data = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'Test123!@#'
      };

      const { error, value } = userSchemas.register.validate(data);

      expect(error).toBeUndefined();
      expect(value.email).toBe('john@example.com');
    });

    it('should reject weak password', () => {
      const data = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'weak'
      };

      const { error } = userSchemas.register.validate(data);

      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('password');
    });

    it('should reject invalid email', () => {
      const data = {
        name: 'John Doe',
        email: 'invalid-email',
        password: 'Test123!@#'
      };

      const { error } = userSchemas.register.validate(data);

      expect(error).toBeDefined();
      expect(error.details[0].path).toContain('email');
    });

    it('should convert email to lowercase', () => {
      const data = {
        name: 'John Doe',
        email: 'JOHN@EXAMPLE.COM',
        password: 'Test123!@#'
      };

      const { value } = userSchemas.register.validate(data);

      expect(value.email).toBe('john@example.com');
    });
  });

  describe('Update Password Schema', () => {
    it('should reject same current and new password', () => {
      const data = {
        currentPassword: 'Test123!@#',
        newPassword: 'Test123!@#'
      };

      const { error } = userSchemas.updatePassword.validate(data);

      expect(error).toBeDefined();
      expect(error.details[0].message).toContain('different');
    });
  });
});
```

### Validation Best Practices Summary

1. **Schema Organization**: Group related schemas in separate files
2. **Custom Messages**: Provide clear, user-friendly error messages
3. **Type Coercion**: Use `convert: true` to automatically convert types
4. **Strip Unknown**: Remove unexpected fields with `stripUnknown: true`
5. **Fail Fast**: Use `abortEarly: false` to return all errors at once
6. **Reusable Validators**: Create custom validators for common patterns
7. **Source Validation**: Validate params, query, and body separately
8. **Security**: Validate and sanitize all user input
9. **Documentation**: Document validation rules in API documentation
10. **Testing**: Write comprehensive tests for validation schemas

