### Section 6: Validation

Input validation is critical for API security, data integrity, and user experience. Proper validation prevents malicious data, ensures data consistency, and provides clear feedback to API consumers.

#### Why Validation Matters

- **Security**: Prevents injection attacks, XSS, and malformed data
- **Data Integrity**: Ensures only valid data enters your database
- **User Experience**: Provides clear, actionable error messages
- **Documentation**: Validation schemas serve as API contracts

#### Validation Strategies

**1. Schema-Based Validation**

Use libraries like Joi, Yup, or Zod for declarative validation:

```javascript
const Joi = require('joi');

const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).pattern(/^(?=.*[A-Z])(?=.*[0-9])/).required(),
  age: Joi.number().integer().min(18).max(120),
  role: Joi.string().valid('user', 'admin', 'moderator').default('user')
});

// Validation middleware
const validateUser = (req, res, next) => {
  const { error, value } = userSchema.validate(req.body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message
      }))
    });
  }

  req.validatedData = value;
  next();
};
```

**2. Request Validation Layers**

Validate different parts of the request:

```javascript
const { body, param, query, validationResult } = require('express-validator');

router.post('/users/:id/posts',
  // Path parameters
  param('id').isMongoId().withMessage('Invalid user ID'),

  // Query parameters
  query('publish').optional().isBoolean(),

  // Request body
  body('title').trim().isLength({ min: 5, max: 200 }),
  body('content').trim().notEmpty(),
  body('tags').isArray().optional(),
  body('tags.*').isString().trim(),

  // Check results
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  },

  createPost
);
```

**3. Custom Validators**

Implement business logic validation:

```javascript
const customValidators = {
  isUniqueEmail: async (email) => {
    const user = await User.findOne({ email });
    if (user) {
      throw new Error('Email already registered');
    }
    return true;
  },

  isValidDateRange: (startDate, endDate) => {
    const start = new Date(startDate);
    const end = new Date(endDate);
    if (end <= start) {
      throw new Error('End date must be after start date');
    }
    return true;
  },

  hasPermission: async (userId, resourceId) => {
    const resource = await Resource.findById(resourceId);
    if (resource.ownerId !== userId) {
      throw new Error('Insufficient permissions');
    }
    return true;
  }
};
```

**4. Sanitization**

Clean input data to prevent attacks:

```javascript
const sanitize = require('sanitize-html');
const validator = require('validator');

const sanitizeInput = (req, res, next) => {
  // Escape HTML
  if (req.body.content) {
    req.body.content = sanitize(req.body.content, {
      allowedTags: ['b', 'i', 'em', 'strong', 'p'],
      allowedAttributes: {}
    });
  }

  // Normalize email
  if (req.body.email) {
    req.body.email = validator.normalizeEmail(req.body.email);
  }

  // Trim strings
  Object.keys(req.body).forEach(key => {
    if (typeof req.body[key] === 'string') {
      req.body[key] = req.body[key].trim();
    }
  });

  next();
};
```

#### Production Best Practices

**1. Centralized Validation**

Create reusable validation schemas:

```javascript
// validators/schemas.js
const schemas = {
  user: {
    create: Joi.object({
      email: Joi.string().email().required(),
      password: Joi.string().min(8).required(),
      name: Joi.string().min(2).max(100).required()
    }),

    update: Joi.object({
      email: Joi.string().email(),
      name: Joi.string().min(2).max(100),
      bio: Joi.string().max(500)
    }).min(1) // At least one field required
  },

  post: {
    create: Joi.object({
      title: Joi.string().min(5).max(200).required(),
      content: Joi.string().min(10).required(),
      tags: Joi.array().items(Joi.string()).max(10)
    })
  }
};

// Validation factory
const validate = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message
      }))
    });
  }

  req.validatedData = value;
  next();
};

module.exports = { schemas, validate };
```

**2. Error Response Format**

Standardize validation error responses:

```javascript
class ValidationError extends Error {
  constructor(errors) {
    super('Validation failed');
    this.name = 'ValidationError';
    this.statusCode = 400;
    this.errors = errors;
  }

  toJSON() {
    return {
      error: {
        type: 'ValidationError',
        message: this.message,
        fields: this.errors.reduce((acc, err) => {
          acc[err.field] = err.message;
          return acc;
        }, {})
      }
    };
  }
}
```

**3. File Upload Validation**

Validate file uploads securely:

```javascript
const multer = require('multer');
const path = require('path');

const fileFilter = (req, file, cb) => {
  const allowedTypes = /jpeg|jpg|png|pdf/;
  const extname = allowedTypes.test(
    path.extname(file.originalname).toLowerCase()
  );
  const mimetype = allowedTypes.test(file.mimetype);

  if (extname && mimetype) {
    cb(null, true);
  } else {
    cb(new Error('Invalid file type. Only JPEG, PNG, and PDF allowed.'));
  }
};

const upload = multer({
  storage: multer.diskStorage({
    destination: './uploads/',
    filename: (req, file, cb) => {
      cb(null, `${Date.now()}-${file.originalname}`);
    }
  }),
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB
    files: 1
  },
  fileFilter
});
```

**4. Rate Limiting Validation**

Prevent abuse with rate limiting:

```javascript
const rateLimit = require('express-rate-limit');

const createAccountLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // 5 accounts per hour
  message: 'Too many accounts created. Please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});

router.post('/register', createAccountLimiter, validate(schemas.user.create), register);
```

#### Testing Validation

```javascript
describe('User Validation', () => {
  it('should reject invalid email', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ email: 'invalid-email', password: 'Test1234' });

    expect(res.status).toBe(400);
    expect(res.body.errors).toContainEqual(
      expect.objectContaining({ field: 'email' })
    );
  });

  it('should reject weak password', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ email: 'test@example.com', password: '123' });

    expect(res.status).toBe(400);
    expect(res.body.errors).toContainEqual(
      expect.objectContaining({ field: 'password' })
    );
  });

  it('should accept valid data', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ 
        email: 'test@example.com', 
        password: 'SecurePass123',
        name: 'Test User'
      });

    expect(res.status).toBe(201);
  });
});
```

#### Key Takeaways

- **Validate Early**: Check input at the API boundary before processing
- **Be Specific**: Provide clear, actionable error messages
- **Sanitize Always**: Clean input to prevent injection attacks
- **Fail Securely**: Don't expose internal details in validation errors
- **Document Schemas**: Use validation schemas as API documentation
- **Test Thoroughly**: Cover edge cases and malicious input scenarios

