## Section 6: Validation

### Validation with Zod

Install Zod:

```bash
npm install zod
```

### Authentication Validators

Create `src/validators/auth.validator.ts`:

```typescript
import { z } from 'zod';

const passwordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
  .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
  .regex(/[0-9]/, 'Password must contain at least one number')
  .regex(
    /[^A-Za-z0-9]/,
    'Password must contain at least one special character'
  );

const emailSchema = z
  .string()
  .email('Invalid email address')
  .toLowerCase()
  .trim();

export const authValidator = {
  register: z.object({
    body: z.object({
      email: emailSchema,
      password: passwordSchema,
      firstName: z
        .string()
        .min(2, 'First name must be at least 2 characters')
        .max(50, 'First name cannot exceed 50 characters')
        .trim(),
      lastName: z
        .string()
        .min(2, 'Last name must be at least 2 characters')
        .max(50, 'Last name cannot exceed 50 characters')
        .trim(),
    }),
  }),

  login: z.object({
    body: z.object({
      email: emailSchema,
      password: z.string().min(1, 'Password is required'),
    }),
  }),

  refreshToken: z.object({
    body: z.object({
      refreshToken: z.string().min(1, 'Refresh token is required'),
    }),
  }),

  forgotPassword: z.object({
    body: z.object({
      email: emailSchema,
    }),
  }),

  resetPassword: z.object({
    params: z.object({
      token: z.string().min(1, 'Token is required'),
    }),
    body: z.object({
      password: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.password === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }),
  }),

  updatePassword: z.object({
    body: z.object({
      currentPassword: z.string().min(1, 'Current password is required'),
      newPassword: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.newPassword === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }),
  }),
};
```

### User Validators

Create `src/validators/user.validator.ts`:

```typescript
import { z } from 'zod';

const mongoIdSchema = z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format');

export const userValidator = {
  getUserById: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  updateUser: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
    body: z.object({
      firstName: z
        .string()
        .min(2, 'First name must be at least 2 characters')
        .max(50, 'First name cannot exceed 50 characters')
        .trim()
        .optional(),
      lastName: z
        .string()
        .min(2, 'Last name must be at least 2 characters')
        .max(50, 'Last name cannot exceed 50 characters')
        .trim()
        .optional(),
      email: z
        .string()
        .email('Invalid email address')
        .toLowerCase()
        .trim()
        .optional(),
    }).refine((data) => Object.keys(data).length > 0, {
      message: 'At least one field must be provided',
    }),
  }),

  deleteUser: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  uploadAvatar: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),
};
```

### Product Validators

Create `src/validators/product.validator.ts`:

```typescript
import { z } from 'zod';

const mongoIdSchema = z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format');

export const productValidator = {
  createProduct: z.object({
    body: z.object({
      name: z
        .string()
        .min(3, 'Product name must be at least 3 characters')
        .max(100, 'Product name cannot exceed 100 characters')
        .trim(),
      description: z
        .string()
        .min(10, 'Description must be at least 10 characters')
        .max(2000, 'Description cannot exceed 2000 characters')
        .trim(),
      price: z
        .number()
        .positive('Price must be positive')
        .max(1000000, 'Price cannot exceed 1,000,000'),
      category: z.enum([
        'electronics',
        'clothing',
        'books',
        'home',
        'sports',
        'other',
      ]),
      stock: z
        .number()
        .int('Stock must be an integer')
        .nonnegative('Stock cannot be negative')
        .default(0),
      images: z
        .array(z.string().url('Invalid image URL'))
        .max(5, 'Cannot upload more than 5 images')
        .optional(),
    }),
  }),

  updateProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
    body: z.object({
      name: z
        .string()
        .min(3, 'Product name must be at least 3 characters')
        .max(100, 'Product name cannot exceed 100 characters')
        .trim()
        .optional(),
      description: z
        .string()
        .min(10, 'Description must be at least 10 characters')
        .max(2000, 'Description cannot exceed 2000 characters')
        .trim()
        .optional(),
      price: z
        .number()
        .positive('Price must be positive')
        .max(1000000, 'Price cannot exceed 1,000,000')
        .optional(),
      category: z
        .enum(['electronics', 'clothing', 'books', 'home', 'sports', 'other'])
        .optional(),
      stock: z
        .number()
        .int('Stock must be an integer')
        .nonnegative('Stock cannot be negative')
        .optional(),
      images: z
        .array(z.string().url('Invalid image URL'))
        .max(5, 'Cannot upload more than 5 images')
        .optional(),
      isActive: z.boolean().optional(),
    }).refine((data) => Object.keys(data).length > 0, {
      message: 'At least one field must be provided',
    }),
  }),

  getProductById: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  deleteProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  searchProducts: z.object({
    query: z.object({
      q: z.string().min(1, 'Search query is required').optional(),
      category: z
        .enum(['electronics', 'clothing', 'books', 'home', 'sports', 'other'])
        .optional(),
      minPrice: z
        .string()
        .transform((val) => parseFloat(val))
        .pipe(z.number().nonnegative())
        .optional(),
      maxPrice: z
        .string()
        .transform((val) => parseFloat(val))
        .pipe(z.number().positive())
        .optional(),
      page: z
        .string()
        .transform((val) => parseInt(val, 10))
        .pipe(z.number().int().positive())
        .default('1'),
      limit: z
        .string()
        .transform((val) => parseInt(val, 10))
        .pipe(z.number().int().positive().max(100))
        .default('10'),
      sort: z
        .enum(['price', '-price', 'name', '-name', 'createdAt', '-createdAt'])
        .default('-createdAt'),
    }),
  }),

  bulkCreate: z.object({
    body: z.object({
      products: z
        .array(
          z.object({
            name: z.string().min(3).max(100).trim(),
            description: z.string().min(10).max(2000).trim(),
            price: z.number().positive().max(1000000),
            category: z.enum([
              'electronics',
              'clothing',
              'books',
              'home',
              'sports',
              'other',
            ]),
            stock: z.number().int().nonnegative().default(0),
          })
        )
        .min(1, 'At least one product is required')
        .max(100, 'Cannot create more than 100 products at once'),
    }),
  }),
};
```

### Custom Validation Helpers

Create `src/validators/helpers.ts`:

```typescript
import { z } from 'zod';

// File upload validation
export const fileSchema = z.object({
  fieldname: z.string(),
  originalname: z.string(),
  encoding: z.string(),
  mimetype: z.string(),
  size: z.number(),
  destination: z.string().optional(),
  filename: z.string().optional(),
  path: z.string().optional(),
  buffer: z.instanceof(Buffer).optional(),
});

export const imageFileSchema = fileSchema.refine(
  (file) => {
    const allowedMimeTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    return allowedMimeTypes.includes(file.mimetype);
  },
  {
    message: 'File must be an image (JPEG, PNG, GIF, or WebP)',
  }
).refine(
  (file) => {
    const maxSize = 5 * 1024 * 1024; // 5MB
    return file.size <= maxSize;
  },
  {
    message: 'File size must not exceed 5MB',
  }
);

// Date range validation
export const dateRangeSchema = z
  .object({
    startDate: z.string().datetime().optional(),
    endDate: z.string().datetime().optional(),
  })
  .refine(
    (data) => {
      if (data.startDate && data.endDate) {
        return new Date(data.startDate) <= new Date(data.endDate);
      }
      return true;
    },
    {
      message: 'Start date must be before end date',
    }
  );

// Pagination schema
export const paginationSchema = z.object({
  page: z
    .string()
    .transform((val) => parseInt(val, 10))
    .pipe(z.number().int().positive())
    .default('1'),
  limit: z
    .string()
    .transform((val) => parseInt(val, 10))
    .pipe(z.number().int().positive().max(100))
    .default('10'),
});

// Sort schema
export const sortSchema = z
  .string()
  .regex(/^-?[a-zA-Z0-9_]+$/, 'Invalid sort format')
  .default('-createdAt');
```

### Server Entry Point

Create `src/server.ts`:

```typescript
import app from './app';
import { config } from './config/environment';
import { database } from './config/database';
import { logger } from './config/logger';
import {
  handleUnhandledRejection,
  handleUncaughtException,
} from './middleware/error.middleware';

// Handle uncaught exceptions
handleUncaughtException();

// Start server
const startServer = async () => {
  try {
    // Connect to database
    await database.connect();

    // Start listening
    const server = app.listen(config.port, () => {
      logger.info(`Server running on port ${config.port} in ${config.node_env} mode`);
    });

    // Handle unhandled rejections
    handleUnhandledRejection();

    // Graceful shutdown
    const gracefulShutdown = async (signal: string) => {
      logger.info(`${signal} received. Starting graceful shutdown...`);

      server.close(async () => {
        logger.info('HTTP server closed');

        try {
          await database.disconnect();
          logger.info('Database connection closed');
          process.exit(0);
        } catch (error) {
          logger.error('Error during shutdown:', error);
          process.exit(1);
        }
      });

      // Force shutdown after 30 seconds
      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 30000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

startServer();
```

