### File Upload Validation

Create `src/middleware/validators/file.validators.js`:

```javascript
const AppError = require('../../utils/AppError');

/**
 * Validate file upload
 */
exports.validateFileUpload = (options = {}) => {
  const {
    maxSize = 5 * 1024 * 1024, // 5MB default
    allowedTypes = ['image/jpeg', 'image/png', 'image/webp'],
    required = false
  } = options;

  return (req, res, next) => {
    if (!req.file && !req.files) {
      if (required) {
        return next(new AppError('File upload is required', 400));
      }
      return next();
    }

    const files = req.files || [req.file];

    for (const file of files) {
      // Check file size
      if (file.size > maxSize) {
        return next(new AppError(
          `File ${file.originalname} exceeds maximum size of ${maxSize / 1024 / 1024}MB`,
          400
        ));
      }

      // Check file type
      if (!allowedTypes.includes(file.mimetype)) {
        return next(new AppError(
          `File type ${file.mimetype} is not allowed. Allowed types: ${allowedTypes.join(', ')}`,
          400
        ));
      }
    }

    next();
  };
};

/**
 * Validate image dimensions
 */
exports.validateImageDimensions = (options = {}) => {
  const {
    minWidth = 100,
    minHeight = 100,
    maxWidth = 4000,
    maxHeight = 4000
  } = options;

  return async (req, res, next) => {
    if (!req.file && !req.files) {
      return next();
    }

    try {
      const sharp = require('sharp');
      const files = req.files || [req.file];

      for (const file of files) {
        const metadata = await sharp(file.buffer).metadata();

        if (metadata.width < minWidth || metadata.height < minHeight) {
          return next(new AppError(
            `Image dimensions must be at least ${minWidth}x${minHeight}px`,
            400
          ));
        }

        if (metadata.width > maxWidth || metadata.height > maxHeight) {
          return next(new AppError(
            `Image dimensions cannot exceed ${maxWidth}x${maxHeight}px`,
            400
          ));
        }
      }

      next();
    } catch (error) {
      next(new AppError('Invalid image file', 400));
    }
  };
};
