### Sanitization Middleware

Create `src/middleware/sanitize.js`:

```javascript
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

/**
 * Sanitize request data to prevent NoSQL injection and XSS
 */
exports.sanitizeInput = [
  // Prevent NoSQL injection
  mongoSanitize({
    replaceWith: '_',
    onSanitize: ({ req, key }) => {
      console.warn(`Sanitized key: ${key} in request`);
    }
  }),

  // Prevent XSS attacks
  xss()
];

/**
 * Custom sanitization for specific fields
 */
exports.sanitizeFields = (fields) => {
  return (req, res, next) => {
    fields.forEach(field => {
      if (req.body[field]) {
        // Remove HTML tags
        req.body[field] = req.body[field].replace(/<[^>]*>/g, '');

        // Trim whitespace
        req.body[field] = req.body[field].trim();

        // Remove multiple spaces
        req.body[field] = req.body[field].replace(/\s+/g, ' ');
      }
    });
    next();
  };
};
```

### Enhanced Error Handler for Validation

Update `src/middleware/errorHandler.js`:

```javascript
const logger = require('../utils/logger');
const config = require('../config');

const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  logger.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method
  });

  // Validation errors
  if (err.statusCode === 400 && err.errors) {
    return res.status(400).json({
      status: 'fail',
      message: err.message,
      errors: err.errors
    });
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => ({
      field: e.path,
      message: e.message
    }));

    return res.status(400).json({
      status: 'fail',
      message: 'Validation failed',
      errors
    });
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyPattern)[0];
    return res.status(400).json({
      status: 'fail',
      message: `${field} already exists`
    });
  }

  // Mongoose cast error
  if (err.name === 'CastError') {
    return res.status(400).json({
      status: 'fail',
      message: `Invalid ${err.path}: ${err.value}`
    });
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      status: 'fail',
      message: 'Invalid token'
    });
  }

  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({
      status: 'fail',
      message: 'Token expired'
    });
  }

  // Development error response
  if (config.env === 'development') {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
      stack: err.stack,
      error: err
    });
  }

  // Production error response
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  }

  // Programming or unknown errors
  return res.status(500).json({
    status: 'error',
    message: 'Something went wrong'
  });
};

module.exports = errorHandler;
```

### Update Routes with Validation

Update `src/routes/product.routes.js`:

```javascript
const express = require('express');
const productController = require('../controllers/product.controller');
const {
  createProductValidation,
  updateProductValidation,
  getProductValidation,
  listProductsValidation
} = require('../middleware/validators/product.validators');
const { validate } = require('../middleware/validators');
const { protect, restrictTo } = require('../middleware/auth');

const router = express.Router();

router
  .route('/')
  .get(listProductsValidation, validate, productController.getAllProducts)
  .post(
    protect,
    restrictTo('admin'),
    createProductValidation,
    validate,
    productController.createProduct
  );

router
  .route('/:id')
  .get(getProductValidation, validate, productController.getProductById)
  .patch(
    protect,
    restrictTo('admin'),
    updateProductValidation,
    validate,
    productController.updateProduct
  )
  .delete(
    protect,
    restrictTo('admin'),
    getProductValidation,
    validate,
    productController.deleteProduct
  );

module.exports = router;
```

