### Auth Validators

Create `src/validators/auth.validator.ts`:

```typescript
import { z } from 'zod';

const passwordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
  .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
  .regex(/[0-9]/, 'Password must contain at least one number')
  .regex(/[^A-Za-z0-9]/, 'Password must contain at least one special character');

const emailSchema = z
  .string()
  .email('Invalid email format')
  .toLowerCase()
  .trim();

export const authValidators = {
  register: z.object({
    body: z.object({
      email: emailSchema,
      password: passwordSchema,
      firstName: z
        .string()
        .min(1, 'First name is required')
        .max(50)
        .trim(),
      lastName: z
        .string()
        .min(1, 'Last name is required')
        .max(50)
        .trim(),
    }),
  }),

  login: z.object({
    body: z.object({
      email: emailSchema,
      password: z.string().min(1, 'Password is required'),
    }),
  }),

  refreshToken: z.object({
    body: z.object({
      refreshToken: z.string().min(1, 'Refresh token is required'),
    }),
  }),

  forgotPassword: z.object({
    body: z.object({
      email: emailSchema,
    }),
  }),

  resetPassword: z.object({
    params: z.object({
      token: z.string().min(1, 'Reset token is required'),
    }),
    body: z.object({
      password: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.password === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }),
  }),

  verifyEmail: z.object({
    params: z.object({
      token: z.string().min(1, 'Verification token is required'),
    }),
  }),

  changePassword: z.object({
    body: z.object({
      currentPassword: z.string().min(1, 'Current password is required'),
      newPassword: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.newPassword === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }).refine((data) => data.currentPassword !== data.newPassword, {
      message: 'New password must be different from current password',
      path: ['newPassword'],
    }),
  }),
};
```

### Product Validators

Create `src/validators/product.validator.ts`:

```typescript
import { z } from 'zod';

const mongoIdSchema = z
  .string()
  .regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format');

export const productValidators = {
  createProduct: z.object({
    body: z.object({
      name: z
        .string()
        .min(1, 'Product name is required')
        .max(200, 'Product name cannot exceed 200 characters')
        .trim(),
      description: z
        .string()
        .min(1, 'Description is required')
        .max(2000, 'Description cannot exceed 2000 characters'),
      price: z
        .number()
        .positive('Price must be positive')
        .max(1000000, 'Price cannot exceed 1,000,000'),
      category: z.enum([
        'electronics',
        'clothing',
        'books',
        'home',
        'sports',
        'other',
      ]),
      stock: z
        .number()
        .int('Stock must be an integer')
        .min(0, 'Stock cannot be negative'),
      images: z
        .array(z.string().url('Invalid image URL'))
        .max(5, 'Cannot have more than 5 images')
        .optional(),
    }),
  }),

  updateProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
    body: z.object({
      name: z
        .string()
        .min(1)
        .max(200)
        .trim()
        .optional(),
      description: z
        .string()
        .min(1)
        .max(2000)
        .optional(),
      price: z
        .number()
        .positive()
        .max(1000000)
        .optional(),
      category: z
        .enum(['electronics', 'clothing', 'books', 'home', 'sports', 'other'])
        .optional(),
      stock: z
        .number()
        .int()
        .min(0)
        .optional(),
      images: z
        .array(z.string().url())
        .max(5)
        .optional(),
      isActive: z.boolean().optional(),
    }),
  }),

  getProductById: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  deleteProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  getProducts: z.object({
    query: z.object({
      page: z
        .string()
        .regex(/^\d+$/)
        .transform(Number)
        .pipe(z.number().int().positive())
        .optional()
        .default('1'),
      limit: z
        .string()
        .regex(/^\d+$/)
        .transform(Number)
        .pipe(z.number().int().positive().max(100))
        .optional()
        .default('10'),
      category: z
        .enum(['electronics', 'clothing', 'books', 'home', 'sports', 'other'])
        .optional(),
      minPrice: z
        .string()
        .regex(/^\d+(\.\d+)?$/)
        .transform(Number)
        .pipe(z.number().min(0))
        .optional(),
      maxPrice: z
        .string()
        .regex(/^\d+(\.\d+)?$/)
        .transform(Number)
        .pipe(z.number().min(0))
        .optional(),
      search: z.string().trim().optional(),
      sortBy: z
        .enum(['price', 'createdAt', 'name', 'ratings'])
        .optional()
        .default('createdAt'),
      sortOrder: z
        .enum(['asc', 'desc'])
        .optional()
        .default('desc'),
    }).refine(
      (data) => {
        if (data.minPrice && data.maxPrice) {
          return data.minPrice <= data.maxPrice;
        }
        return true;
      },
      {
        message: 'minPrice must be less than or equal to maxPrice',
        path: ['minPrice'],
      }
    ),
  }),

  getProductsByCategory: z.object({
    params: z.object({
      category: z.enum([
        'electronics',
        'clothing',
        'books',
        'home',
        'sports',
        'other',
      ]),
    }),
    query: z.object({
      page: z
        .string()
        .regex(/^\d+$/)
        .transform(Number)
        .optional()
        .default('1'),
      limit: z
        .string()
        .regex(/^\d+$/)
        .transform(Number)
        .optional()
        .default('10'),
    }),
  }),
};
