### Custom Validation Helpers

Create `src/validators/helpers.ts`:

```typescript
import { z } from 'zod';

// Phone number validation
export const phoneSchema = z
  .string()
  .regex(
    /^\+?[1-9]\d{1,14}$/,
    'Invalid phone number format (E.164 format required)'
  );

// URL validation with specific domains
export const urlSchema = (allowedDomains?: string[]) => {
  let schema = z.string().url('Invalid URL format');

  if (allowedDomains) {
    schema = schema.refine(
      (url) => {
        try {
          const domain = new URL(url).hostname;
          return allowedDomains.some((allowed) => domain.includes(allowed));
        } catch {
          return false;
        }
      },
      {
        message: `URL must be from allowed domains: ${allowedDomains.join(', ')}`,
      }
    );
  }

  return schema;
};

// Date validation
export const dateSchema = z.string().refine(
  (date) => {
    const parsed = Date.parse(date);
    return !isNaN(parsed);
  },
  {
    message: 'Invalid date format',
  }
);

// Future date validation
export const futureDateSchema = dateSchema.refine(
  (date) => {
    return new Date(date) > new Date();
  },
  {
    message: 'Date must be in the future',
  }
);

// Past date validation
export const pastDateSchema = dateSchema.refine(
  (date) => {
    return new Date(date) < new Date();
  },
  {
    message: 'Date must be in the past',
  }
);

// File upload validation
export const fileSchema = z.object({
  fieldname: z.string(),
  originalname: z.string(),
  encoding: z.string(),
  mimetype: z.string(),
  size: z.number(),
  buffer: z.instanceof(Buffer),
});

export const imageFileSchema = fileSchema.refine(
  (file) => {
    const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    return allowedTypes.includes(file.mimetype);
  },
  {
    message: 'File must be an image (JPEG, PNG, GIF, or WebP)',
  }
).refine(
  (file) => {
    const maxSize = 5 * 1024 * 1024; // 5MB
    return file.size <= maxSize;
  },
  {
    message: 'File size must not exceed 5MB',
  }
);

// Pagination schema
export const paginationSchema = z.object({
  page: z
    .string()
    .regex(/^\d+$/)
    .transform(Number)
    .pipe(z.number().int().positive())
    .optional()
    .default('1'),
  limit: z
    .string()
    .regex(/^\d+$/)
    .transform(Number)
    .pipe(z.number().int().positive().max(100))
    .optional()
    .default('10'),
});

// Sort schema
export const sortSchema = (allowedFields: string[]) =>
  z.object({
    sortBy: z.enum(allowedFields as [string, ...string[]]).optional(),
    sortOrder: z.enum(['asc', 'desc']).optional().default('desc'),
  });
```

### Server Entry Point

Create `src/server.ts`:

```typescript
import app from './app';
import { config } from './config/environment';
import { database } from './config/database';
import { logger } from './config/logger';

async function startServer() {
  try {
    // Connect to database
    await database.connect();

    // Start server
    const server = app.listen(config.port, () => {
      logger.info(`Server running on port ${config.port} in ${config.node_env} mode`);
      logger.info(`API available at http://localhost:${config.port}/api/${config.api_version}`);
    });

    // Graceful shutdown
    const gracefulShutdown = async (signal: string) => {
      logger.info(`${signal} received, shutting down gracefully`);

      server.close(async () => {
        logger.info('HTTP server closed');

        await database.disconnect();

        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    // Handle unhandled rejections
    process.on('unhandledRejection', (reason: Error) => {
      logger.error('Unhandled Rejection:', reason);
      throw reason;
    });

    // Handle uncaught exceptions
    process.on('uncaughtException', (error: Error) => {
      logger.error('Uncaught Exception:', error);
      process.exit(1);
    });
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

startServer();
```

