export const validateParams = (schema: AnySchema) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      req.params = await schema.validate(req.params, {
        abortEarly: false,
        stripUnknown: true
      });
      next();
    } catch (error) {
      handleValidationError(error, res, next);
    }
  };
};

function handleValidationError(
  error: any,
  res: Response,
  next: NextFunction
) {
  if (error instanceof YupValidationError) {
    const errors: ValidationErrorDetail[] = error.inner.map((err) => ({
      field: err.path || 'unknown',
      message: err.message
    }));

    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors
    });
  }
  next(error);
}
