### Applying Validation to Routes

Update `src/routes/userRoutes.ts`:

```typescript
import { Router } from 'express';
import userController from '../controllers/userController';
import { authenticate, authorize } from '../middleware/auth';
import { validate } from '../middleware/validate';
import {
  createUserSchema,
  updateUserSchema,
  getUserSchema,
  listUsersSchema,
  deleteUserSchema
} from '../validations/userValidation';

const router = Router();

router.use(authenticate);

router.get(
  '/',
  validate(listUsersSchema),
  userController.getAllUsers
);

router.get(
  '/:id',
  validate(getUserSchema),
  userController.getUserById
);

router.post(
  '/',
  authorize('ADMIN'),
  validate(createUserSchema),
  userController.createUser
);

router.put(
  '/:id',
  authorize('ADMIN'),
  validate(updateUserSchema),
  userController.updateUser
);

router.delete(
  '/:id',
  authorize('ADMIN'),
  validate(deleteUserSchema),
  userController.deleteUser
);

export default router;
```

### Testing Validation

Create `tests/validation/userValidation.test.ts`:

```typescript
import request from 'supertest';
import app from '../../src/server';

describe('User Validation', () => {
  let authToken: string;

  beforeAll(async () => {
    // Login to get auth token
    const response = await request(app)
      .post('/api/v1/auth/login')
      .send({
        email: 'admin@example.com',
        password: 'admin123'
      });

    authToken = response.body.data.accessToken;
  });

  describe('POST /api/v1/users', () => {
    it('should reject invalid email', async () => {
      const response = await request(app)
        .post('/api/v1/users')
        .set('Authorization', `Bearer ${authToken}`)
        .send({
          email: 'invalid-email',
          username: 'testuser',
          password: 'Password123!',
          firstName: 'Test',
          lastName: 'User'
        })
        .expect(400);

      expect(response.body.success).toBe(false);
      expect(response.body.errors).toBeDefined();
      expect(response.body.errors[0].field).toBe('body.email');
    });

    it('should reject weak password', async () => {
      const response = await request(app)
        .post('/api/v1/users')
        .set('Authorization', `Bearer ${authToken}`)
        .send({
          email: 'test@example.com',
          username: 'testuser',
          password: 'weak',
          firstName: 'Test',
          lastName: 'User'
        })
        .expect(400);

      expect(response.body.errors[0].field).toBe('body.password');
    });

    it('should accept valid user data', async () => {
      const response = await request(app)
        .post('/api/v1/users')
        .set('Authorization', `Bearer ${authToken}`)
        .send({
          email: 'valid@example.com',
          username: 'validuser',
          password: 'ValidPass123!',
          firstName: 'Valid',
          lastName: 'User'
        })
        .expect(201);

      expect(response.body.success).toBe(true);
    });
  });

  describe('GET /api/v1/users', () => {
    it('should validate pagination parameters', async () => {
      const response = await request(app)
        .get('/api/v1/users?page=0&limit=200')
        .set('Authorization', `Bearer ${authToken}`)
        .expect(400);

      expect(response.body.errors).toBeDefined();
    });

    it('should accept valid query parameters', async () => {
      const response = await request(app)
        .get('/api/v1/users?page=1&limit=10&sortBy=email')
        .set('Authorization', `Bearer ${authToken}`)
        .expect(200);

      expect(response.body.success).toBe(true);
    });
  });
});
```

### Key Takeaways

- Validate all user input at the API boundary
- Use schema validation libraries like Yup for consistency
- Create reusable validation schemas organized by resource
- Provide clear, actionable error messages
- Validate request body, query parameters, and URL parameters
- Strip unknown fields to prevent mass assignment vulnerabilities
- Transform and normalize data during validation
- Implement custom validation methods for domain-specific rules
- Validate file uploads separately with size and type checks
- Test validation rules thoroughly
- Log validation failures for security monitoring
- Use TypeScript types generated from validation schemas

