{"runType":"STIGMERGY","runId":"600dbdb3-921b-4316-a4a9-d7bc5489aaa9-STIGMERGY-3","contentTransferTokens":3710,"mechanismOverheadTokens":16465,"coordinationInstructionsTokens":4874,"taskReasoningTokens":18452,"systemIdentityTokens":0,"interAgentTokens":25049,"agentAutonomousTokens":18452,"totalTokens":43501,"cachedTokens":0,"effectiveTokens":43501,"cacheHitRate":0,"wallClockMs":201711,"agentCount":6,"apiCallCount":18,"success":true,"output":"## Complete 6-Section Guide to Building a Production-Ready REST API

### Section 6: Validation

Input validation is critical for API security, data integrity, and user experience. Proper validation prevents malicious data, ensures data consistency, and provides clear feedback to API consumers.

#### Why Validation Matters

- **Security**: Prevents injection attacks, XSS, and malformed data
- **Data Integrity**: Ensures only valid data enters your database
- **User Experience**: Provides clear, actionable error messages
- **Documentation**: Validation schemas serve as API contracts

#### Validation Strategies

**1. Schema-Based Validation**

Use validation libraries to define data schemas:

```javascript
// Using Joi
const Joi = require('joi');

const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/).required(),
  age: Joi.number().integer().min(18).max(120),
  role: Joi.string().valid('user', 'admin', 'moderator').default('user')
});

// Using Zod (TypeScript-friendly)
const { z } = require('zod');

const userSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8).regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/),
  age: z.number().int().min(18).max(120).optional(),
  role: z.enum(['user', 'admin', 'moderator']).default('user')
});
```

**2. Validation Middleware**

Create reusable validation middleware:

```javascript
const validate = (schema) => {
  return async (req, res, next) => {
    try {
      // Validate request body
      const validated = await schema.validateAsync(req.body, {
        abortEarly: false, // Return all errors
        stripUnknown: true // Remove unknown fields
      });

      req.body = validated;
      next();
    } catch (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));

      return res.status(400).json({
        error: 'Validation failed',
        details: errors
      });
    }
  };
};

// Apply to routes
router.post('/users', validate(userSchema), createUser);
router.put('/users/:id', validate(updateUserSchema), updateUser);
```

**3. Multi-Layer Validation**

Validate different parts of the request:

```javascript
const validateRequest = (schemas) => {
  return async (req, res, next) => {
    try {
      if (schemas.params) {
        req.params = await schemas.params.validateAsync(req.params);
      }
      if (schemas.query) {
        req.query = await schemas.query.validateAsync(req.query);
      }
      if (schemas.body) {
        req.body = await schemas.body.validateAsync(req.body);
      }
      next();
    } catch (error) {
      return res.status(400).json({
        error: 'Validation failed',
        message: error.message
      });
    }
  };
};

// Usage
router.get('/users/:id/posts', validateRequest({
  params: Joi.object({
    id: Joi.string().uuid().required()
  }),
  query: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    limit: Joi.number().integer().min(1).max(100).default(20),
    sort: Joi.string().valid('created', 'updated', 'title')
  })
}), getUserPosts);
```

**4. Custom Validators**

Implement business logic validation:

```javascript
const userSchema = Joi.object({
  email: Joi.string().email().required()
    .external(async (value) => {
      const exists = await User.findOne({ email: value });
      if (exists) {
        throw new Error('Email already registered');
      }
      return value;
    }),
  username: Joi.string().alphanum().min(3).max(30).required()
    .custom((value, helpers) => {
      if (value.toLowerCase().includes('admin')) {
        return helpers.error('any.invalid');
      }
      return value;
    }),
  birthdate: Joi.date().max('now').required()
    .custom((value, helpers) => {
      const age = (Date.now() - value.getTime()) / (365.25 * 24 * 60 * 60 * 1000);
      if (age < 18) {
        return helpers.message('Must be at least 18 years old');
      }
      return value;
    })
});
```

**5. Sanitization**

Clean and normalize input data:

```javascript
const validator = require('validator');

const sanitizeInput = (req, res, next) => {
  // Trim strings
  Object.keys(req.body).forEach(key => {
    if (typeof req.body[key] === 'string') {
      req.body[key] = req.body[key].trim();
    }
  });

  // Sanitize specific fields
  if (req.body.email) {
    req.body.email = validator.normalizeEmail(req.body.email);
  }

  if (req.body.url) {
    req.body.url = validator.escape(req.body.url);
  }

  next();
};

router.post('/users', sanitizeInput, validate(userSchema), createUser);
```

**6. File Upload Validation**

Validate uploaded files:

```javascript
const multer = require('multer');

const fileFilter = (req, file, cb) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/gif'];

  if (!allowedTypes.includes(file.mimetype)) {
    return cb(new Error('Invalid file type. Only JPEG, PNG, and GIF allowed.'), false);
  }

  cb(null, true);
};

const upload = multer({
  storage: multer.diskStorage({
    destination: 'uploads/',
    filename: (req, file, cb) => {
      const uniqueName = `${Date.now()}-${Math.round(Math.random() * 1E9)}`;
      cb(null, `${uniqueName}-${file.originalname}`);
    }
  }),
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB
    files: 1
  },
  fileFilter
});

router.post('/upload', upload.single('avatar'), (req, res) => {
  res.json({ file: req.file });
});
```

**7. Error Response Format**

Provide consistent, helpful error messages:

```javascript
class ValidationError extends Error {
  constructor(errors) {
    super('Validation failed');
    this.name = 'ValidationError';
    this.statusCode = 400;
    this.errors = errors;
  }
}

// Error handler middleware
app.use((err, req, res, next) => {
  if (err instanceof ValidationError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        type: 'ValidationError',
        message: err.message,
        fields: err.errors
      }
    });
  }

  // Handle other errors
  next(err);
});
```

**8. Production Best Practices**

```javascript
// Rate limiting for validation-heavy endpoints
const rateLimit = require('express-rate-limit');

const validationLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many validation attempts'
});

// Comprehensive validation setup
const productSchema = Joi.object({
  name: Joi.string().min(3).max(100).required(),
  description: Joi.string().max(1000),
  price: Joi.number().positive().precision(2).required(),
  category: Joi.string().valid('electronics', 'clothing', 'books').required(),
  tags: Joi.array().items(Joi.string()).max(10),
  inStock: Joi.boolean().default(true),
  metadata: Joi.object().pattern(
    Joi.string(),
    Joi.alternatives().try(Joi.string(), Joi.number(), Joi.boolean())
  )
});

router.post('/products', 
  validationLimiter,
  sanitizeInput,
  validate(productSchema),
  createProduct
);
```

**Key Takeaways:**

- Always validate on the server side, never trust client validation alone
- Use schema-based validation libraries for consistency
- Provide clear, actionable error messages
- Sanitize input to prevent injection attacks
- Validate all request components (body, params, query, headers)
- Implement custom validators for business logic
- Use TypeScript or schema validation for type safety
- Document validation rules as part of your API documentation

