## Section 6: Validation

### Validation Schemas

**src/validators/auth.validator.ts:**
```typescript
import Joi from 'joi';

const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;

export class AuthValidator {
  static register = Joi.object({
    body: Joi.object({
      email: Joi.string()
        .email()
        .lowercase()
        .required()
        .messages({
          'string.email': 'Please provide a valid email address',
          'any.required': 'Email is required',
        }),
      username: Joi.string()
        .alphanum()
        .min(3)
        .max(30)
        .required()
        .messages({
          'string.alphanum': 'Username must contain only letters and numbers',
          'string.min': 'Username must be at least 3 characters long',
          'string.max': 'Username cannot exceed 30 characters',
          'any.required': 'Username is required',
        }),
      password: Joi.string()
        .pattern(passwordRegex)
        .required()
        .messages({
          'string.pattern.base':
            'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character',
          'any.required': 'Password is required',
        }),
      confirmPassword: Joi.string()
        .valid(Joi.ref('password'))
        .required()
        .messages({
          'any.only': 'Passwords do not match',
          'any.required': 'Password confirmation is required',
        }),
      firstName: Joi.string().min(2).max(50).optional(),
      lastName: Joi.string().min(2).max(50).optional(),
    }),
  });

  static login = Joi.object({
    body: Joi.object({
      identifier: Joi.string().required().messages({
        'any.required': 'Email or username is required',
      }),
      password: Joi.string().required().messages({
        'any.required': 'Password is required',
      }),
    }),
  });

  static refreshToken = Joi.object({
    body: Joi.object({
      refreshToken: Joi.string().required().messages({
        'any.required': 'Refresh token is required',
      }),
    }),
  });

  static changePassword = Joi.object({
    body: Joi.object({
      currentPassword: Joi.string().required().messages({
        'any.required': 'Current password is required',
      }),
      newPassword: Joi.string()
        .pattern(passwordRegex)
        .required()
        .messages({
          'string.pattern.base':
            'New password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character',
          'any.required': 'New password is required',
        }),
      confirmPassword: Joi.string()
        .valid(Joi.ref('newPassword'))
        .required()
        .messages({
          'any.only': 'Passwords do not match',
          'any.required': 'Password confirmation is required',
        }),
    }),
  });

  static forgotPassword = Joi.object({
    body: Joi.object({
      email: Joi.string().email().required().messages({
        'string.email': 'Please provide a valid email address',
        'any.required': 'Email is required',
      }),
    }),
  });

  static resetPassword = Joi.object({
    params: Joi.object({
      token: Joi.string().required(),
    }),
    body: Joi.object({
      password: Joi.string()
        .pattern(passwordRegex)
        .required()
        .messages({
          'string.pattern.base':
            'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character',
          'any.required': 'Password is required',
        }),
      confirmPassword: Joi.string()
        .valid(Joi.ref('password'))
        .required()
        .messages({
          'any.only': 'Passwords do not match',
          'any.required': 'Password confirmation is required',
        }),
    }),
  });
}
```

**src/validators/user.validator.ts:**
```typescript
import Joi from 'joi';

export class UserValidator {
  static getUserById = Joi.object({
    params: Joi.object({
      id: Joi.string().uuid().required().messages({
        'string.guid': 'Invalid user ID format',
        'any.required': 'User ID is required',
      }),
    }),
  });

  static updateUser = Joi.object({
    params: Joi.object({
      id: Joi.string().uuid().required(),
    }),
    body: Joi.object({
      firstName: Joi.string().min(2).max(50).optional(),
      lastName: Joi.string().min(2).max(50).optional(),
      username: Joi.string().alphanum().min(3).max(30).optional(),
      email: Joi.string().email().optional(),
      avatar: Joi.string().uri().optional(),
    }).min(1).messages({
      'object.min': 'At least one field must be provided for update',
    }),
  });

  static deleteUser = Joi.object({
    params: Joi.object({
      id: Joi.string().uuid().required(),
    }),
  });

  static updateUserRole = Joi.object({
    params: Joi.object({
      id: Joi.string().uuid().required(),
    }),
    body: Joi.object({
      role: Joi.string().valid('USER', 'ADMIN', 'MODERATOR').required().messages({
        'any.only': 'Role must be one of: USER, ADMIN, MODERATOR',
        'any.required': 'Role is required',
      }),
    }),
  });

  static uploadAvatar = Joi.object({
    params: Joi.object({
      id: Joi.string().uuid().required(),
    }),
  });

  static listUsers = Joi.object({
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      sortBy: Joi.string().valid('createdAt', 'email', 'username').default('createdAt'),
      sortOrder: Joi.string().valid('asc', 'desc').default('desc'),
      search: Joi.string().optional(),
      role: Joi.string().valid('USER', 'ADMIN', 'MODERATOR').optional(),
      isActive: Joi.boolean().optional(),
    }),
  });
}
```

### Custom Validation Rules

**src/validators/custom.validator.ts:**
```typescript
import Joi from 'joi';

// Custom validator for phone numbers
export const phoneValidator = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Please provide a valid phone number',
  });

// Custom validator for URLs
export const urlValidator = Joi.string()
  .uri({ scheme: ['http', 'https'] })
  .messages({
    'string.uri': 'Please provide a valid URL',
  });

// Custom validator for dates
export const dateValidator = Joi.date()
  .iso()
  .messages({
    'date.format': 'Date must be in ISO 8601 format',
  });

// Custom validator for file uploads
export const fileValidator = Joi.object({
  fieldname: Joi.string().required(),
  originalname: Joi.string().required(),
  encoding: Joi.string().required(),
  mimetype: Joi.string()
    .valid('image/jpeg', 'image/png', 'image/gif', 'image/webp')
    .required()
    .messages({
      'any.only': 'Only JPEG, PNG, GIF, and WebP images are allowed',
    }),
  size: Joi.number()
    .max(5 * 1024 * 1024) // 5MB
    .required()
    .messages({
      'number.max': 'File size cannot exceed 5MB',
    }),
});

// Custom validator for pagination
export const paginationValidator = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  sortBy: Joi.string().optional(),
  sortOrder: Joi.string().valid('asc', 'desc').default('desc'),
});

// Custom validator for search queries
export const searchValidator = Joi.object({
  q: Joi.string().min(2).max(100).required().messages({
    'string.min': 'Search query must be at least 2 characters long',
    'string.max': 'Search query cannot exceed 100 characters',
    'any.required': 'Search query is required',
  }),
  fields: Joi.array().items(Joi.string()).optional(),
  ...paginationValidator.describe().keys,
});
