### Sanitization

**src/utils/sanitize.ts:**
```typescript
import validator from 'validator';
import xss from 'xss';

export class Sanitizer {
  static sanitizeString(input: string): string {
    // Remove XSS
    let sanitized = xss(input);

    // Trim whitespace
    sanitized = validator.trim(sanitized);

    // Escape HTML
    sanitized = validator.escape(sanitized);

    return sanitized;
  }

  static sanitizeEmail(email: string): string {
    return validator.normalizeEmail(email) || email;
  }

  static sanitizeUrl(url: string): string {
    if (!validator.isURL(url)) {
      throw new Error('Invalid URL');
    }
    return url;
  }

  static sanitizeObject<T extends Record<string, any>>(obj: T): T {
    const sanitized = {} as T;

    for (const [key, value] of Object.entries(obj)) {
      if (typeof value === 'string') {
        sanitized[key as keyof T] = this.sanitizeString(value) as T[keyof T];
      } else if (typeof value === 'object' && value !== null) {
        sanitized[key as keyof T] = this.sanitizeObject(value);
      } else {
        sanitized[key as keyof T] = value;
      }
    }

    return sanitized;
  }

  static removeNullUndefined<T extends Record<string, any>>(obj: T): Partial<T> {
    const cleaned: Partial<T> = {};

    for (const [key, value] of Object.entries(obj)) {
      if (value !== null && value !== undefined) {
        cleaned[key as keyof T] = value;
      }
    }

    return cleaned;
  }
}
```

