**src/app.ts:**
```typescript
import express, { Application } from 'express';
import { helmetConfig, corsConfig, sanitizeData, preventHPP } from './middleware/security.middleware';
import { compressionConfig } from './middleware/compression.middleware';
import { requestLogger } from './middleware/requestLogger.middleware';
import { errorConverter, errorHandler, notFoundHandler } from './middleware/error.middleware';
import { apiLimiter } from './middleware/rateLimiter.middleware';
import routes from './routes';

const app: Application = express();

// Security middleware
app.use(helmetConfig);
app.use(corsConfig);
app.use(sanitizeData);
app.use(preventHPP);

// Body parsing middleware
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Compression
app.use(compressionConfig);

// Logging
app.use(requestLogger);

// Rate limiting
app.use('/api/', apiLimiter);

// Routes
app.use('/api', routes);

// Error handling
app.use(notFoundHandler);
app.use(errorConverter);
app.use(errorHandler);

export default app;
```

