import { BusinessRuleValidator } from '../validators/business-rules';
import { DataTransformer } from '../utils/transformers';

export class UserController {
  async createUser(req: Request, res: Response, next: NextFunction) {
    try {
      const { email, name, password, phone } = req.body;

      // Business rule validation
      await BusinessRuleValidator.validateUniqueEmail(email);

      // Transform data
      const normalizedEmail = DataTransformer.normalizeEmail(email);
      const normalizedPhone = phone
        ? DataTransformer.normalizePhone(phone)
        : undefined;

      const user = await userService.createUser({
        email: normalizedEmail,
        name: name.trim(),
        password,
        phone: normalizedPhone,
      });

      res.status(201).json({
        success: true,
        data: { user },
      });
    } catch (error) {
      next(error);
    }
  }

  async updateUser(req: Request, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const updates = req.body;

      // Validate email uniqueness if email is being updated
      if (updates.email) {
        await BusinessRuleValidator.validateUniqueEmail(updates.email, id);
        updates.email = DataTransformer.normalizeEmail(updates.email);
      }

      // Normalize phone if provided
      if (updates.phone) {
        updates.phone = DataTransformer.normalizePhone(updates.phone);
      }

      const user = await userService.updateUser(id, updates);

      res.json({
        success: true,
        data: { user },
      });
    } catch (error) {
      next(error);
    }
  }
}
