```typescript
import { BusinessRuleValidator } from '../validators/business-rules';
import { DataTransformer } from '../utils/transformers';

export class PostController {
  async createPost(req: Request, res: Response, next: NextFunction) {
    try {
      const { title, content, categoryId, tags, published } = req.body;
      const userId = req.user!.userId;

      // Validate category exists
      if (categoryId) {
        await BusinessRuleValidator.validateCategoryExists(categoryId);
      }

      // Transform data
      const slug = DataTransformer.slugify(title);
      const normalizedTags = DataTransformer.normalizeTags(tags || []);
      const excerpt = DataTransformer.truncate(content, 200);

      const post = await postService.createPost({
        title: title.trim(),
        content,
        slug,
        excerpt,
        authorId: userId,
        categoryId,
        tags: normalizedTags,
        published,
      });

      res.status(201).json({
        success: true,
        data: { post },
      });
    } catch (error) {
      next(error);
    }
  }

  async publishPost(req: Request, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const userId = req.user!.userId;

      // Validate ownership
      await BusinessRuleValidator.validatePostOwnership(id, userId);

      // Validate can publish
      await BusinessRuleValidator.validateCanPublish(id);

      const post = await postService.publishPost(id);

      res.json({
        success: true,
        data: { post },
        message: 'Post published successfully',
      });
    } catch (error) {
      next(error);
    }
  }
}
