### Section 6: Validation

Input validation is critical for API security, data integrity, and providing clear feedback to clients. Proper validation prevents malformed data from entering your system and protects against injection attacks.

#### Why Validation Matters

- **Security**: Prevents SQL injection, XSS, and other attacks
- **Data Integrity**: Ensures only valid data reaches your database
- **User Experience**: Provides clear, actionable error messages
- **Documentation**: Validation schemas serve as API contracts

#### Validation Strategies

**1. Schema-Based Validation**

Use libraries like Joi, Yup, or Zod for declarative validation:

```javascript
const Joi = require('joi');

const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).required(),
  age: Joi.number().integer().min(18).max(120),
  role: Joi.string().valid('user', 'admin', 'moderator')
});

// Validation middleware
const validateUser = (req, res, next) => {
  const { error, value } = userSchema.validate(req.body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message
      }))
    });
  }

  req.validatedData = value;
  next();
};
```

**2. Request Validation Layers**

Validate different parts of the request:

```javascript
const { body, param, query, validationResult } = require('express-validator');

router.post('/users/:id/posts',
  // Validate URL parameters
  param('id').isInt().toInt(),

  // Validate query strings
  query('published').optional().isBoolean().toBoolean(),

  // Validate request body
  body('title').trim().isLength({ min: 3, max: 200 }),
  body('content').trim().notEmpty(),
  body('tags').isArray().optional(),
  body('tags.*').isString().trim(),

  // Check validation results
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  },

  createPost
);
```

**3. Custom Validators**

Create reusable custom validation logic:

```javascript
const customValidators = {
  isStrongPassword: (value) => {
    const hasUpperCase = /[A-Z]/.test(value);
    const hasLowerCase = /[a-z]/.test(value);
    const hasNumbers = /\d/.test(value);
    const hasSpecialChar = /[!@#$%^&*]/.test(value);

    return hasUpperCase && hasLowerCase && hasNumbers && hasSpecialChar;
  },

  isValidSlug: (value) => {
    return /^[a-z0-9-]+$/.test(value);
  },

  isUniqueEmail: async (email) => {
    const user = await User.findOne({ email });
    return !user;
  }
};

// Usage
body('password')
  .custom(customValidators.isStrongPassword)
  .withMessage('Password must contain uppercase, lowercase, number, and special character');
```

**4. Sanitization**

Clean input data before processing:

```javascript
const sanitize = {
  // Remove HTML tags
  stripHtml: (str) => str.replace(/<[^>]*>/g, ''),

  // Normalize whitespace
  normalizeSpace: (str) => str.trim().replace(/\s+/g, ' '),

  // Escape special characters
  escapeHtml: (str) => {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#x27;'
    };
    return str.replace(/[&<>"']/g, (m) => map[m]);
  }
};

// Sanitization middleware
const sanitizeInput = (req, res, next) => {
  if (req.body.bio) {
    req.body.bio = sanitize.stripHtml(req.body.bio);
    req.body.bio = sanitize.normalizeSpace(req.body.bio);
  }
  next();
};
```

**5. File Upload Validation**

Validate uploaded files for security:

```javascript
const multer = require('multer');

const fileFilter = (req, file, cb) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/gif'];
  const allowedExtensions = ['.jpg', '.jpeg', '.png', '.gif'];

  const ext = path.extname(file.originalname).toLowerCase();

  if (allowedTypes.includes(file.mimetype) && allowedExtensions.includes(ext)) {
    cb(null, true);
  } else {
    cb(new Error('Invalid file type. Only JPEG, PNG, and GIF allowed.'));
  }
};

const upload = multer({
  storage: multer.diskStorage({
    destination: 'uploads/',
    filename: (req, file, cb) => {
      const uniqueName = `${Date.now()}-${crypto.randomBytes(6).toString('hex')}${path.extname(file.originalname)}`;
      cb(null, uniqueName);
    }
  }),
  fileFilter,
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB
    files: 1
  }
});
```

**6. Business Logic Validation**

Validate beyond data types:

```javascript
const validateBusinessRules = async (req, res, next) => {
  try {
    const { userId, productId, quantity } = req.body;

    // Check product availability
    const product = await Product.findById(productId);
    if (!product) {
      return res.status(404).json({ error: 'Product not found' });
    }

    if (product.stock < quantity) {
      return res.status(400).json({ 
        error: 'Insufficient stock',
        available: product.stock,
        requested: quantity
      });
    }

    // Check user purchase limits
    const userOrders = await Order.countDocuments({
      userId,
      createdAt: { $gte: new Date(Date.now() - 24 * 60 * 60 * 1000) }
    });

    if (userOrders >= 10) {
      return res.status(429).json({ 
        error: 'Daily purchase limit reached' 
      });
    }

    next();
  } catch (error) {
    next(error);
  }
};
```

**7. Validation Error Handling**

Provide consistent, helpful error responses:

```javascript
class ValidationError extends Error {
  constructor(errors) {
    super('Validation failed');
    this.name = 'ValidationError';
    this.statusCode = 400;
    this.errors = errors;
  }
}

// Global validation error handler
app.use((err, req, res, next) => {
  if (err instanceof ValidationError) {
    return res.status(err.statusCode).json({
      error: err.message,
      details: err.errors,
      timestamp: new Date().toISOString(),
      path: req.path
    });
  }

  // Handle Joi validation errors
  if (err.isJoi) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details.map(d => ({
        field: d.path.join('.'),
        message: d.message,
        type: d.type
      }))
    });
  }

  next(err);
});
```

**8. Production Best Practices**

- **Validate early**: Check inputs at API boundaries before processing
- **Fail fast**: Return validation errors immediately
- **Be specific**: Provide clear error messages indicating what's wrong
- **Whitelist approach**: Define what's allowed, reject everything else
- **Rate limiting**: Prevent validation abuse with rate limits
- **Log validation failures**: Track patterns for security monitoring
- **Version schemas**: Maintain validation schemas alongside API versions
- **Test thoroughly**: Include validation tests in your test suite

**Example: Complete Validation Pipeline**

```javascript
router.post('/api/v1/articles',
  authenticate,
  rateLimit({ windowMs: 15 * 60 * 1000, max: 10 }),

  // Schema validation
  validateSchema(articleSchema),

  // Sanitization
  sanitizeInput,

  // Business rules
  async (req, res, next) => {
    const canPublish = await checkPublishPermissions(req.user, req.body);
    if (!canPublish) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  },

  // Controller
  createArticle
);
```

#### Testing Validation

```javascript
describe('Article Validation', () => {
  it('should reject articles with short titles', async () => {
    const response = await request(app)
      .post('/api/v1/articles')
      .send({ title: 'Hi', content: 'Valid content' })
      .expect(400);

    expect(response.body.errors).toContainEqual(
      expect.objectContaining({
        field: 'title',
        message: expect.stringContaining('at least 3 characters')
      })
    );
  });

  it('should sanitize HTML in content', async () => {
    const response = await request(app)
      .post('/api/v1/articles')
      .send({ 
        title: 'Valid Title',
        content: '<script>alert("xss")</script>Safe content'
      })
      .expect(201);

    expect(response.body.content).not.toContain('<script>');
  });
});
```

With comprehensive validation in place, your REST API is now production-ready with robust security, data integrity, and excellent developer experience. Validation is your first line of defense and should be treated as a critical component of your API architecture.

