// Custom validator for strong passwords
export const strongPassword = Joi.extend((joi) => ({
  type: 'string',
  base: joi.string(),
  messages: {
    'string.strongPassword':
      '{{#label}} must be at least 8 characters long and contain uppercase, lowercase, number, and special character',
  },
  rules: {
    strongPassword: {
      validate(value, helpers) {
        const hasUpperCase = /[A-Z]/.test(value);
        const hasLowerCase = /[a-z]/.test(value);
        const hasNumber = /\d/.test(value);
        const hasSpecialChar = /[@$!%*?&]/.test(value);
        const isLongEnough = value.length >= 8;

        if (!(hasUpperCase && hasLowerCase && hasNumber && hasSpecialChar && isLongEnough)) {
          return helpers.error('string.strongPassword');
        }

        return value;
      },
    },
  },
}));

// Custom validator for phone numbers
export const phoneNumber = Joi.extend((joi) => ({
  type: 'string',
  base: joi.string(),
  messages: {
    'string.phoneNumber': '{{#label}} must be a valid phone number',
  },
  rules: {
    phoneNumber: {
      validate(value, helpers) {
        // Simple international phone number validation
        const phoneRegex = /^\+?[1-9]\d{1,14}$/;
        if (!phoneRegex.test(value.replace(/[\s-]/g, ''))) {
          return helpers.error('string.phoneNumber');
        }
        return value;
      },
    },
  },
}));

// Custom validator for URLs
export const secureUrl = Joi.extend((joi) => ({
  type: 'string',
  base: joi.string(),
  messages: {
    'string.secureUrl': '{{#label}} must be a valid HTTPS URL',
  },
  rules: {
    secureUrl: {
      validate(value, helpers) {
        try {
          const url = new URL(value);
          if (url.protocol !== 'https:') {
            return helpers.error('string.secureUrl');
          }
          return value;
        } catch {
          return helpers.error('string.secureUrl');
        }
      },
    },
  },
}));
