### Sanitization Helpers

Create `src/utils/sanitize.ts`:

```typescript
import validator from 'validator';

export class Sanitizer {
  static sanitizeString(input: string): string {
    return validator.escape(validator.trim(input));
  }

  static sanitizeEmail(email: string): string {
    return validator.normalizeEmail(email) || email;
  }

  static sanitizeHtml(html: string): string {
    // Remove all HTML tags
    return validator.stripLow(html.replace(/<[^>]*>/g, ''));
  }

  static sanitizeObject<T extends Record<string, any>>(obj: T): T {
    const sanitized = {} as T;

    for (const [key, value] of Object.entries(obj)) {
      if (typeof value === 'string') {
        sanitized[key as keyof T] = this.sanitizeString(value) as T[keyof T];
      } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        sanitized[key as keyof T] = this.sanitizeObject(value);
      } else {
        sanitized[key as keyof T] = value;
      }
    }

    return sanitized;
  }
}
```

### Application Entry Point

Create `src/app.ts`:

```typescript
import express, { Application } from 'express';
import { securityMiddleware } from './middleware/security.middleware';
import { compressionMiddleware } from './middleware/compression.middleware';
import { requestLogger } from './middleware/logger.middleware';
import { contextMiddleware } from './middleware/context.middleware';
import { errorHandler } from './middleware/error.middleware';
import { apiLimiter } from './middleware/rateLimiter.middleware';
import routes from './routes';

export const createApp = (): Application => {
  const app = express();

  // Trust proxy
  app.set('trust proxy', 1);

  // Body parser
  app.use(express.json({ limit: '10mb' }));
  app.use(express.urlencoded({ extended: true, limit: '10mb' }));

  // Security middleware
  app.use(securityMiddleware);

  // Compression
  app.use(compressionMiddleware);

  // Request context
  app.use(contextMiddleware);

  // Request logging
  app.use(requestLogger);

  // Rate limiting
  app.use(apiLimiter);

  // Routes
  app.use(routes);

  // Error handling
  app.use(errorHandler);

  return app;
};
```

Create `src/server.ts`:

```typescript
import { createApp } from './app';
import { env } from './config/environment';
import { logger } from './config/logger';
import { database } from './config/database';
import {
  handleUnhandledRejection,
  handleUncaughtException,
} from './middleware/error.middleware';

// Handle uncaught exceptions
handleUncaughtException();

const startServer = async () => {
  try {
    // Connect to database
    await database.connect();

    // Create Express app
    const app = createApp();

    // Start server
    const server = app.listen(env.port, () => {
      logger.info(`Server running on port ${env.port} in ${env.nodeEnv} mode`);
    });

    // Handle unhandled rejections
    handleUnhandledRejection();

    // Graceful shutdown
    const gracefulShutdown = async (signal: string) => {
      logger.info(`${signal} received. Starting graceful shutdown...`);

      server.close(async () => {
        logger.info('HTTP server closed');

        try {
          await database.disconnect();
          logger.info('Database connection closed');
          process.exit(0);
        } catch (error) {
          logger.error('Error during shutdown:', error);
          process.exit(1);
        }
      });

      // Force shutdown after 30 seconds
      setTimeout(() => {
        logger.error('Forced shutdown after timeout');
        process.exit(1);
      }, 30000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

startServer();
```

### User Controller Implementation

Create `src/controllers/user.controller.ts`:

```typescript
import { Request, Response } from 'express';
import { UserRepository } from '../repositories/user.repository';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiError } from '../utils/ApiError';
import { QueryParser } from '../utils/queryParser';

export class UserController {
  private userRepository: UserRepository;

  constructor() {
    this.userRepository = new UserRepository();
  }

  getCurrentUser = asyncHandler(async (req: Request, res: Response) => {
    const user = await this.userRepository.findById(req.user!.userId);
    if (!user) {
      throw ApiError.notFound('User not found');
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  });

  updateCurrentUser = asyncHandler(async (req: Request, res: Response) => {
    const { email, firstName, lastName } = req.body;

    // Check if email is being changed and if it's already taken
    if (email) {
      const existingUser = await this.userRepository.findByEmail(email);
      if (existingUser && existingUser._id.toString() !== req.user!.userId) {
        throw ApiError.conflict('Email already in use');
      }
    }

    const user = await this.userRepository.update(req.user!.userId, {
      email,
      firstName,
      lastName,
    });

    if (!user) {
      throw ApiError.notFound('User not found');
    }

    res.status(200).json({
      status: 'success',
      message: 'Profile updated successfully',
      data: { user },
    });
  });

  deleteCurrentUser = asyncHandler(async (req: Request, res: Response) => {
    await this.userRepository.delete(req.user!.userId);

    res.status(200).json({
      status: 'success',
      message: 'Account deleted successfully',
    });
  });

  changePassword = asyncHandler(async (req: Request, res: Response) => {
    const { currentPassword, newPassword } = req.body;

    const user = await this.userRepository.findById(req.user!.userId);
    if (!user) {
      throw ApiError.notFound('User not found');
    }

    const isPasswordValid = await user.comparePassword(currentPassword);
    if (!isPasswordValid) {
      throw ApiError.unauthorized('Current password is incorrect');
    }

    user.password = newPassword;
    await user.save();

    res.status(200).json({
      status: 'success',
      message: 'Password changed successfully',
    });
  });

  getUsers = asyncHandler(async (req: Request, res: Response) => {
    const parsedQuery = QueryParser.parse(req);
    const result = await this.userRepository.findWithPagination(parsedQuery);

    res.status(200).json({
      status: 'success',
      data: result.data,
      pagination: result.pagination,
    });
  });

  getUserById = asyncHandler(async (req: Request, res: Response) => {
    const user = await this.userRepository.findById(req.params.id);
    if (!user) {
      throw ApiError.notFound('User not found');
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  });

  updateUser = asyncHandler(async (req: Request, res: Response) => {
    const user = await this.userRepository.update(req.params.id, req.body);
    if (!user) {
      throw ApiError.notFound('User not found');
    }

    res.status(200).json({
      status: 'success',
      message: 'User updated successfully',
      data: { user },
    });
  });

  deleteUser = asyncHandler(async (req: Request, res: Response) => {
    const user = await this.userRepository.delete(req.params.id);
    if (!user) {
      throw ApiError.notFound('User not found');
    }

    res.status(200).json({
      status: 'success',
      message: 'User deleted successfully',
    });
  });
}
```

