### Request Sanitization Middleware

Create `src/middleware/sanitize.js`:

```javascript
const Sanitizer = require('../utils/sanitizer');

// Sanitize request body
exports.sanitizeBody = (req, res, next) => {
  if (req.body) {
    req.body = Sanitizer.sanitizeObject(req.body);
  }
  next();
};

// Sanitize query parameters
exports.sanitizeQuery = (req, res, next) => {
  if (req.query) {
    req.query = Sanitizer.sanitizeObject(req.query);
  }
  next();
};

// Sanitize route parameters
exports.sanitizeParams = (req, res, next) => {
  if (req.params) {
    req.params = Sanitizer.sanitizeObject(req.params);
  }
  next();
};

// Sanitize all request data
exports.sanitizeAll = (req, res, next) => {
  if (req.body) req.body = Sanitizer.sanitizeObject(req.body);
  if (req.query) req.query = Sanitizer.sanitizeObject(req.query);
  if (req.params) req.params = Sanitizer.sanitizeObject(req.params);
  next();
};
```

