### Custom Business Logic Validators

Create `src/validators/business.validators.js`:

```javascript
const Product = require('../models/product.model');
const Order = require('../models/order.model');

class BusinessValidators {
  // Validate product availability
  static async validateProductAvailability(productId, quantity) {
    const product = await Product.findById(productId);

    if (!product) {
      throw new Error('Product not found');
    }

    if (!product.isActive) {
      throw new Error('Product is not available');
    }

    if (product.stock < quantity) {
      throw new Error(`Only ${product.stock} items available in stock`);
    }

    return true;
  }

  // Validate order total
  static async validateOrderTotal(items) {
    let calculatedTotal = 0;

    for (const item of items) {
      const product = await Product.findById(item.productId);
      if (!product) {
        throw new Error(`Product ${item.productId} not found`);
      }

      const expectedPrice = product.discountedPrice || product.price;
      if (Math.abs(item.price - expectedPrice) > 0.01) {
        throw new Error(`Price mismatch for product ${product.name}`);
      }

      calculatedTotal += item.price * item.quantity;
    }

    return calculatedTotal;
  }

  // Validate user can cancel order
  static async validateOrderCancellation(orderId, userId) {
    const order = await Order.findById(orderId);

    if (!order) {
      throw new Error('Order not found');
    }

    if (order.user.toString() !== userId) {
      throw new Error('Not authorized to cancel this order');
    }

    if (['shipped', 'delivered'].includes(order.status)) {
      throw new Error('Cannot cancel order that has been shipped or delivered');
    }

    return true;
  }

  // Validate discount code
  static async validateDiscountCode(code, userId, orderTotal) {
    // This would typically check against a DiscountCode model
    // Simplified example:
    const validCodes = {
      'SAVE10': { discount: 0.10, minOrder: 50 },
      'SAVE20': { discount: 0.20, minOrder: 100 }
    };

    const discountInfo = validCodes[code];

    if (!discountInfo) {
      throw new Error('Invalid discount code');
    }

    if (orderTotal < discountInfo.minOrder) {
      throw new Error(`Minimum order of $${discountInfo.minOrder} required for this code`);
    }

    return discountInfo.discount;
  }
}

module.exports = BusinessValidators;
```

### Validation Testing

Create `tests/validation.test.js`:

```javascript
const request = require('supertest');
const app = require('../src/app');
const { connectDB, closeDB, clearDB } = require('./setup');

describe('Validation Tests', () => {
  beforeAll(async () => await connectDB());
  afterEach(async () => await clearDB());
  afterAll(async () => await closeDB());

  describe('User Validation', () => {
    it('should reject invalid email format', async () => {
      const res = await request(app)
        .post('/api/v1/auth/register')
        .send({
          name: 'Test User',
          email: 'invalid-email',
          password: 'Test@1234'
        });

      expect(res.statusCode).toBe(400);
      expect(res.body.error).toBe('Validation Error');
    });

    it('should reject weak password', async () => {
      const res = await request(app)
        .post('/api/v1/auth/register')
        .send({
          name: 'Test User',
          email: 'test@example.com',
          password: 'weak'
        });

      expect(res.statusCode).toBe(400);
      expect(res.body.details).toBeDefined();
    });

    it('should accept valid user data', async () => {
      const res = await request(app)
        .post('/api/v1/auth/register')
        .send({
          name: 'Test User',
          email: 'test@example.com',
          password: 'Test@1234'
        });

      expect(res.statusCode).toBe(201);
    });
  });

  describe('Product Validation', () => {
    it('should reject negative price', async () => {
      const res = await request(app)
        .post('/api/v1/products')
        .send({
          name: 'Test Product',
          description: 'Test description',
          price: -10,
          category: 'electronics',
          stock: 100,
          sku: 'TEST-001'
        });

      expect(res.statusCode).toBe(400);
    });

    it('should reject invalid category', async () => {
      const res = await request(app)
        .post('/api/v1/products')
        .send({
          name: 'Test Product',
          description: 'Test description',
          price: 99.99,
          category: 'invalid-category',
          stock: 100,
          sku: 'TEST-001'
        });

      expect(res.statusCode).toBe(400);
    });
  });

  describe('Sanitization', () => {
    it('should sanitize XSS attempts', async () => {
      const res = await request(app)
        .post('/api/v1/auth/register')
        .send({
          name: '<script>alert("xss")</script>',
          email: 'test@example.com',
          password: 'Test@1234'
        });

      // Should either reject or sanitize
      if (res.statusCode === 201) {
        expect(res.body.data.user.name).not.toContain('<script>');
      }
    });
  });
});
```

### Best Practices Summary

✅ **Multi-layer validation**: Route, controller, and service level validation
✅ **Clear error messages**: Actionable feedback for API consumers
✅ **Custom validators**: Business logic validation beyond basic types
✅ **Data sanitization**: XSS prevention and input cleaning
✅ **Type checking**: Strict type validation for all inputs
✅ **Range validation**: Min/max constraints for numbers and strings
✅ **Format validation**: Email, phone, URL, credit card validation
✅ **Async validation**: Database checks for uniqueness and existence
✅ **Whitelist approach**: Only allow expected fields
✅ **Comprehensive testing**: Validation edge cases covered

