## Section 6: Validation

### Validation Schemas

Create `src/validators/auth.validator.ts`:

```typescript
import Joi from 'joi';

const emailSchema = Joi.string().email().required().messages({
  'string.email': 'Please provide a valid email address',
  'any.required': 'Email is required',
});

const passwordSchema = Joi.string().min(8).required().messages({
  'string.min': 'Password must be at least 8 characters long',
  'any.required': 'Password is required',
});

export const authValidator = {
  register: Joi.object({
    body: Joi.object({
      email: emailSchema,
      password: passwordSchema,
      firstName: Joi.string().min(2).max(50).required().messages({
        'string.min': 'First name must be at least 2 characters long',
        'string.max': 'First name cannot exceed 50 characters',
        'any.required': 'First name is required',
      }),
      lastName: Joi.string().min(2).max(50).required().messages({
        'string.min': 'Last name must be at least 2 characters long',
        'string.max': 'Last name cannot exceed 50 characters',
        'any.required': 'Last name is required',
      }),
    }),
  }),

  login: Joi.object({
    body: Joi.object({
      email: emailSchema,
      password: Joi.string().required().messages({
        'any.required': 'Password is required',
      }),
    }),
  }),

  refresh: Joi.object({
    body: Joi.object({
      refreshToken: Joi.string().required().messages({
        'any.required': 'Refresh token is required',
      }),
    }),
  }),

  forgotPassword: Joi.object({
    body: Joi.object({
      email: emailSchema,
    }),
  }),

  resetPassword: Joi.object({
    body: Joi.object({
      token: Joi.string().required().messages({
        'any.required': 'Reset token is required',
      }),
      password: passwordSchema,
    }),
  }),
};
```

Create `src/validators/user.validator.ts`:

```typescript
import Joi from 'joi';

const uuidSchema = Joi.string().uuid().messages({
  'string.guid': 'Invalid ID format',
});

export const userValidator = {
  updateProfile: Joi.object({
    body: Joi.object({
      firstName: Joi.string().min(2).max(50).messages({
        'string.min': 'First name must be at least 2 characters long',
        'string.max': 'First name cannot exceed 50 characters',
      }),
      lastName: Joi.string().min(2).max(50).messages({
        'string.min': 'Last name must be at least 2 characters long',
        'string.max': 'Last name cannot exceed 50 characters',
      }),
      email: Joi.string().email().messages({
        'string.email': 'Please provide a valid email address',
      }),
    }).min(1).messages({
      'object.min': 'At least one field must be provided for update',
    }),
  }),

  getUsers: Joi.object({
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      search: Joi.string().allow(''),
      role: Joi.string().valid('user', 'admin', 'moderator'),
      isActive: Joi.boolean(),
    }),
  }),

  getUserById: Joi.object({
    params: Joi.object({
      id: uuidSchema.required(),
    }),
  }),

  updateUser: Joi.object({
    params: Joi.object({
      id: uuidSchema.required(),
    }),
    body: Joi.object({
      firstName: Joi.string().min(2).max(50),
      lastName: Joi.string().min(2).max(50),
      email: Joi.string().email(),
      role: Joi.string().valid('user', 'admin', 'moderator'),
      isActive: Joi.boolean(),
      emailVerified: Joi.boolean(),
    }).min(1).messages({
      'object.min': 'At least one field must be provided for update',
    }),
  }),

  deleteUser: Joi.object({
    params: Joi.object({
      id: uuidSchema.required(),
    }),
  }),
};
```

### Custom Validation Rules

Create `src/validators/custom.validator.ts`:

```typescript
import Joi from 'joi';

// Custom validator for strong passwords
export const strongPassword = Joi.string()
  .min(8)
  .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
  .messages({
    'string.pattern.base':
      'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character',
    'string.min': 'Password must be at least 8 characters long',
  });

// Custom validator for phone numbers
export const phoneNumber = Joi.string()
  .pattern(/^\+?[1-9]\d{1,14}$/)
  .messages({
    'string.pattern.base': 'Please provide a valid phone number',
  });

// Custom validator for URLs
export const url = Joi.string()
  .uri({ scheme: ['http', 'https'] })
  .messages({
    'string.uri': 'Please provide a valid URL',
  });

// Custom validator for dates
export const futureDate = Joi.date()
  .greater('now')
  .messages({
    'date.greater': 'Date must be in the future',
  });

export const pastDate = Joi.date()
  .less('now')
  .messages({
    'date.less': 'Date must be in the past',
  });

// Custom validator for file uploads
export const fileUpload = Joi.object({
  fieldname: Joi.string().required(),
  originalname: Joi.string().required(),
  encoding: Joi.string().required(),
  mimetype: Joi.string()
    .valid('image/jpeg', 'image/png', 'image/gif', 'application/pdf')
    .required()
    .messages({
      'any.only': 'File type must be JPEG, PNG, GIF, or PDF',
    }),
  size: Joi.number()
    .max(5 * 1024 * 1024) // 5MB
    .required()
    .messages({
      'number.max': 'File size cannot exceed 5MB',
    }),
});
```

### Input Sanitization

Create `src/utils/sanitize.ts`:

```typescript
import validator from 'validator';

export class Sanitizer {
  static sanitizeString(input: string): string {
    return validator.escape(validator.trim(input));
  }

  static sanitizeEmail(email: string): string {
    return validator.normalizeEmail(email) || email;
  }

  static sanitizeHTML(html: string): string {
    // In production, use a library like DOMPurify
    return validator.stripLow(html);
  }

  static sanitizeObject<T extends Record<string, any>>(obj: T): T {
    const sanitized = {} as T;

    for (const [key, value] of Object.entries(obj)) {
      if (typeof value === 'string') {
        sanitized[key as keyof T] = this.sanitizeString(value) as T[keyof T];
      } else if (Array.isArray(value)) {
        sanitized[key as keyof T] = value.map((item) =>
          typeof item === 'string' ? this.sanitizeString(item) : item
        ) as T[keyof T];
      } else if (typeof value === 'object' && value !== null) {
        sanitized[key as keyof T] = this.sanitizeObject(value);
      } else {
        sanitized[key as keyof T] = value;
      }
    }

    return sanitized;
  }
}
```

### Testing Validation

Create `tests/unit/validators/auth.validator.test.ts`:

```typescript
import { authValidator } from '../../../src/validators/auth.validator';

describe('Auth Validator', () => {
  describe('register', () => {
    it('should validate correct registration data', () => {
      const data = {
        body: {
          email: 'test@example.com',
          password: 'SecurePass123!',
          firstName: 'John',
          lastName: 'Doe',
        },
      };

      const { error } = authValidator.register.validate(data);
      expect(error).toBeUndefined();
    });

    it('should reject invalid email', () => {
      const data = {
        body: {
          email: 'invalid-email',
          password: 'SecurePass123!',
          firstName: 'John',
          lastName: 'Doe',
        },
      };

      const { error } = authValidator.register.validate(data);
      expect(error).toBeDefined();
      expect(error?.details[0].message).toContain('valid email');
    });

    it('should reject short password', () => {
      const data = {
        body: {
          email: 'test@example.com',
          password: 'short',
          firstName: 'John',
          lastName: 'Doe',
        },
      };

      const { error } = authValidator.register.validate(data);
      expect(error).toBeDefined();
      expect(error?.details[0].message).toContain('8 characters');
    });

    it('should reject missing required fields', () => {
      const data = {
        body: {
          email: 'test@example.com',
        },
      };

      const { error } = authValidator.register.validate(data);
      expect(error).toBeDefined();
    });
  });

  describe('login', () => {
    it('should validate correct login data', () => {
      const data = {
        body: {
          email: 'test@example.com',
          password: 'password123',
        },
      };

      const { error } = authValidator.login.validate(data);
      expect(error).toBeUndefined();
    });
  });
});
