### Business Logic Validation

Create `src/services/ValidationService.ts`:

```typescript
import { UserRepository } from '../repositories/UserRepository';
import { ValidationError } from '../utils/errors';
import { customValidators } from '../validators/customValidators';

export class ValidationService {
  private userRepo: UserRepository;

  constructor() {
    this.userRepo = new UserRepository();
  }

  async validateUserCreation(data: {
    email: string;
    username: string;
    password: string;
    dateOfBirth?: Date;
  }): Promise<void> {
    const errors: string[] = [];

    // Check email uniqueness
    const isEmailUnique = await customValidators.isUniqueEmail(data.email);
    if (!isEmailUnique) {
      errors.push('Email already in use');
    }

    // Check username uniqueness
    const isUsernameUnique = await customValidators.isUniqueUsername(data.username);
    if (!isUsernameUnique) {
      errors.push('Username already taken');
    }

    // Validate password strength
    if (!customValidators.isStrongPassword(data.password)) {
      errors.push('Password does not meet strength requirements');
    }

    // Validate age if date of birth provided
    if (data.dateOfBirth && !customValidators.meetsAgeRequirement(data.dateOfBirth)) {
      errors.push('Must be at least 18 years old');
    }

    if (errors.length > 0) {
      throw new ValidationError(errors.join(', '));
    }
  }

  async validateUserUpdate(
    userId: number,
    data: {
      email?: string;
      username?: string;
    }
  ): Promise<void> {
    const errors: string[] = [];

    // Check email uniqueness if being updated
    if (data.email) {
      const isEmailUnique = await customValidators.isUniqueEmail(data.email, userId);
      if (!isEmailUnique) {
        errors.push('Email already in use');
      }
    }

    // Check username uniqueness if being updated
    if (data.username) {
      const isUsernameUnique = await customValidators.isUniqueUsername(data.username, userId);
      if (!isUsernameUnique) {
        errors.push('Username already taken');
      }
    }

    if (errors.length > 0) {
      throw new ValidationError(errors.join(', '));
    }
  }
}
