import { createUserSchema, updateUserSchema } from '../../src/validators/schemas/user.schema';

describe('User Validation Schemas', () => {
  describe('createUserSchema', () => {
    it('should validate correct user data', async () => {
      const validData = {
        body: {
          email: 'test@example.com',
          username: 'testuser',
          password: 'Password123!',
          firstName: 'Test',
          lastName: 'User',
        },
      };

      const result = await createUserSchema.parseAsync(validData);
      expect(result.body.email).toBe('test@example.com');
    });

    it('should reject invalid email', async () => {
      const invalidData = {
        body: {
          email: 'invalid-email',
          username: 'testuser',
          password: 'Password123!',
        },
      };

      await expect(createUserSchema.parseAsync(invalidData)).rejects.toThrow();
    });

    it('should reject weak password', async () => {
      const invalidData = {
        body: {
          email: 'test@example.com',
          username: 'testuser',
          password: 'weak',
        },
      };

      await expect(createUserSchema.parseAsync(invalidData)).rejects.toThrow();
    });

    it('should reject short username', async () => {
      const invalidData = {
        body: {
          email: 'test@example.com',
          username: 'ab',
          password: 'Password123!',
        },
      };

      await expect(createUserSchema.parseAsync(invalidData)).rejects.toThrow();
    });
  });

  describe('updateUserSchema', () => {
    it('should validate partial updates', async () => {
      const validData = {
        params: { id: '123' },
        body: { firstName: 'Updated' },
      };

      const result = await updateUserSchema.parseAsync(validData);
      expect(result.params.id).toBe(123);
      expect(result.body.firstName).toBe('Updated');
    });

    it('should reject empty update', async () => {
      const invalidData = {
        params: { id: '123' },
        body: {},
      };

      await expect(updateUserSchema.parseAsync(invalidData)).rejects.toThrow();
    });
  });
});
