### Validation Error Response Format

Update `src/middleware/errorHandler.ts` to handle validation errors:

```typescript
import { Request, Response, NextFunction } from 'express';
import { AppError, ValidationError } from '../utils/errors';
import { logger } from '../utils/logger';

export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
) => {
  logger.error('Error occurred:', err);

  if (err instanceof ValidationError) {
    let errors;
    try {
      errors = JSON.parse(err.message);
    } catch {
      errors = [{ field: 'general', message: err.message }];
    }

    return res.status(err.statusCode).json({
      success: false,
      error: {
        type: 'ValidationError',
        message: 'Validation failed',
        errors,
      },
    });
  }

  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        type: err.constructor.name,
        message: err.message,
      },
    });
  }

  // Unexpected errors
  return res.status(500).json({
    success: false,
    error: {
      type: 'InternalServerError',
      message: process.env.NODE_ENV === 'production' 
        ? 'An unexpected error occurred' 
        : err.message,
    },
  });
};
```

### Complete Server Setup with All Middleware

Update `src/server.ts` with complete middleware stack:

```typescript
import express, { Application } from 'express';
import dotenv from 'dotenv';
import cors from 'cors';
import helmet from 'helmet';
import compression from 'compression';
import xss from 'xss-clean';

import { requestLogger } from './middleware/logger';
import { rateLimiter } from './middleware/rateLimiter';
import { sanitizeInput } from './middleware/sanitize';
import { errorHandler } from './middleware/errorHandler';
import { notFoundHandler } from './middleware/notFoundHandler';

import userRoutes from './routes/user.routes';
import authRoutes from './routes/auth.routes';

dotenv.config();

const app: Application = express();
const PORT = process.env.PORT || 3000;

// Security middleware
app.use(helmet());
app.use(cors());
app.use(xss());

// Performance middleware
app.use(compression());

// Body parsing
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Custom middleware
app.use(requestLogger);
app.use(sanitizeInput);
app.use(rateLimiter);

// Health check
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// API routes
app.use('/api/v1/auth', authRoutes);
app.use('/api/v1/users', userRoutes);

// Error handling (must be last)
app.use(notFoundHandler);
app.use(errorHandler);

app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

export default app;
```

### Key Takeaways

- Implement validation at multiple layers: schema, business logic, and database
- Use type-safe validation libraries like Zod for better developer experience
- Sanitize all user input to prevent XSS and injection attacks
- Provide clear, actionable error messages for validation failures
- Validate both structure (schema) and business rules (uniqueness, relationships)
- Use custom validators for complex domain-specific validation
- Test validation logic thoroughly with edge cases
- Validate file uploads for type, size, and content
- Apply validation middleware before controller logic
- Return consistent error response formats
- Never trust client-side validation alone
- Validate query parameters for pagination and filtering

