### OAuth Integration

**src/services/oauth.service.ts:**
```typescript
import axios from 'axios';
import { env } from '../config/environment';
import { UnauthorizedError } from '../utils/ApiError';

export interface OAuthProvider {
  name: string;
  authUrl: string;
  tokenUrl: string;
  userInfoUrl: string;
  clientId: string;
  clientSecret: string;
  redirectUri: string;
  scope: string[];
}

export class OAuthService {
  private providers: Map<string, OAuthProvider>;

  constructor() {
    this.providers = new Map();
    this.initializeProviders();
  }

  private initializeProviders() {
    // Google OAuth
    this.providers.set('google', {
      name: 'google',
      authUrl: 'https://accounts.google.com/o/oauth2/v2/auth',
      tokenUrl: 'https://oauth2.googleapis.com/token',
      userInfoUrl: 'https://www.googleapis.com/oauth2/v2/userinfo',
      clientId: env.GOOGLE_CLIENT_ID,
      clientSecret: env.GOOGLE_CLIENT_SECRET,
      redirectUri: env.GOOGLE_REDIRECT_URI,
      scope: ['email', 'profile'],
    });

    // GitHub OAuth
    this.providers.set('github', {
      name: 'github',
      authUrl: 'https://github.com/login/oauth/authorize',
      tokenUrl: 'https://github.com/login/oauth/access_token',
      userInfoUrl: 'https://api.github.com/user',
      clientId: env.GITHUB_CLIENT_ID,
      clientSecret: env.GITHUB_CLIENT_SECRET,
      redirectUri: env.GITHUB_REDIRECT_URI,
      scope: ['user:email'],
    });
  }

  getAuthorizationUrl(providerName: string, state: string): string {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Unknown OAuth provider: ${providerName}`);
    }

    const params = new URLSearchParams({
      client_id: provider.clientId,
      redirect_uri: provider.redirectUri,
      scope: provider.scope.join(' '),
      response_type: 'code',
      state,
    });

    return `${provider.authUrl}?${params.toString()}`;
  }

  async getAccessToken(providerName: string, code: string): Promise<string> {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Unknown OAuth provider: ${providerName}`);
    }

    try {
      const response = await axios.post(
        provider.tokenUrl,
        {
          client_id: provider.clientId,
          client_secret: provider.clientSecret,
          code,
          redirect_uri: provider.redirectUri,
          grant_type: 'authorization_code',
        },
        {
          headers: {
            Accept: 'application/json',
          },
        }
      );

      return response.data.access_token;
    } catch (error) {
      throw new UnauthorizedError('Failed to get access token');
    }
  }

  async getUserInfo(providerName: string, accessToken: string): Promise<any> {
    const provider = this.providers.get(providerName);
    if (!provider) {
      throw new Error(`Unknown OAuth provider: ${providerName}`);
    }

    try {
      const response = await axios.get(provider.userInfoUrl, {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      });

      return response.data;
    } catch (error) {
      throw new UnauthorizedError('Failed to get user info');
    }
  }
}
