### Two-Factor Authentication

**src/services/twoFactor.service.ts:**
```typescript
import speakeasy from 'speakeasy';
import QRCode from 'qrcode';
import { UserModel } from '../models/user.model';
import { UnauthorizedError } from '../utils/ApiError';

export class TwoFactorService {
  private userModel: UserModel;

  constructor() {
    this.userModel = new UserModel();
  }

  async generateSecret(userId: string): Promise<{ secret: string; qrCode: string }> {
    const user = await this.userModel.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    const secret = speakeasy.generateSecret({
      name: `YourApp (${user.email})`,
      length: 32,
    });

    // Generate QR code
    const qrCode = await QRCode.toDataURL(secret.otpauth_url!);

    // Store secret in database (encrypted)
    // await this.userModel.update(userId, { twoFactorSecret: secret.base32 });

    return {
      secret: secret.base32,
      qrCode,
    };
  }

  async verifyToken(userId: string, token: string): Promise<boolean> {
    const user = await this.userModel.findById(userId);
    if (!user || !user.twoFactorSecret) {
      throw new UnauthorizedError('2FA not enabled');
    }

    return speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token,
      window: 2, // Allow 2 time steps before/after
    });
  }

  async enable2FA(userId: string, token: string): Promise<void> {
    const isValid = await this.verifyToken(userId, token);
    if (!isValid) {
      throw new UnauthorizedError('Invalid 2FA token');
    }

    // Enable 2FA for user
    // await this.userModel.update(userId, { twoFactorEnabled: true });
  }

  async disable2FA(userId: string, token: string): Promise<void> {
    const isValid = await this.verifyToken(userId, token);
    if (!isValid) {
      throw new UnauthorizedError('Invalid 2FA token');
    }

    // Disable 2FA for user
    // await this.userModel.update(userId, {
    //   twoFactorEnabled: false,
    //   twoFactorSecret: null,
    // });
  }
}
