```typescript
import { Request, Response } from 'express';
import { AuthService } from '../services/auth.service';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiResponse } from '../utils/ApiResponse';
import { AuthRequest } from '../middleware/auth.middleware';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  register = asyncHandler(async (req: Request, res: Response) => {
    const { user, tokens } = await this.authService.register(req.body);

    res.status(201).json(
      ApiResponse.created(
        { user, tokens },
        'User registered successfully. Please verify your email.'
      )
    );
  });

  login = asyncHandler(async (req: Request, res: Response) => {
    const { email, password } = req.body;
    const { user, tokens } = await this.authService.login(email, password);

    res.json(ApiResponse.success({ user, tokens }, 'Login successful'));
  });

  refreshToken = asyncHandler(async (req: Request, res: Response) => {
    const { refreshToken } = req.body;
    const tokens = await this.authService.refreshToken(refreshToken);

    res.json(ApiResponse.success({ tokens }, 'Token refreshed successfully'));
  });

  forgotPassword = asyncHandler(async (req: Request, res: Response) => {
    const { email } = req.body;
    await this.authService.forgotPassword(email);

    res.json(
      ApiResponse.success(
        null,
        'If the email exists, a password reset link has been sent'
      )
    );
  });

  resetPassword = asyncHandler(async (req: Request, res: Response) => {
    const { token } = req.params;
    const { password } = req.body;

    await this.authService.resetPassword(token, password);

    res.json(ApiResponse.success(null, 'Password reset successfully'));
  });

  changePassword = asyncHandler(async (req: AuthRequest, res: Response) => {
    const { currentPassword, newPassword } = req.body;
    await this.authService.changePassword(req.user!.id, currentPassword, newPassword);

    res.json(ApiResponse.success(null, 'Password changed successfully'));
  });

  logout = asyncHandler(async (req: AuthRequest, res: Response) => {
    await this.authService.logout(req.user!.id);

    res.json(ApiResponse.success(null, 'Logged out successfully'));
  });

  getCurrentUser = asyncHandler(async (req: AuthRequest, res: Response) => {
    res.json(ApiResponse.success({ user: req.user }, 'User retrieved successfully'));
  });
}
```

