## Section 6: Validation

### Validation with Zod

Install Zod:

```bash
npm install zod
```

### Authentication Validators

Create `src/validators/auth.validator.ts`:

```typescript
import { z } from 'zod';

const passwordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .max(128, 'Password must not exceed 128 characters')
  .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
  .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
  .regex(/[0-9]/, 'Password must contain at least one number')
  .regex(/[^a-zA-Z0-9]/, 'Password must contain at least one special character');

const emailSchema = z
  .string()
  .email('Invalid email address')
  .toLowerCase()
  .trim();

export const authValidator = {
  register: z.object({
    body: z.object({
      email: emailSchema,
      password: passwordSchema,
      firstName: z
        .string()
        .min(1, 'First name is required')
        .max(50, 'First name must not exceed 50 characters')
        .trim(),
      lastName: z
        .string()
        .min(1, 'Last name is required')
        .max(50, 'Last name must not exceed 50 characters')
        .trim(),
    }),
  }),

  login: z.object({
    body: z.object({
      email: emailSchema,
      password: z.string().min(1, 'Password is required'),
    }),
  }),

  forgotPassword: z.object({
    body: z.object({
      email: emailSchema,
    }),
  }),

  resetPassword: z.object({
    params: z.object({
      token: z.string().min(1, 'Reset token is required'),
    }),
    body: z.object({
      password: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.password === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }),
  }),

  updatePassword: z.object({
    body: z.object({
      currentPassword: z.string().min(1, 'Current password is required'),
      newPassword: passwordSchema,
      confirmPassword: z.string(),
    }).refine((data) => data.newPassword === data.confirmPassword, {
      message: 'Passwords do not match',
      path: ['confirmPassword'],
    }),
  }),

  verifyEmail: z.object({
    params: z.object({
      token: z.string().min(1, 'Verification token is required'),
    }),
  }),

  resendVerification: z.object({
    body: z.object({
      email: emailSchema,
    }),
  }),
};
```

### User Validators

Create `src/validators/user.validator.ts`:

```typescript
import { z } from 'zod';

const mongoIdSchema = z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format');

export const userValidator = {
  getUserById: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  updateUser: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
    body: z.object({
      firstName: z.string().min(1).max(50).trim().optional(),
      lastName: z.string().min(1).max(50).trim().optional(),
      email: z.string().email().toLowerCase().trim().optional(),
      role: z.enum(['user', 'admin', 'moderator']).optional(),
      isActive: z.boolean().optional(),
    }).refine((data) => Object.keys(data).length > 0, {
      message: 'At least one field must be provided for update',
    }),
  }),

  deleteUser: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  updateProfile: z.object({
    body: z.object({
      firstName: z.string().min(1).max(50).trim().optional(),
      lastName: z.string().min(1).max(50).trim().optional(),
    }).refine((data) => Object.keys(data).length > 0, {
      message: 'At least one field must be provided for update',
    }),
  }),
};
```

### Product Validators

Create `src/validators/product.validator.ts`:

```typescript
import { z } from 'zod';

const mongoIdSchema = z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ID format');

const productBaseSchema = {
  name: z.string().min(1).max(200).trim(),
  description: z.string().min(1).max(5000),
  price: z.number().positive('Price must be positive'),
  compareAtPrice: z.number().positive().optional(),
  cost: z.number().positive().optional(),
  sku: z.string().min(1).toUpperCase(),
  barcode: z.string().optional(),
  quantity: z.number().int().min(0, 'Quantity cannot be negative'),
  category: z.string().min(1),
  tags: z.array(z.string()).optional(),
  images: z.array(z.string().url()).optional(),
  status: z.enum(['draft', 'active', 'archived']).optional(),
  vendor: z.string().optional(),
  weight: z.number().positive().optional(),
  dimensions: z.object({
    length: z.number().positive(),
    width: z.number().positive(),
    height: z.number().positive(),
  }).optional(),
  seo: z.object({
    title: z.string().max(60).optional(),
    description: z.string().max(160).optional(),
    keywords: z.array(z.string()).optional(),
  }).optional(),
  variants: z.array(z.object({
    name: z.string(),
    options: z.array(z.string()),
  })).optional(),
};

export const productValidator = {
  getProducts: z.object({
    query: z.object({
      page: z.string().regex(/^\d+$/).transform(Number).optional(),
      limit: z.string().regex(/^\d+$/).transform(Number).optional(),
      sort: z.string().optional(),
      category: z.string().optional(),
      status: z.enum(['draft', 'active', 'archived']).optional(),
      minPrice: z.string().regex(/^\d+(\.\d+)?$/).transform(Number).optional(),
      maxPrice: z.string().regex(/^\d+(\.\d+)?$/).transform(Number).optional(),
      search: z.string().optional(),
    }),
  }),

  getProductById: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  getProductsByCategory: z.object({
    params: z.object({
      category: z.string().min(1),
    }),
    query: z.object({
      page: z.string().regex(/^\d+$/).transform(Number).optional(),
      limit: z.string().regex(/^\d+$/).transform(Number).optional(),
      sort: z.string().optional(),
    }),
  }),

  searchProducts: z.object({
    query: z.object({
      q: z.string().min(1, 'Search query is required'),
      page: z.string().regex(/^\d+$/).transform(Number).optional(),
      limit: z.string().regex(/^\d+$/).transform(Number).optional(),
    }),
  }),

  createProduct: z.object({
    body: z.object(productBaseSchema),
  }),

  updateProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
    body: z.object({
      ...Object.fromEntries(
        Object.entries(productBaseSchema).map(([key, value]) => [key, value.optional()])
      ),
    }).refine((data) => Object.keys(data).length > 0, {
      message: 'At least one field must be provided for update',
    }),
  }),

  deleteProduct: z.object({
    params: z.object({
      id: mongoIdSchema,
    }),
  }),

  bulkCreateProducts: z.object({
    body: z.object({
      products: z.array(z.object(productBaseSchema)).min(1).max(100),
    }),
  }),

  bulkUpdateProducts: z.object({
    body: z.object({
      updates: z.array(z.object({
        id: mongoIdSchema,
        data: z.object({
          ...Object.fromEntries(
            Object.entries(productBaseSchema).map(([key, value]) => [key, value.optional()])
          ),
        }),
      })).min(1).max(100),
    }),
  }),
};
```

