## **Section 6: Validation**

### **Why Input Validation Matters**

Input validation is your API's first line of defense against bad data, security vulnerabilities, and application crashes. Never trust client input—always validate and sanitize data before processing it.

**Key Benefits:**
- **Security**: Prevent injection attacks, XSS, and malicious payloads
- **Data Integrity**: Ensure only valid data reaches your database
- **Better UX**: Provide clear, actionable error messages
- **Type Safety**: Catch type mismatches early in the request lifecycle

---

### **Choosing a Validation Library**

**Popular Options:**

1. **Zod** (Recommended for TypeScript)
   - Type-safe schema validation
   - Excellent TypeScript inference
   - Composable and reusable schemas

2. **Joi**
   - Mature and feature-rich
   - Great documentation
   - Works with JavaScript and TypeScript

3. **express-validator**
   - Built specifically for Express
   - Middleware-based approach
   - Based on validator.js

---

### **Implementation with Zod**

**Installation:**
```bash
npm install zod
```

**Define Validation Schemas:**

```typescript
// src/validators/user.validator.ts
import { z } from 'zod';

export const createUserSchema = z.object({
  body: z.object({
    email: z.string().email('Invalid email format'),
    password: z
      .string()
      .min(8, 'Password must be at least 8 characters')
      .regex(/[A-Z]/, 'Password must contain uppercase letter')
      .regex(/[a-z]/, 'Password must contain lowercase letter')
      .regex(/[0-9]/, 'Password must contain number'),
    name: z.string().min(2).max(100),
    age: z.number().int().min(18).max(120).optional(),
    role: z.enum(['user', 'admin', 'moderator']).default('user'),
  }),
});

export const updateUserSchema = z.object({
  params: z.object({
    id: z.string().uuid('Invalid user ID format'),
  }),
  body: z.object({
    email: z.string().email().optional(),
    name: z.string().min(2).max(100).optional(),
    age: z.number().int().min(18).max(120).optional(),
  }),
});

export const getUserSchema = z.object({
  params: z.object({
    id: z.string().uuid(),
  }),
});

export const listUsersSchema = z.object({
  query: z.object({
    page: z.string().regex(/^\d+$/).transform(Number).default('1'),
    limit: z.string().regex(/^\d+$/).transform(Number).default('10'),
    sortBy: z.enum(['name', 'email', 'createdAt']).optional(),
    order: z.enum(['asc', 'desc']).default('asc'),
  }),
});
```

---

### **Validation Middleware**

**Create Reusable Validation Middleware:**

```typescript
// src/middleware/validate.ts
import { Request, Response, NextFunction } from 'express';
import { AnyZodObject, ZodError } from 'zod';

export const validate = (schema: AnyZodObject) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      await schema.parseAsync({
        body: req.body,
        query: req.query,
        params: req.params,
      });
      next();
    } catch (error) {
      if (error instanceof ZodError) {
        const errors = error.errors.map((err) => ({
          field: err.path.join('.'),
          message: err.message,
        }));

        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors,
        });
      }
      next(error);
    }
  };
};
```

**Apply to Routes:**

```typescript
// src/routes/user.routes.ts
import { Router } from 'express';
import { validate } from '../middleware/validate';
import {
  createUserSchema,
  updateUserSchema,
  getUserSchema,
  listUsersSchema,
} from '../validators/user.validator';
import * as userController from '../controllers/user.controller';
import { authenticate } from '../middleware/auth';

const router = Router();

router.post(
  '/users',
  validate(createUserSchema),
  userController.createUser
);

router.get(
  '/users',
  authenticate,
  validate(listUsersSchema),
  userController.listUsers
);

router.get(
  '/users/:id',
  authenticate,
  validate(getUserSchema),
  userController.getUser
);

router.patch(
  '/users/:id',
  authenticate,
  validate(updateUserSchema),
  userController.updateUser
);

export default router;
```

