### **Advanced Validation Patterns**

**Custom Validators:**

```typescript
// src/validators/custom.validator.ts
import { z } from 'zod';

// Custom phone number validator
const phoneSchema = z.string().refine(
  (val) => /^\+?[1-9]\d{1,14}$/.test(val),
  { message: 'Invalid phone number format' }
);

// Password confirmation
const passwordConfirmSchema = z
  .object({
    password: z.string().min(8),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "Passwords don't match",
    path: ['confirmPassword'],
  });

// Date range validation
const dateRangeSchema = z
  .object({
    startDate: z.string().datetime(),
    endDate: z.string().datetime(),
  })
  .refine((data) => new Date(data.startDate) < new Date(data.endDate), {
    message: 'End date must be after start date',
    path: ['endDate'],
  });

// Conditional validation
const productSchema = z.object({
  type: z.enum(['physical', 'digital']),
  weight: z.number().optional(),
  downloadUrl: z.string().url().optional(),
}).refine(
  (data) => {
    if (data.type === 'physical') return data.weight !== undefined;
    if (data.type === 'digital') return data.downloadUrl !== undefined;
    return true;
  },
  {
    message: 'Physical products need weight, digital products need download URL',
  }
);
```

