### Authentication Controller

Create `src/controllers/auth.controller.ts`:

```typescript
import { Request, Response } from 'express';
import { AuthService } from '../services/auth.service';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiResponse } from '../utils/ApiResponse';
import { ApiError } from '../utils/ApiError';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  register = asyncHandler(async (req: Request, res: Response) => {
    const { email, password, firstName, lastName } = req.body;

    const result = await this.authService.register({
      email,
      password,
      firstName,
      lastName,
    });

    res.status(201).json(
      new ApiResponse(201, result, 'User registered successfully')
    );
  });

  login = asyncHandler(async (req: Request, res: Response) => {
    const { email, password } = req.body;

    const result = await this.authService.login(email, password);

    // Set refresh token in HTTP-only cookie
    res.cookie('refreshToken', result.tokens.refreshToken, {
      httpOnly: true,
      secure: env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    });

    res.status(200).json(
      new ApiResponse(200, result, 'Login successful')
    );
  });

  logout = asyncHandler(async (req: Request, res: Response) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

    if (!refreshToken) {
      throw new ApiError(400, 'Refresh token required');
    }

    await this.authService.logout(req.user.id, refreshToken);

    res.clearCookie('refreshToken');

    res.status(200).json(
      new ApiResponse(200, null, 'Logout successful')
    );
  });

  refreshToken = asyncHandler(async (req: Request, res: Response) => {
    const refreshToken = req.cookies.refreshToken || req.body.refreshToken;

    if (!refreshToken) {
      throw new ApiError(400, 'Refresh token required');
    }

    const tokens = await this.authService.refreshTokens(refreshToken);

    // Set new refresh token in cookie
    res.cookie('refreshToken', tokens.refreshToken, {
      httpOnly: true,
      secure: env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 30 * 24 * 60 * 60 * 1000,
    });

    res.status(200).json(
      new ApiResponse(200, tokens, 'Tokens refreshed successfully')
    );
  });

  forgotPassword = asyncHandler(async (req: Request, res: Response) => {
    const { email } = req.body;

    const result = await this.authService.forgotPassword(email);

    res.status(200).json(
      new ApiResponse(200, result, 'Password reset email sent')
    );
  });

  resetPassword = asyncHandler(async (req: Request, res: Response) => {
    const { token } = req.params;
    const { password } = req.body;

    const result = await this.authService.resetPassword(token, password);

    res.status(200).json(
      new ApiResponse(200, result, 'Password reset successful')
    );
  });

  verifyEmail = asyncHandler(async (req: Request, res: Response) => {
    const { token } = req.params;

    const result = await this.authService.verifyEmail(token);

    res.status(200).json(
      new ApiResponse(200, result, 'Email verified successfully')
    );
  });

  updatePassword = asyncHandler(async (req: Request, res: Response) => {
    const { currentPassword, newPassword } = req.body;

    const result = await this.authService.updatePassword(
      req.user.id,
      currentPassword,
      newPassword
    );

    res.status(200).json(
      new ApiResponse(200, result, 'Password updated successfully')
    );
  });

  getCurrentUser = asyncHandler(async (req: Request, res: Response) => {
    const user = await this.authService.getCurrentUser(req.user.id);

    res.status(200).json(
      new ApiResponse(200, user, 'User retrieved successfully')
    );
  });
}
```

Install cookie-parser:

```bash
npm install cookie-parser
npm install -D @types/cookie-parser
```

