### Error Monitoring Integration

Create `src/utils/errorMonitoring.js`:

```javascript
const logger = require('./logger');

/**
 * Initialize error monitoring service (e.g., Sentry)
 */
const initErrorMonitoring = () => {
  if (process.env.SENTRY_DSN && process.env.NODE_ENV === 'production') {
    const Sentry = require('@sentry/node');

    Sentry.init({
      dsn: process.env.SENTRY_DSN,
      environment: process.env.NODE_ENV,
      tracesSampleRate: 0.1,
      beforeSend(event, hint) {
        // Filter out operational errors from Sentry
        const error = hint.originalException;
        if (error && error.isOperational) {
          return null;
        }
        return event;
      }
    });

    logger.info('Error monitoring initialized');
    return Sentry;
  }

  return null;
};

module.exports = { initErrorMonitoring };
```

### Testing Error Handling

Create `tests/errorHandling.test.js`:

```javascript
const request = require('supertest');
const app = require('../src/app');

describe('Error Handling Tests', () => {
  describe('404 Not Found', () => {
    test('Should return 404 for non-existent route', async () => {
      const response = await request(app).get('/api/v1/nonexistent');

      expect(response.status).toBe(404);
      expect(response.body.success).toBe(false);
      expect(response.body.error).toContain('not found');
    });
  });

  describe('Validation Errors', () => {
    test('Should return 422 for validation failure', async () => {
      const response = await request(app)
        .post('/api/v1/auth/register')
        .send({
          email: 'invalid-email',
          password: 'weak'
        });

      expect(response.status).toBe(422);
      expect(response.body.success).toBe(false);
      expect(response.body.details).toBeDefined();
    });
  });

  describe('Authentication Errors', () => {
    test('Should return 401 for missing token', async () => {
      const response = await request(app).get('/api/v1/auth/profile');

      expect(response.status).toBe(401);
      expect(response.body.error).toContain('token');
    });

    test('Should return 401 for invalid token', async () => {
      const response = await request(app)
        .get('/api/v1/auth/profile')
        .set('Authorization', 'Bearer invalid-token');

      expect(response.status).toBe(401);
    });
  });

  describe('Resource Not Found', () => {
    test('Should return 404 for non-existent user', async () => {
      const response = await request(app)
        .get('/api/v1/users/00000000-0000-0000-0000-000000000000')
        .set('Authorization', 'Bearer VALID_ADMIN_TOKEN');

      expect(response.status).toBe(404);
      expect(response.body.error).toContain('not found');
    });
  });

  describe('Conflict Errors', () => {
    test('Should return 409 for duplicate email', async () => {
      // First registration
      await request(app)
        .post('/api/v1/auth/register')
        .send({
          email: 'duplicate@example.com',
          username: 'user1',
          password: 'SecurePass123!',
          firstName: 'John',
          lastName: 'Doe'
        });

      // Duplicate registration
      const response = await request(app)
        .post('/api/v1/auth/register')
        .send({
          email: 'duplicate@example.com',
          username: 'user2',
          password: 'SecurePass123!',
          firstName: 'Jane',
          lastName: 'Doe'
        });

      expect(response.status).toBe(409);
      expect(response.body.error).toContain('already');
    });
  });
});
```

### Error Handling Best Practices Summary

1. **Custom error classes**: Specific error types for different scenarios
2. **Centralized handling**: Single error handler for consistent responses
3. **Error normalization**: Convert all errors to standard format
4. **Operational vs programming errors**: Different handling strategies
5. **Detailed logging**: Comprehensive error information for debugging
6. **Stack traces**: Include in development, exclude in production
7. **Error monitoring**: Integration with services like Sentry
8. **Graceful degradation**: Proper shutdown on critical errors
9. **User-friendly messages**: Clear, actionable error responses
10. **Security**: Don't expose sensitive information in errors

### Environment Variables Update

Add to `.env`:

```env
# Error Monitoring
SENTRY_DSN=your-sentry-dsn-here
```

### Production Checklist

Before deploying to production, ensure:

- [ ] All error handlers are in place
- [ ] Error monitoring service is configured
- [ ] Stack traces are disabled in production
- [ ] Sensitive information is not exposed in errors
- [ ] Unhandled rejection and exception handlers are active
- [ ] Graceful shutdown is implemented
- [ ] All routes use asyncHandler or try-catch
- [ ] Database errors are properly normalized
- [ ] Rate limiting is configured
- [ ] CORS is properly configured
- [ ] Security headers are set
- [ ] Input validation is comprehensive
- [ ] Authentication is required for protected routes
- [ ] Logging is configured for production
- [ ] Health check endpoint is available

