{"runType":"SINGLE_AGENT","runId":"89976549-1b4e-4233-84cb-fa0f347e3286-SINGLE_AGENT-1","contentTransferTokens":0,"mechanismOverheadTokens":0,"coordinationInstructionsTokens":0,"taskReasoningTokens":61683,"systemIdentityTokens":329,"interAgentTokens":0,"agentAutonomousTokens":62012,"totalTokens":62012,"cachedTokens":0,"effectiveTokens":62012,"cacheHitRate":0,"wallClockMs":217838,"agentCount":1,"apiCallCount":5,"success":true,"output":"password, user.password);

    if (!isPasswordValid) {
      throw new ApiError(401, 'Invalid credentials');
    }

    // Generate tokens
    const accessToken = this.generateAccessToken({
      id: user.id,
      email: user.email,
      role: user.role,
    });

    const refreshToken = this.generateRefreshToken({
      id: user.id,
      email: user.email,
      role: user.role,
    });

    // Save refresh token in database
    await prisma.session.create({
      data: {
        userId: user.id,
        refreshToken,
        userAgent,
        ipAddress,
        expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // 30 days
      },
    });

    // Update last login
    await this.userRepository.updateLastLogin(user.id);

    const { password: _, ...userWithoutPassword } = user;

    return {
      user: userWithoutPassword,
      tokens: {
        accessToken,
        refreshToken,
      },
    };
  }

  /**
   * Refresh access token
   */
  async refreshToken(refreshToken: string) {
    try {
      // Verify refresh token
      const decoded = jwt.verify(
        refreshToken,
        config.jwt.refreshSecret
      ) as TokenPayload;

      // Check if session exists
      const session = await prisma.session.findUnique({
        where: { refreshToken },
        include: { user: true },
      });

      if (!session) {
        throw new ApiError(401, 'Invalid refresh token');
      }

      // Check if session is expired
      if (session.expiresAt < new Date()) {
        await prisma.session.delete({ where: { id: session.id } });
        throw new ApiError(401, 'Refresh token expired');
      }

      // Check if user is still active
      if (!session.user.isActive) {
        throw new ApiError(401, 'Account is deactivated');
      }

      // Generate new access token
      const accessToken = this.generateAccessToken({
        id: session.user.id,
        email: session.user.email,
        role: session.user.role,
      });

      return { accessToken };
    } catch (error) {
      if (error instanceof jwt.JsonWebTokenError) {
        throw new ApiError(401, 'Invalid refresh token');
      }
      throw error;
    }
  }

  /**
   * Logout user
   */
  async logout(refreshToken: string) {
    await prisma.session.deleteMany({
      where: { refreshToken },
    });
  }

  /**
   * Verify email
   */
  async verifyEmail(token: string) {
    const tokenRecord = await prisma.token.findUnique({
      where: { token },
      include: { user: true },
    });

    if (!tokenRecord) {
      throw new ApiError(400, 'Invalid verification token');
    }

    if (tokenRecord.type !== 'EMAIL_VERIFICATION') {
      throw new ApiError(400, 'Invalid token type');
    }

    if (tokenRecord.expiresAt < new Date()) {
      throw new ApiError(400, 'Verification token expired');
    }

    // Update user as verified
    await prisma.$transaction([
      prisma.user.update({
        where: { id: tokenRecord.userId },
        data: { isVerified: true },
      }),
      prisma.token.delete({
        where: { id: tokenRecord.id },
      }),
    ]);

    return { message: 'Email verified successfully' };
  }

  /**
   * Request password reset
   */
  async forgotPassword(email: string) {
    const user = await this.userRepository.findByEmail(email);

    if (!user) {
      // Don't reveal if email exists
      return {
        message: 'If the email exists, a reset link has been sent',
      };
    }

    // Generate reset token
    const resetToken = crypto.randomBytes(32).toString('hex');

    await prisma.token.create({
      data: {
        userId: user.id,
        type: 'PASSWORD_RESET',
        token: resetToken,
        expiresAt: new Date(Date.now() + 60 * 60 * 1000), // 1 hour
      },
    });

    // TODO: Send password reset email
    // await this.sendPasswordResetEmail(user.email, resetToken);

    return {
      message: 'If the email exists, a reset link has been sent',
    };
  }

  /**
   * Reset password
   */
  async resetPassword(token: string, newPassword: string) {
    const tokenRecord = await prisma.token.findUnique({
      where: { token },
      include: { user: true },
    });

    if (!tokenRecord) {
      throw new ApiError(400, 'Invalid reset token');
    }

    if (tokenRecord.type !== 'PASSWORD_RESET') {
      throw new ApiError(400, 'Invalid token type');
    }

    if (tokenRecord.expiresAt < new Date()) {
      throw new ApiError(400, 'Reset token expired');
    }

    // Hash new password
    const hashedPassword = await bcrypt.hash(newPassword, 10);

    // Update password and delete token
    await prisma.$transaction([
      prisma.user.update({
        where: { id: tokenRecord.userId },
        data: { password: hashedPassword },
      }),
      prisma.token.delete({
        where: { id: tokenRecord.id },
      }),
      // Invalidate all sessions
      prisma.session.deleteMany({
        where: { userId: tokenRecord.userId },
      }),
    ]);

    return { message: 'Password reset successfully' };
  }

  /**
   * Generate access token
   */
  private generateAccessToken(payload: TokenPayload): string {
    return jwt.sign(payload, config.jwt.secret, {
      expiresIn: config.jwt.expiresIn,
    });
  }

  /**
   * Generate refresh token
   */
  private generateRefreshToken(payload: TokenPayload): string {
    return jwt.sign(payload, config.jwt.refreshSecret, {
      expiresIn: config.jwt.refreshExpiresIn,
    });
  }
}
