### Auth Controller

Create `src/controllers/auth.controller.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { AuthService } from '../services/auth.service';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiResponse } from '../utils/ApiResponse';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  /**
   * Register new user
   */
  register = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const result = await this.authService.register(req.body);

      res.status(201).json(
        new ApiResponse(201, result, 'User registered successfully')
      );
    }
  );

  /**
   * Login user
   */
  login = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { email, password } = req.body;
      const userAgent = req.get('user-agent');
      const ipAddress = req.ip;

      const result = await this.authService.login(
        email,
        password,
        userAgent,
        ipAddress
      );

      res.json(new ApiResponse(200, result, 'Login successful'));
    }
  );

  /**
   * Refresh access token
   */
  refreshToken = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { refreshToken } = req.body;

      const result = await this.authService.refreshToken(refreshToken);

      res.json(new ApiResponse(200, result, 'Token refreshed successfully'));
    }
  );

  /**
   * Logout user
   */
  logout = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { refreshToken } = req.body;

      await this.authService.logout(refreshToken);

      res.json(new ApiResponse(200, null, 'Logout successful'));
    }
  );

  /**
   * Verify email
   */
  verifyEmail = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { token } = req.params;

      const result = await this.authService.verifyEmail(token);

      res.json(new ApiResponse(200, result, 'Email verified successfully'));
    }
  );

  /**
   * Request password reset
   */
  forgotPassword = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { email } = req.body;

      const result = await this.authService.forgotPassword(email);

      res.json(new ApiResponse(200, result, 'Password reset email sent'));
    }
  );

  /**
   * Reset password
   */
  resetPassword = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { token, password } = req.body;

      const result = await this.authService.resetPassword(token, password);

      res.json(new ApiResponse(200, result, 'Password reset successfully'));
    }
  );
}
