Error handling is critical for production-ready REST APIs. Proper error management improves debugging, provides clear feedback to clients, and prevents sensitive information leakage.

### 7.1 Custom Error Classes

Create structured error classes for different scenarios:

```javascript
// errors/AppError.js
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, errors = []) {
    super(message, 400);
    this.errors = errors;
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized access') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Access forbidden') {
    super(message, 403);
  }
}

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  UnauthorizedError,
  ForbiddenError
};
```

### 7.2 Global Error Handler Middleware

Implement a centralized error handler:

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;
  error.statusCode = err.statusCode || 500;

  // Log error for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method
  });

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => e.message);
    error.message = 'Validation failed';
    error.statusCode = 400;
    error.errors = errors;
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    error.message = `${field} already exists`;
    error.statusCode = 409;
  }

  // Mongoose cast error (invalid ObjectId)
  if (err.name === 'CastError') {
    error.message = 'Resource not found';
    error.statusCode = 404;
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    error.message = 'Invalid token';
    error.statusCode = 401;
  }

  if (err.name === 'TokenExpiredError') {
    error.message = 'Token expired';
    error.statusCode = 401;
  }

  // Send response
  res.status(error.statusCode).json({
    success: false,
    error: error.message,
    ...(error.errors && { errors: error.errors }),
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

module.exports = errorHandler;
```

### 7.3 Async Error Wrapper

Handle async errors without try-catch blocks everywhere:

```javascript
// utils/asyncHandler.js
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = asyncHandler;

// Usage in routes
const asyncHandler = require('../utils/asyncHandler');

router.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await User.findById(req.params.id);
  if (!user) {
    throw new NotFoundError('User');
  }
  res.json({ success: true, data: user });
}));
```

### 7.4 404 Handler

Handle undefined routes:

```javascript
// middleware/notFound.js
const notFound = (req, res, next) => {
  const error = new Error(`Route not found - ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
};

module.exports = notFound;
```

### 7.5 Integration in app.js

Wire everything together:

```javascript
const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

const app = express();

// Routes
app.use('/api/users', userRoutes);
app.use('/api/posts', postRoutes);

// 404 handler (must be after all routes)
app.use(notFound);

// Global error handler (must be last)
app.use(errorHandler);

module.exports = app;
```

### 7.6 Production Best Practices

**Environment-Specific Responses:**
```javascript
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    success: false,
    error: err.message,
    stack: err.stack,
    details: err
  });
};

const sendErrorProd = (err, res) => {
  // Only send operational errors to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      success: false,
      error: err.message
    });
  } else {
    // Programming or unknown errors: don't leak details
    console.error('ERROR 💥', err);
    res.status(500).json({
      success: false,
      error: 'Something went wrong'
    });
  }
};
```

**Error Logging:**
```javascript
// Use logging libraries like Winston or Pino
const winston = require('winston');

const logger = winston.createLogger({
  level: 'error',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// In error handler
logger.error(err.message, {
  statusCode: err.statusCode,
  stack: err.stack,
  url: req.originalUrl
});
```

### 7.7 Client-Friendly Error Responses

Maintain consistent error response format:

```javascript
{
  "success": false,
  "error": "User not found",
  "statusCode": 404,
  "timestamp": "2024-01-15T10:30:00Z",
  "path": "/api/users/123"
}
```

With validation errors:
```javascript
{
  "success": false,
  "error": "Validation failed",
  "statusCode": 400,
  "errors": [
    "Email is required",
    "Password must be at least 8 characters"
  ]
}
```

### Key Takeaways

✅ Use custom error classes for different error types  
✅ Implement centralized error handling middleware  
✅ Wrap async functions to catch errors automatically  
✅ Handle 404s for undefined routes  
✅ Never expose sensitive information in production  
✅ Log errors for monitoring and debugging  
✅ Return consistent, client-friendly error responses  
✅ Distinguish between operational and programming errors

