{"runType":"SINGLE_AGENT","runId":"89976549-1b4e-4233-84cb-fa0f347e3286-SINGLE_AGENT-2","contentTransferTokens":0,"mechanismOverheadTokens":0,"coordinationInstructionsTokens":0,"taskReasoningTokens":61668,"systemIdentityTokens":331,"interAgentTokens":0,"agentAutonomousTokens":61999,"totalTokens":61999,"cachedTokens":0,"effectiveTokens":61999,"cacheHitRate":0,"wallClockMs":222883,"agentCount":1,"apiCallCount":5,"success":true,"output":" piresIn,
    });

    // Generate refresh token
    const refreshToken = jwt.sign(payload, config.jwt.refreshSecret, {
      expiresIn: config.jwt.refreshExpiresIn,
    });

    // Store refresh token in database
    const expiresAt = new Date(
      Date.now() + this.parseExpiry(config.jwt.refreshExpiresIn)
    );

    await prisma.refreshToken.create({
      data: {
        token: refreshToken,
        userId: payload.id,
        expiresAt,
      },
    });

    return { accessToken, refreshToken };
  }

  /**
   * Parse JWT expiry string to milliseconds
   */
  private parseExpiry(expiry: string): number {
    const unit = expiry.slice(-1);
    const value = parseInt(expiry.slice(0, -1));

    switch (unit) {
      case 'd':
        return value * 24 * 60 * 60 * 1000;
      case 'h':
        return value * 60 * 60 * 1000;
      case 'm':
        return value * 60 * 1000;
      default:
        return value * 1000;
    }
  }
}
```

### Auth Controller

Create `src/controllers/auth.controller.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { AuthService } from '../services/auth.service';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiResponse } from '../utils/ApiResponse';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  /**
   * Register new user
   */
  register = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const result = await this.authService.register(req.body);

      res.status(201).json(
        new ApiResponse(201, result, 'User registered successfully')
      );
    }
  );

  /**
   * Login user
   */
  login = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { email, password } = req.body;
      const result = await this.authService.login(email, password);

      res.json(
        new ApiResponse(200, result, 'Login successful')
      );
    }
  );

  /**
   * Refresh token
   */
  refreshToken = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { refreshToken } = req.body;
      const result = await this.authService.refreshToken(refreshToken);

      res.json(
        new ApiResponse(200, result, 'Token refreshed successfully')
      );
    }
  );

  /**
   * Logout user
   */
  logout = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { refreshToken } = req.body;
      await this.authService.logout(refreshToken);

      res.json(
        new ApiResponse(200, null, 'Logout successful')
      );
    }
  );

  /**
   * Forgot password
   */
  forgotPassword = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { email } = req.body;
      const result = await this.authService.forgotPassword(email);

      res.json(
        new ApiResponse(200, result, 'Password reset email sent')
      );
    }
  );

  /**
   * Reset password
   */
  resetPassword = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { token, password } = req.body;
      const result = await this.authService.resetPassword(token, password);

      res.json(
        new ApiResponse(200, result, 'Password reset successful')
      );
    }
  );

  /**
   * Verify email
   */
  verifyEmail = asyncHandler(
    async (req: Request, res: Response, next: NextFunction) => {
      const { token } = req.params;
      const result = await this.authService.verifyEmail(token);

      res.json(
        new ApiResponse(200, result, 'Email verified successfully')
      );
    }
  );
}
```

### OAuth Integration (Google Example)

Install dependencies:

```bash
npm install passport passport-google-oauth20
npm install -D @types/passport @types/passport-google-oauth20
```

Create `src/config/passport.ts`:

```typescript
import passport from 'passport';
import { Strategy as GoogleStrategy } from 'passport-google-oauth20';
import { config } from './environment';
import { UserRepository } from '../repositories/user.repository';

const userRepository = new UserRepository();

passport.use(
  new GoogleStrategy(
    {
      clientID: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      callbackURL: '/api/v1/auth/google/callback',
    },
    async (accessToken, refreshToken, profile, done) => {
      try {
        // Check if user exists
        let user = await userRepository.findByEmail(profile.emails![0].value);

        if (!user) {
          // Create new user
          user = await userRepository.create({
            email: profile.emails![0].value,
            username: profile.emails![0].value.split('@')[0],
            password: '', // No password for OAuth users
            firstName: profile.name?.givenName,
            lastName: profile.name?.familyName,
            avatar: profile.photos?.[0].value,
            isEmailVerified: true,
          });
        }

        done(null, user);
      } catch (error) {
        done(error as Error);
      }
    }
  )
);

export default passport;
```

Add OAuth routes:

```typescript
// In auth.routes.ts
import passport from '../config/passport';

router.get(
  '/google',
  passport.authenticate('google', { scope: ['profile', 'email'] })
);

router.get(
  '/google/callback',
  passport.authenticate('google', { session: false }),
  authController.oauthCallback
);
```

### Two-Factor Authentication (2FA)

Install dependencies:

```bash
npm install speakeasy qrcode
npm install -D @types/speakeasy @types/qrcode
```

Add to user schema:

```prisma
model User {
  // ... existing fields
  twoFactorSecret   String?
  twoFactorEnabled  Boolean @default(false)
}
```

Create 2FA service:

```typescript
import speakeasy from 'speakeasy';
import QRCode from 'qrcode';

export class TwoFactorService {
  /**
   * Generate 2FA secret
   */
  async generateSecret(email: string) {
    const secret = speakeasy.generateSecret({
      name: `YourApp (${email})`,
      length: 32,
    });

    const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url!);

    return {
      secret: secret.base32,
      qrCode: qrCodeUrl,
    };
  }

  /**
   * Verify 2FA token
   */
  verifyToken(secret: string, token: string): boolean {
    return speakeasy.totp.verify({
      secret,
      encoding: 'base32',
      token,
      window: 2,
    });
  }
}
```

