Error handling is the final critical piece of a production-ready REST API. Proper error handling ensures your API fails gracefully, provides meaningful feedback to clients, and helps with debugging and monitoring.

### 7.1 Custom Error Classes

Create a hierarchy of custom error classes for different error types:

```javascript
// errors/AppError.js
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, errors = []) {
    super(message, 400);
    this.errors = errors;
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Forbidden') {
    super(message, 403);
  }
}

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  UnauthorizedError,
  ForbiddenError
};
```

### 7.2 Global Error Handler Middleware

Implement a centralized error handler that catches all errors:

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;
  error.statusCode = err.statusCode || 500;

  // Log error for debugging
  console.error(err);

  // Mongoose bad ObjectId
  if (err.name === 'CastError') {
    error.message = 'Resource not found';
    error.statusCode = 404;
  }

  // Mongoose duplicate key
  if (err.code === 11000) {
    error.message = 'Duplicate field value entered';
    error.statusCode = 400;
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => e.message);
    error.message = 'Validation failed';
    error.statusCode = 400;
    error.errors = errors;
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    error.message = 'Invalid token';
    error.statusCode = 401;
  }

  if (err.name === 'TokenExpiredError') {
    error.message = 'Token expired';
    error.statusCode = 401;
  }

  // Send response
  res.status(error.statusCode).json({
    success: false,
    error: error.message,
    ...(error.errors && { errors: error.errors }),
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

module.exports = errorHandler;
```

### 7.3 Async Error Wrapper

Create a utility to handle async errors without try-catch blocks:

```javascript
// utils/asyncHandler.js
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = asyncHandler;

// Usage in routes
const asyncHandler = require('../utils/asyncHandler');
const { NotFoundError } = require('../errors/AppError');

router.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await User.findById(req.params.id);

  if (!user) {
    throw new NotFoundError('User');
  }

  res.json({ success: true, data: user });
}));
```

### 7.4 404 Handler

Handle routes that don't exist:

```javascript
// middleware/notFound.js
const { NotFoundError } = require('../errors/AppError');

const notFound = (req, res, next) => {
  next(new NotFoundError(`Route ${req.originalUrl}`));
};

module.exports = notFound;
```

### 7.5 Error Logging and Monitoring

Integrate error logging for production monitoring:

```javascript
// utils/logger.js
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

module.exports = logger;

// Enhanced error handler with logging
const logger = require('../utils/logger');

const errorHandler = (err, req, res, next) => {
  // Log error details
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id
  });

  // ... rest of error handling
};
```

### 7.6 Unhandled Rejections and Exceptions

Handle uncaught errors at the process level:

```javascript
// server.js
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});
```

### 7.7 Complete Integration

Wire everything together in your main app file:

```javascript
// app.js
const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

const app = express();

// Body parser
app.use(express.json());

// Routes
app.use('/api/v1/users', userRoutes);
app.use('/api/v1/posts', postRoutes);

// 404 handler (must be after all routes)
app.use(notFound);

// Global error handler (must be last)
app.use(errorHandler);

module.exports = app;
```

### 7.8 Best Practices

1. **Distinguish operational vs programming errors**: Only send user-friendly messages for operational errors
2. **Never expose stack traces in production**: Include them only in development
3. **Use appropriate HTTP status codes**: 4xx for client errors, 5xx for server errors
4. **Log all errors**: Use a logging service for production monitoring
5. **Fail fast**: Don't continue processing after critical errors
6. **Provide actionable error messages**: Help clients understand what went wrong and how to fix it
7. **Monitor error rates**: Set up alerts for unusual error patterns
8. **Test error scenarios**: Include error cases in your test suite

### 7.9 Example Error Responses

**Validation Error:**
```json
{
  "success": false,
  "error": "Validation failed",
  "errors": [
    "Email is required",
    "Password must be at least 8 characters"
  ]
}
```

**Not Found Error:**
```json
{
  "success": false,
  "error": "User not found"
}
```

**Server Error:**
```json
{
  "success": false,
  "error": "Internal server error"
}
```

