### Custom Validators

Create `src/validators/custom.validators.ts`:

```typescript
import { body, CustomValidator } from 'express-validator';
import { prisma } from '../config/database';

/**
 * Check if email is unique
 */
export const isEmailUnique: CustomValidator = async (email, { req }) => {
  const user = await prisma.user.findUnique({ where: { email } });

  // If updating, allow same email for same user
  if (user && user.id !== req.user?.id) {
    throw new Error('Email already in use');
  }

  return true;
};

/**
 * Check if slug is unique
 */
export const isSlugUnique: CustomValidator = async (slug, { req }) => {
  const product = await prisma.product.findUnique({ where: { slug } });

  if (product && product.id !== req.params?.id) {
    throw new Error('Slug already in use');
  }

  return true;
};

/**
 * Validate password confirmation
 */
export const passwordsMatch: CustomValidator = (value, { req }) => {
  if (value !== req.body.password) {
    throw new Error('Passwords do not match');
  }
  return true;
};

/**
 * Validate date range
 */
export const isValidDateRange: CustomValidator = (endDate, { req }) => {
  const startDate = new Date(req.body.startDate);
  const end = new Date(endDate);

  if (end <= startDate) {
    throw new Error('End date must be after start date');
  }

  return true;
};

/**
 * Validate file upload
 */
export const isValidImage: CustomValidator = (value) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
  const maxSize = 5 * 1024 * 1024; // 5MB

  if (!allowedTypes.includes(value.mimetype)) {
    throw new Error('Invalid file type. Only JPEG, PNG, and WebP are allowed');
  }

  if (value.size > maxSize) {
    throw new Error('File size must be less than 5MB');
  }

  return true;
};

// Usage example
export const registerValidation = [
  body('email')
    .isEmail()
    .normalizeEmail()
    .custom(isEmailUnique),

  body('password')
    .isLength({ min: 8 }),

  body('confirmPassword')
    .custom(passwordsMatch),
];
```

