Error handling is critical for production-ready REST APIs. Proper error management improves debugging, provides clear feedback to clients, and prevents sensitive information leakage.

### 7.1 Custom Error Classes

Create structured error classes for different scenarios:

```javascript
// errors/AppError.js
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, errors = []) {
    super(message, 400);
    this.errors = errors;
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized access') {
    super(message, 401);
  }
}

module.exports = { AppError, ValidationError, NotFoundError, UnauthorizedError };
```

### 7.2 Global Error Handler Middleware

Implement a centralized error handler that catches all errors:

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;
  error.statusCode = err.statusCode || 500;

  // Log error for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method
  });

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => e.message);
    error.message = 'Validation failed';
    error.statusCode = 400;
    error.errors = errors;
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    error.message = `${field} already exists`;
    error.statusCode = 409;
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    error.message = 'Invalid token';
    error.statusCode = 401;
  }

  if (err.name === 'TokenExpiredError') {
    error.message = 'Token expired';
    error.statusCode = 401;
  }

  // Send response
  res.status(error.statusCode).json({
    success: false,
    error: error.message,
    ...(error.errors && { errors: error.errors }),
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

module.exports = errorHandler;
```

### 7.3 Async Error Wrapper

Wrap async route handlers to catch errors automatically:

```javascript
// utils/asyncHandler.js
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = asyncHandler;

// Usage in routes
const asyncHandler = require('../utils/asyncHandler');

router.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await User.findById(req.params.id);
  if (!user) {
    throw new NotFoundError('User');
  }
  res.json({ success: true, data: user });
}));
```

### 7.4 404 Handler

Handle undefined routes:

```javascript
// middleware/notFound.js
const notFound = (req, res, next) => {
  const error = new Error(`Route not found - ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
};

module.exports = notFound;
```

### 7.5 Integration in app.js

Wire everything together:

```javascript
const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

const app = express();

// Routes
app.use('/api/users', userRoutes);
app.use('/api/posts', postRoutes);

// 404 handler (must be after all routes)
app.use(notFound);

// Global error handler (must be last)
app.use(errorHandler);

module.exports = app;
```

### 7.6 Production Best Practices

**Environment-specific responses:**
```javascript
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    success: false,
    error: err.message,
    stack: err.stack,
    details: err
  });
};

const sendErrorProd = (err, res) => {
  // Only send operational errors to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      success: false,
      error: err.message
    });
  } else {
    // Log programming errors but send generic message
    console.error('ERROR:', err);
    res.status(500).json({
      success: false,
      error: 'Something went wrong'
    });
  }
};
```

**Error logging service integration:**
```javascript
// Use services like Sentry, LogRocket, or Winston
const Sentry = require('@sentry/node');

if (process.env.NODE_ENV === 'production') {
  Sentry.init({ dsn: process.env.SENTRY_DSN });
  app.use(Sentry.Handlers.errorHandler());
}
```

### 7.7 Testing Error Handling

```javascript
// tests/errorHandler.test.js
describe('Error Handler', () => {
  it('should handle 404 errors', async () => {
    const res = await request(app)
      .get('/api/nonexistent')
      .expect(404);

    expect(res.body.success).toBe(false);
    expect(res.body.error).toContain('not found');
  });

  it('should handle validation errors', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ email: 'invalid' })
      .expect(400);

    expect(res.body.success).toBe(false);
  });

  it('should not leak stack traces in production', async () => {
    process.env.NODE_ENV = 'production';
    const res = await request(app)
      .get('/api/error')
      .expect(500);

    expect(res.body.stack).toBeUndefined();
  });
});
```

### Key Takeaways

✅ **Centralized error handling** - Single source of truth for error responses  
✅ **Custom error classes** - Structured, predictable error objects  
✅ **Async error handling** - Automatic error catching in async routes  
✅ **Environment awareness** - Different error details for dev vs production  
✅ **Security** - Never expose sensitive data or stack traces in production  
✅ **Logging** - Track errors for debugging and monitoring  
