### Custom Validation Rules

Create `src/validators/custom.validator.ts`:

```typescript
import Joi from 'joi';

// Custom validator for file uploads
export const fileValidator = Joi.object({
  fieldname: Joi.string().required(),
  originalname: Joi.string().required(),
  encoding: Joi.string().required(),
  mimetype: Joi.string()
    .valid(
      'image/jpeg',
      'image/png',
      'image/gif',
      'image/webp',
      'application/pdf'
    )
    .required()
    .messages({
      'any.only': 'Invalid file type. Only JPEG, PNG, GIF, WebP, and PDF are allowed',
    }),
  size: Joi.number()
    .max(5 * 1024 * 1024) // 5MB
    .required()
    .messages({
      'number.max': 'File size cannot exceed 5MB',
    }),
});

// Custom validator for date ranges
export const dateRangeValidator = Joi.object({
  startDate: Joi.date().iso().required(),
  endDate: Joi.date()
    .iso()
    .greater(Joi.ref('startDate'))
    .required()
    .messages({
      'date.greater': 'End date must be after start date',
    }),
});

// Custom validator for pagination
export const paginationValidator = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  sortBy: Joi.string().optional(),
  sortOrder: Joi.string().valid('asc', 'desc').default('desc'),
});

// Custom validator for search
export const searchValidator = Joi.object({
  q: Joi.string().min(2).max(100).required().messages({
    'string.min': 'Search query must be at least 2 characters',
    'string.max': 'Search query cannot exceed 100 characters',
  }),
  fields: Joi.array()
    .items(Joi.string())
    .optional()
    .default(['title', 'content']),
});
```

