import Joi from 'joi';

export const conditionalValidators = {
  // Validate based on user role
  userUpdate: Joi.object({
    email: Joi.string().email().optional(),
    role: Joi.when('$userRole', {
      is: 'ADMIN',
      then: Joi.string().valid('USER', 'ADMIN', 'MODERATOR'),
      otherwise: Joi.forbidden(),
    }),
    isActive: Joi.when('$userRole', {
      is: 'ADMIN',
      then: Joi.boolean(),
      otherwise: Joi.forbidden(),
    }),
  }),

  // Validate based on field value
  postCreate: Joi.object({
    title: Joi.string().required(),
    content: Joi.string().required(),
    published: Joi.boolean().default(false),
    publishedAt: Joi.when('published', {
      is: true,
      then: Joi.date().iso().required(),
      otherwise: Joi.forbidden(),
    }),
  }),
};
