### Sanitization

Create `src/validators/sanitizers.ts`:

```typescript
import Joi from 'joi';

// Email sanitization
export const sanitizeEmail = (email: string): string => {
  return email.toLowerCase().trim();
};

// String sanitization
export const sanitizeString = (str: string): string => {
  return str.trim().replace(/\s+/g, ' ');
};

// HTML sanitization
export const sanitizeHTML = (html: string): string => {
  // Use a library like DOMPurify for production
  return html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
};

// Custom Joi extension for sanitization
export const JoiWithSanitization = Joi.extend((joi) => ({
  type: 'string',
  base: joi.string(),
  messages: {
    'string.sanitize': '{{#label}} contains invalid characters',
  },
  rules: {
    sanitize: {
      method() {
        return this.$_addRule({ name: 'sanitize' });
      },
      validate(value, helpers) {
        const sanitized = sanitizeString(value);
        if (sanitized !== value) {
          return helpers.error('string.sanitize');
        }
        return sanitized;
      },
    },
  },
}));
```

