## Section 7: Error Handling

### Centralized Error Handling

### Custom Error Classes

Create `src/utils/ApiError.ts`:

```typescript
export class ApiError extends Error {
  statusCode: number;
  isOperational: boolean;
  errors?: any[];

  constructor(
    statusCode: number,
    message: string,
    errors?: any[],
    isOperational = true,
    stack = ''
  ) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.errors = errors;

    if (stack) {
      this.stack = stack;
    } else {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// Specific error classes
export class ValidationError extends ApiError {
  constructor(message: string, errors?: any[]) {
    super(400, message, errors);
  }
}

export class AuthenticationError extends ApiError {
  constructor(message = 'Authentication failed') {
    super(401, message);
  }
}

export class AuthorizationError extends ApiError {
  constructor(message = 'Access denied') {
    super(403, message);
  }
}

export class NotFoundError extends ApiError {
  constructor(resource = 'Resource') {
    super(404, `${resource} not found`);
  }
}

export class ConflictError extends ApiError {
  constructor(message: string) {
    super(409, message);
  }
}

export class RateLimitError extends ApiError {
  constructor(message = 'Too many requests') {
    super(429, message);
  }
}

export class InternalServerError extends ApiError {
  constructor(message = 'Internal server error') {
    super(500, message, [], false);
  }
}
```

### Error Handler Middleware

Create `src/middleware/error.middleware.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { ApiError } from '../utils/ApiError';
import { logger } from '../config/logger';
import { config } from '../config/environment';
import { Prisma } from '@prisma/client';

export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
) => {
  let error = err;

  // Log error
  logger.error(`Error: ${err.message}`, {
    error: err,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id,
  });

  // Convert known errors to ApiError
  if (!(error instanceof ApiError)) {
    // Prisma errors
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      error = handlePrismaError(error);
    }
    // Prisma validation errors
    else if (error instanceof Prisma.PrismaClientValidationError) {
      error = new ApiError(400, 'Invalid data provided');
    }
    // JWT errors
    else if (error.name === 'JsonWebTokenError') {
      error = new ApiError(401, 'Invalid token');
    } else if (error.name === 'TokenExpiredError') {
      error = new ApiError(401, 'Token expired');
    }
    // Multer errors (file upload)
    else if (error.name === 'MulterError') {
      error = handleMulterError(error as any);
    }
    // Generic errors
    else {
      error = new ApiError(
        500,
        config.env === 'production'
          ? 'Internal server error'
          : err.message,
        [],
        false
      );
    }
  }

  const apiError = error as ApiError;

  // Prepare error response
  const response: any = {
    status: 'error',
    statusCode: apiError.statusCode,
    message: apiError.message,
  };

  // Add errors array if present
  if (apiError.errors && apiError.errors.length > 0) {
    response.errors = apiError.errors;
  }

  // Add stack trace in development
  if (config.env === 'development') {
    response.stack = apiError.stack;
  }

  // Send response
  res.status(apiError.statusCode).json(response);
};

// Handle Prisma errors
const handlePrismaError = (
  error: Prisma.PrismaClientKnownRequestError
): ApiError => {
  switch (error.code) {
    case 'P2002':
      // Unique constraint violation
      const field = (error.meta?.target as string[])?.[0] || 'field';
      return new ApiError(409, `${field} already exists`);

    case 'P2025':
      // Record not found
      return new ApiError(404, 'Record not found');

    case 'P2003':
      // Foreign key constraint violation
      return new ApiError(400, 'Related record not found');

    case 'P2014':
      // Invalid ID
      return new ApiError(400, 'Invalid ID provided');

    default:
      return new ApiError(500, 'Database error occurred');
  }
};

// Handle Multer errors
const handleMulterError = (error: any): ApiError => {
  if (error.code === 'LIMIT_FILE_SIZE') {
    return new ApiError(400, 'File size too large');
  }
  if (error.code === 'LIMIT_FILE_COUNT') {
    return new ApiError(400, 'Too many files');
  }
  if (error.code === 'LIMIT_UNEXPECTED_FILE') {
    return new ApiError(400, 'Unexpected file field');
  }
  return new ApiError(400, error.message);
};

// 404 handler
export const notFoundHandler = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  const error = new ApiError(404, `Route ${req.originalUrl} not found`);
  next(error);
};

// Async error wrapper
export const catchAsync = (fn: Function) => {
  return (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};
```

