Building on the previous sections (Project Setup, Routing, Middleware, Database, Authentication, and Validation), proper error handling is the final critical component that ensures your REST API is truly production-ready. A robust error handling strategy provides clear feedback to clients, protects sensitive information, and makes debugging easier.

### 7.1 Custom Error Classes

Create a hierarchy of custom error classes to represent different error scenarios:

```javascript
// errors/AppError.js
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, errors = []) {
    super(message, 400);
    this.errors = errors;
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized access') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Access forbidden') {
    super(message, 403);
  }
}

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  UnauthorizedError,
  ForbiddenError
};
```

### 7.2 Global Error Handler Middleware

Implement a centralized error handler that catches all errors:

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;
  error.statusCode = err.statusCode || 500;

  // Log error for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => e.message);
    error = new ValidationError('Validation failed', errors);
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    error = new AppError(`${field} already exists`, 400);
  }

  // Mongoose cast error (invalid ID)
  if (err.name === 'CastError') {
    error = new NotFoundError('Resource');
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    error = new UnauthorizedError('Invalid token');
  }

  if (err.name === 'TokenExpiredError') {
    error = new UnauthorizedError('Token expired');
  }

  // Send response
  res.status(error.statusCode).json({
    success: false,
    status: error.status || 'error',
    message: error.message,
    ...(error.errors && { errors: error.errors }),
    ...(process.env.NODE_ENV === 'development' && { 
      stack: err.stack,
      originalError: err 
    })
  });
};

module.exports = errorHandler;
```

### 7.3 Async Error Wrapper

Create a utility to handle async errors without try-catch blocks:

```javascript
// utils/asyncHandler.js
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = asyncHandler;

// Usage in routes
const asyncHandler = require('../utils/asyncHandler');

router.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await User.findById(req.params.id);
  if (!user) {
    throw new NotFoundError('User');
  }
  res.json({ success: true, data: user });
}));
```

### 7.4 404 Handler

Handle routes that don't exist:

```javascript
// middleware/notFound.js
const { NotFoundError } = require('../errors/AppError');

const notFound = (req, res, next) => {
  next(new NotFoundError(`Route ${req.originalUrl}`));
};

module.exports = notFound;
```

### 7.5 Integration in Express App

Wire everything together in your main application file:

```javascript
// app.js
const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

const app = express();

// ... middleware, routes, etc.

// 404 handler (must be after all routes)
app.use(notFound);

// Global error handler (must be last)
app.use(errorHandler);

module.exports = app;
```

### 7.6 Graceful Shutdown

Handle uncaught exceptions and unhandled rejections:

```javascript
// server.js
const app = require('./app');

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated');
  });
});
```

### 7.7 Error Logging and Monitoring

Integrate professional logging for production:

```javascript
// utils/logger.js
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

module.exports = logger;

// Use in error handler
const logger = require('../utils/logger');

const errorHandler = (err, req, res, next) => {
  logger.error({
    message: err.message,
    statusCode: err.statusCode,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // ... rest of error handling
};
```

### 7.8 Best Practices

1. **Never expose sensitive information** in error messages (stack traces, database details)
2. **Use appropriate HTTP status codes** (400 for client errors, 500 for server errors)
3. **Log all errors** with sufficient context for debugging
4. **Distinguish operational vs programming errors** - only operational errors should be sent to clients
5. **Implement rate limiting** on error-prone endpoints to prevent abuse
6. **Monitor error rates** in production using tools like Sentry, New Relic, or DataDog
7. **Provide helpful error messages** that guide users on how to fix issues
8. **Test error scenarios** thoroughly in your test suite

### Conclusion

With comprehensive error handling in place, your REST API is now production-ready. This seven-section guide has covered all essential aspects: from initial project setup through routing, middleware, database integration, authentication, validation, and finally error handling. Each component works together to create a secure, maintainable, and robust API that can handle real-world production traffic.

