### Error Response Standardization

Create `src/utils/responseFormatter.ts`:

```typescript
export interface SuccessResponse<T = any> {
  status: 'success';
  data: T;
  meta?: {
    page?: number;
    limit?: number;
    total?: number;
    [key: string]: any;
  };
  timestamp: string;
}

export interface ErrorResponse {
  status: 'error';
  message: string;
  code?: string;
  errors?: any[];
  requestId?: string;
  timestamp: string;
}

export class ResponseFormatter {
  static success<T>(data: T, meta?: any): SuccessResponse<T> {
    return {
      status: 'success',
      data,
      meta,
      timestamp: new Date().toISOString()
    };
  }

  static error(
    message: string,
    code?: string,
    errors?: any[],
    requestId?: string
  ): ErrorResponse {
    return {
      status: 'error',
      message,
      code,
      errors,
      requestId,
      timestamp: new Date().toISOString()
    };
  }

  static paginated<T>(
    data: T[],
    page: number,
    limit: number,
    total: number
  ): SuccessResponse<T[]> {
    return {
      status: 'success',
      data,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        hasNext: page * limit < total,
        hasPrev: page > 1
      },
      timestamp: new Date().toISOString()
    };
  }
}
```

### Complete Server Setup with Error Handling

Update `src/server.ts`:

```typescript
import express from 'express';
import helmet from 'helmet';
import { config } from './config';
import { errorHandler } from './middleware/errorHandler';
import { requestLogger } from './middleware/logger';
import { GracefulShutdown } from './utils/gracefulShutdown';
import { ErrorMonitoringService } from './services/ErrorMonitoringService';
import { logger } from './utils/logger';
import routes from './routes';
import healthRoutes from './routes/health';

// Initialize error monitoring
ErrorMonitoringService.initialize();

const app = express();

// Security and parsing
app.use(helmet());
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Logging
app.use(requestLogger);

// Health checks
app.use('/', healthRoutes);

// API routes
app.use('/api/v1', routes);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.originalUrl
  });
});

// Global error handler (must be last)
app.use(errorHandler);

// Start server
const server = app.listen(config.port, () => {
  logger.info(`Server running on port ${config.port} in ${config.env} mode`);
});

// Setup graceful shutdown
GracefulShutdown.setupHandlers(server);

export default app;
```

### Key Takeaways

- Create specific error classes for different error types
- Implement centralized error handling middleware
- Distinguish between operational and programming errors
- Use structured logging with appropriate log levels
- Implement error monitoring and alerting for production
- Provide meaningful error messages without exposing sensitive data
- Handle async errors with proper wrappers
- Implement graceful shutdown for clean process termination
- Create health check endpoints for monitoring
- Standardize response formats across the API
- Log errors with context (request ID, user, etc.)
- Handle database errors appropriately
- Never expose stack traces in production
- Implement retry logic for transient failures
- Monitor error rates and set up alerts

